INSERT INTO `abstract` (`id`, `registration_id`, `abstract_id`, `sub_theme`, `type_of_presentation`, `category_presentation`, `paper_title`, `keywords`, `paper_abstract`, `created_by`, `created_on`, `status`, `flag`) VALUES
(1, 'VIDYEN/1000021', 'AUT000001', 'Patient safety and care in dentistry', 'Oral Presentations for research submission', 'Original Research Medical / Dental Education', 'The Impact of Financial Constraints on Dental Care Utilization: A Cross-Sectional Analysis', 'cost, barriers, oral health, awareness, dental insurance, healthcare access', 'Introduction: Oral health, a crucial aspect of overall health, significantly impacts an individual\'s self-esteem and overall quality of life. Consequently, the cost of dental care can act as a barrier, potentially affecting the regularity and comprehensiveness of care sought by individuals. The study aimed to investigate the association between demographic factors and cost-related dental care avoidance and to predict the likelihood of dental care avoidance based on demographic and behavioural parameters. \r\nMaterials and methods: This cross-sectional study was conducted in Chengalpattu District, Tamil Nadu, involving 137 participants aged 21 years and above. Participants were recruited using convenience sampling. Data were collected using a 17-item self-administered questionnaire. Descriptive analysis, chi-square tests, and logistic regression models were used to analyze the data, with a significance level of p<0.05.\r\nResults: Among the participants, 39.4% of participants reported never or rarely visiting the dentist, 59.1% delayed recommended dental care in the past 12 months, and 60% avoided dental visits due to cost. Over 88.3% lacked dental insurance, and 71.5% were unaware of financial assistance programs. Educational attainment, employment status, and financial awareness significantly influenced dental care avoidance (p<0.05).\r\nConclusion: This study concluded that financial barriers, limited financial literacy and inadequate insurance coverage further complicate access to dental care, identifying cost as a significant obstacle. The study recommends targeted interventions, enhanced public dental care utilization, increased dental coverage in health insurance, and the promotion of preventive treatments to effectively mitigate these discrepancies.\r\n', 'VIDYEN/1000021', '14-08-2025', 2, 0),
(2, 'VIDYEN/1000010', 'AUT000002', 'Patient safety and care in dentistry', 'Posters', 'Narrative Review', '-Bridging Oral and Gut Health: Microbial pathways', 'microbial links, immunology ,oral health, gut health', 'Title- Bridging Oral and Gut Health: Microbial pathways\r\nThe Oral cavity and gut are intricately connected through a shared microbial ecosystem. Emerging research highlights the role of oral microbiota in influencing gut health, and vice versa, through mechanisms such as microbial translocation, immune modulation and systemic inflammation. Dysbiosis in oral cavity has been associated with gastrointestinal disorders like inflammatory bowel disease, systemic conditions linked to gut health also mental health disturbances.\r\nThis poster explores the bidirectional relationship between oral and gut microbiomes, emphasizing the importance of maintaining oral hygiene not just dental health but for overall gastrointestinal well-being and mental health. By mapping these links this review emphasizes the importance of for integrated approaches to diagnosis, prevention and treatment of both oral and gut related diseases, mental health issues and need for further research into specific microbial mechanisms and therapeutic targets.\r\n', 'VIDYEN/1000010', '30-08-2025', 2, 0),
(3, 'VIDYEN/1000022', 'AUT000003', 'Patient safety and care in dentistry', 'Oral Presentations for research submission', 'Original Research Medical / Dental Education', 'Evaluation of a questionnaire-based diabetes screening concept in South Indian population with Stage III or IV periodontitis: A practice-based study', 'Periodontitis, Finish Diabetic Risk Score, Diabetes Mellitus', 'Introduction: This pragmatic retrospective study evaluated a diabetic mellitus (DM) screening method using the Finnish diabetic Risk Score questionnaire in patients with Stage III or IV periodontitis (FINDRISC).\r\n\r\nMethods: Subjects with Stage III or IV periodontitis who underwent FINDRISC screening in a private dental college situated in India were enlisted. People with positive FINDRISC scores (≥12, FINDRISC+) were denoted for diabetological investigation. Numerous demographic and periodontal findings from the patients\' documents were verified and analysed.\r\n\r\nResults: A total of 170 subjects (50.15 ± 11.49 years) were inculpated. In diabetes mellitus examination, 23.4% (n = 44) subjects were FINDRISC+, as well as all individuals with presently diagnosed with Diabetes mellitus (21 of 21). 63.2% (12 of 19, or 7.6% of the entire cohort) of the remaining FINDRISC+ participants had a HbA1c ≥5.7%, and 82.6% (19 of 23) went to see their medical practitioner. Accordingly, 75% of the FINDRISC+ participants had diabetes mellitus, which included people with pre-existing diabetes, and were diabetologically prominent (HbA1c ≥ 5.7%).According to those who were diabetologically inconspicuous, those with a record of undiagnosed diabetes mellitus had higher mean ages, more missing teeth, advanced periodontitis stages (more Stage IV), and more frequently teeth with suppuration (P <0.01).\r\nConclusion: The FINDRISC questionnaire can be suggested in a dental practice context and is suitable for patients with Stage III or IV periodontitis.\r\nKeywords: Diabetes mellitus , Periodontitis, Finnish Diabetes Risk Score questionnaire \r\n', '', '01-09-2025', 2, 0),
(4, 'VIDYEN/1000019', 'AUT000004', 'Aligning Teaching, learning and assessment in relation to Virtual Learning', 'Oral Presentations for research submission', 'Original Research Medical / Dental Education', 'Development, Validation, and Implementation of Immersive Learning Based Teaching Learning Toolkit', 'Immersive learning, Self-directed learning, Competency', 'Introduction: Traditional classroom lectures, particularly in dentistry—a skill-intensive discipline—often fail to foster active engagement and long-term knowledge retention. Passive learning environments limit students’ ability to translate theoretical knowledge into practice, especially for psycho-social topics like behavior management, which require the development of soft skills. With the advancement of educational technology, there is an opportunity to enhance student engagement and comprehension by integrating immersive learning approaches. \r\nAim: This study was therefore designed to evaluate the effectiveness of an immersive learning toolkit in improving knowledge acquisition among third-year BDS students, specifically concerning the impact of parental attitudes on children’s behavior in dental settings.\r\nMethods:The study adopted a quasi-experimental design and was conducted in three structured phases. After obtaining ethical clearance, a detailed storyboard was developed outlining the learning objectives, key content areas, validation rubrics, and instructional flow. This served as the foundation for immersive content development. The content was reviewed and validated by a panel including subject matter experts, technical developers, and educational researchers, ensuring pedagogical rigor and technological viability. \r\nResults & Conclusion: This study demonstrated the feasibility and value of using immersive learning technologies in dental education.Overall, this project highlighted the importance of thoughtful integration of innovation into curriculum design. The effectiveness of immersive learning is not solely dependent on its novelty but on how well it aligns with learning objectives, assessment strategies, and curriculum needs. ', 'VIDYEN/1000019', '01-09-2025', 2, 0),
(5, 'VIDYEN/1000004', 'AUT000005', 'Interprofessional Practice in Virtual Learning', 'Oral Presentations for research submission', 'Original Research Medical / Dental Education', 'Integration of Oral Health with Pediatric Primary Healthcare- An Interprofessional Practice Initiative', 'Early childhood caries, Primary care, Interprofessional, Oral Health', 'Introduction:\r\nDental caries is a highly prevalent oral disease among children. The main reason for the high prevalence of ECC is the lack of awareness about pediatric oral health and its impact on overall health among all stakeholders responsible for the child\'s health, including pediatric healthcare professionals and parents/caregivers. Integrating all the stakeholders of children\'s oral health is pivotal in reducing the prevalence of dental caries in children. The present study aims to improve oral health among children aged < 6 years by equipping the pediatric health care professionals with adequate knowledge and skills to promote oral health in children and referral as required.\r\nMethodology\r\nA cross-sectional study was conducted among Pediatric healthcare professionals (PHCP), which included Pediatricians, pediatric dentists, nurses, speech therapists and dietitians. A focus group discussion was conducted to design the pediatric oral health module. Pretest was conducted before the dissemination of the oral health module. Pediatric Oral health education was provided to all the PHCP through the module. Post-test on oral health awareness was performed. The success of the integration was assessed based on the referrals the PHCP makes to the Pediatric dentist for preventive therapies \r\nResults \r\nThe average % gain in knowledge was 83.8%. Statistical tests confirm that the intervention led to a highly significant increase in knowledge. All roles benefited, with Dietitians and Speech Therapists showing the highest relative improvement. Overall knowledge improved from <30% to 100% correct.\r\n\r\nConclusions\r\nIntegration of Oral Health with Pediatric Primary Healthcare through interprofessional practice demonstrated clearly that the integration increased the oral health knowledge among the PHCP and enhanced the referrals. This project bridged the gap in awareness and practice, laying the foundation for sustainable, holistic child healthcare. \r\n', 'VIDYEN/1000004', '02-09-2025', 2, 0),
(6, 'VIDYEN/1000029', 'AUT000006', 'Blended Learning Strategies in Dental Education', 'Oral Presentations for research submission', 'Systematic Review / Metanalysis', 'Engaged Hybrid Teaching Methodology -Integrating In -Person & Remote Learning', 'Hybrid Teaching,Blended  ,In Person ', ' Introduction -Hybrid teaching is an evolving instructional approach that blends traditional face to face classroom methods with online digital tools. it leverages the strengths of both in-person interaction and virtual resources, creating a flexible and interactive learning environment for students.\r\nObjective\r\nThe primary objective of the hybrid teaching methodology is to enhance student engagement ,he primary objective of the hybrid teaching methodology is to enhance student engagement, improve learning outcomes, and provide personalized learning opportunities while ensuring accessibility and flexibility for diverse learners.\r\n\r\nMethodology\r\nThe methodology integrates classroom lectures, group discussions, and practical demonstrations with online learning platforms that include multimedia content, recorded lectures, discussion forums, and assessments. A flipped-classroom strategy and blended delivery model are applied, encouraging active participation both in physical and virtual settings.\r\n\r\nResult\r\nFindings from the application of the hybrid methodology indicate improved student performance, better conceptual understanding, and increased retention of knowledge. Students reported greater motivation, accessibility to learning materials, and opportunities for self-paced learning. Educators also observed enhanced classroom interaction and more learner-centered teaching.\r\n\r\nConclusion\r\nHybrid teaching methodology proves to be an effective pedagogical practice that balances traditional instruction with digital technology. It not only addresses the diverse needs of learners but also fosters flexibility, collaboration, and continuous academic engagement, making it a sustainable model for future education systems.', 'VIDYEN/1000029', '08-09-2025', 2, 0),
(7, 'VIDYEN/1000045', 'AUT000007', 'Speciality Presentation', 'Posters', 'Original Research Medical / Dental Education', 'Robot-Assisted Endodontic Retreatment: A Case Report with Clinical Considerations', 'Fiber post; nonsurgical endodontic retreatment; robotic system.', 'Fiber posts present significant challenges for nonsurgical endodontic retreatment, as improper removal may result in iatrogenic root perforation or even root fracture. Recently, robotic technology has attracted considerable attention in dentistry and active dental robotic (ADR) systems can perform procedures based on preset instructions, minimizing reliance on the dentist\'s experience. This case report describes the application of an ADR system for fiber post removal through an existing zirconia crown. A 26-year-old female was diagnosed with previously treated, symptomatic apical periodontitis of the mandibular left second premolar. Based on cone-beam computed tomography (CBCT) and intraoral scanning, the ADR system was used to achieve precise fiber post removal through a zirconia crown with minimally invasive coronal access under rubber dam isolation. The robotic arm executed flexible pumping motions to simulate the hand movements of dentists. This was achieved by establishing preset force and distance thresholds tailored to the characteristics of the materials being drilled. Residual gutta-percha was removed, followed by canal preparation and obturation. ', 'VIDYEN/1000045', '09-09-2025', 2, 0),
(8, 'VIDYEN/1000031', 'AUT000008', 'Speciality Presentation', 'Oral Presentations for Speciality Research', 'Original Research Medical / Dental Education', 'Beyond the Brew: Green Coffee Bean Extract as a Natural Anticariogenic and Remineralizing Agent - An In Vitro Study', 'Green Coffee Bean, Streptococcus mutans, antimicrobial activity, mineralization,  caries prevention.', 'Background:\r\nDental caries is a widespread chronic disease, largely driven by Streptococcus mutans, while Candida albicans contributes to secondary oral infections. The limitations of conventional antimicrobials, including adverse effects and resistance, have shifted the focus toward natural phytochemicals. Green Coffee Bean (Coffea arabica) is rich in bioactive compounds, including chlorogenic acids and caffeine derivatives, which may provide antimicrobial benefits and support mineralization processes relevant to dental applications.\r\nAim:\r\nTo investigate the antimicrobial activity and mineralization potential of Green Coffee Bean extract against oral pathogens.\r\nMethods:\r\nGreen Coffee Beans were shade-dried, powdered, sterilized, and subjected to ethanol extraction. Antimicrobial efficacy was assessed against S. mutans and C. albicans using disc diffusion (1000, 750, 500 µg/mL), minimum inhibitory concentration (MIC), and minimum bactericidal concentration (MBC) assays following CLSI guidelines. Zones of inhibition were measured at 24 h and 48 h. For mineralization, Saos-2 osteoblast-like cells were treated with extract concentrations of 125, 62.5, and 31.2 µg/mL and stained with Alizarin Red; mineral deposition was quantified spectrophotometrically at an optical density (OD) of 405.\r\nResults:\r\nGreen Coffee Bean extract exhibited strong antibacterial activity against S. mutans, with inhibition zones of 27 mm at 1000 µg/mL, which was sustained over 24 h and 48 h, nearly matching the antibiotic control (30 mm). MIC and MBC values were 31.2 µg/mL, confirming the bacteriostatic and bactericidal potency of the compound. Antifungal activity against C. albicans was modest, with inhibition zones ranging from 7–8 mm. In mineralization assays, the extract induced high calcium deposition in Saos-2 cells (OD405 = 0.81 ± 0.06), significantly greater than Ficus carica (p < 0.001), indicating its ability to promote in vitro mineralization.\r\nConclusion:\r\nGreen Coffee Bean extract demonstrated potent antibacterial effects against S. mutans and substantial mineralization capacity, highlighting its promise as a natural agent for caries prevention and early enamel repair. These findings suggest its potential integration into preventive oral care formulations; however, further in vivo and clinical studies are needed to confirm its safety and efficacy.\r\n', 'VIDYEN/1000031', '10-09-2025', 2, 0),
(9, 'VIDYEN/1000015', 'AUT000009', 'Technology-Driven Innovations in Dental Education', 'Oral Presentations for research submission', 'Narrative Review', 'G-Safety Latch: Redefining Restorative Training', 'Preclinical dental education, Phantom head simulation, Dental chair conversion', 'Background:\r\nPreclinical dental training relies on phantom head laboratories that replicate oral anatomy but often lack critical clinical features such as high- and low-volume suction, overhead lighting ergonomics, and infection-control protocols. Establishing dedicated preclinical facilities involves significant capital and space investment, limiting access for many institutions. This gap between simulated and real clinical environments hampers students’ development of fine motor skills, hand–eye coordination, and clinical etiquette, resulting in a steep learning curve when transitioning to patient care.\r\nAim:\r\nTo develop and patent the G-Safety Latch, an attachment that converts a standard clinical dental chair into a fully functional preclinical phantom head station, thereby minimizing infrastructure costs while providing authentic clinical environment exposure and comprehensive skill development for undergraduate and postgraduate dental students.\r\nMethod:\r\nThe G-Safety Latch comprises a precision-engineered threaded handle and groove mechanism that interfaces with existing dental chair headrest mounts. Key components include:\r\n•	A universal latch adapter designed to fit standard headrest mounting points without modification.\r\n•	A threaded ball joint system for secure phantom head attachment.\r\n•	Ergonomic alignment features to maintain clinical working angles.\r\nInstallation involves removing the chair’s headrest, securing the G-Safety Latch onto the headrest mount, and affixing a conventional phantom head via the ball joint. This setup grants access to the chair’s integrated suction systems, lighting, and instrument delivery units.\r\nResults: The implementation of the G-Safety Latch yielded significant improvements across multiple domains:\r\n•	Cost Efficiency: Eliminated the need for a separate preclinical lab, reducing facility expenses.\r\n•	Enhanced Skill Acquisition: Achieved faster mastery of isolation and suction techniques compared to conventional phantom setups.\r\n•	Improved Ergonomics Compliance: Enabled real-time monitoring of correct posture and chair positioning.\r\n•	Resource Optimization: Reduced faculty supervision time per student, allowing simultaneous oversight of multiple stations.\r\nConclusion:\r\nThe G-Safety Latch (patent application no.202541017302) transforms clinical dental chairs into dual-purpose training environments, bridging the gap between simulation and patient care. By integrating authentic clinical features into preclinical training, it reduces infrastructure costs, accelerates skill acquisition, and enhances ergonomic and infection-control practice. This innovation offers a scalable, cost-effective solution for dental institutions worldwide, fostering improved educational outcomes and smoother transitions to clinical proficiency\r\n', 'VIDYEN/1000015', '10-09-2025', 2, 0),
(10, 'VIDYEN/1000015', 'AUT000010', 'Blended Learning Strategies in Dental Education', 'Yenvision- Lightning talk', 'Narrative Review', 'Recalibrating Medical and Allied Education', 'Curriculum reform, Entrustable Professional Activities (EPAs), Medical and dental education', 'Introduction\r\nContemporary medical and dental education faces urgent challenges demanding bold reforms that integrate human values, emotional well-being, and technological advancements within a multidisciplinary ecosystem. Rapid scientific innovation, shifting student and patient expectations, and evolving societal values call for curricula that balance technological readiness with holistic professional development grounded in passion for the profession and compassion for patients.\r\nMethods\r\nA comprehensive framework for curriculum recalibration was developed centered on Entrustable Professional Activities (EPAs) that bridge preclinical competence with clinical proficiency. The reform process includes eight sequential steps: stakeholder engagement, gap analysis by policymakers and institutions, collaborative interpretation, curriculum redesign, faculty development, implementation of training protocols, enhancement of assessment tools, and feedback mechanisms for sustainability. Digital learning platforms and AI-enhanced simulation tools were integrated to personalize learning pathways and strengthen clinical reasoning, supported by entrustment-supervision scales for transparent learner progression evaluation.\r\nResults\r\nThe standardized syllabus creates a humanistic, patient-centered educational fabric emphasizing ethical and moral values such as humility, empathy, patience, and human touch alongside technical expertise. Patient outcomes improve through early and accurate diagnosis, precision in procedural planning, enhanced treatment predictability, and safer postoperative recovery. Students develop intellectually, professionally, and personally through the engagement principles of talk-touch-teach-treat-track, fostering reflective practice and resilience. Faculty development programs delineate clear roles and responsibilities, promoting mentorship models that stimulate innovation, research, and entrepreneurship. AI-driven analytics enable real-time gap identification, personalized remediation, and continuous performance feedback, making learning adaptive and responsive.\r\nConclusion\r\nThis curriculum recalibration positions dentistry and allied health education as enduring classics with lasting relevance by integrating cutting-edge technology with timeless ethical principles. It ensures that academic institutions evolve from centers of knowledge generation to platforms for societal problem-solving. While techniques and technologies rapidly evolve, the core commitment remains unchanged: passion towards the profession and compassion for patients. This balanced approach prepares future health professionals to navigate complex interconnected healthcare ecosystems, delivering exemplary patient care with professionalism and humanity.\r\n\r\n', 'VIDYEN/1000015', '10-09-2025', 2, 0),
(11, 'VIDYEN/1000047', 'AUT000011', 'Faculty Development for Effective Hybrid Teaching', 'Posters', 'Interprofessional Research', 'Faculty perception as part of need assessment for designing competency based interprofessional educational model for health science post graduates', 'Faculty perception, interprofessional education, need assessment', 'Background\r\nFaculty is considered to be at the core of developing and implementing IPE. Hence assessment of faculty readiness, and their perception towards IPE can serve as best predictor of their intent to engage in IPE and act as a decisive step toward its implementation in future. \r\n\r\nAim- To assess DMIHER faculty perception as part of need assessment for designing competency-based IPE model for health science postgraduates\r\n\r\nMethodology\r\nFaculty from four constituent colleges, Medical (270), Dental (61), Ayurveda, (60) and Physiotherapy (17), (total=410) under the ambit of DMIHER University were invited to take part in the study. A representative sample size using simple random sampling was drawn (n=283). The survey questionnaire consisted of twelve close ended questions seeking yes/no response and 1 open-ended question. Both offline and online versions of questionnaire were drafted, validated and administered to the faculty \r\n \r\nResults \r\nOverall faculty response rate was (73.49%) which was statistically significant Altogether 75% faculty responded that they were uninformed about the concept of IPE and unaware of IPE competencies the difference being statistically significant. 82.98% Dental, 69.05%- Ayurveda, 87.62%- Medical and 92.86% Physiotherapy faculty agreed that health science post graduates lack knowledge, skills and attitudes to provide interprofessional collaborative care to their patients. 69% faculty perceived that all postgraduates should be trained in teamwork skills and interprofessional competencies. 44.68% Dental, 45.24% Ayurveda, 78.10% Medical and 42.86% Physiotherapy faculty agreed that interprofessional competencies are inadequately addressed in didactic and practical teaching and recommended that health science post graduate curriculum should be revised to include interprofessional education. 40% Medical and 100% Dental, Physiotherapy and Ayurveda, faculty agreed that faculty should be trained to deliver interprofessional education. The barriers/challenges to IPE perceived by faculty were time constraints, old schools of thought and faculty resistance, inadequate resources and infrastructure, lack of orientation and knowledge towards IPE, curricular issues and leadership commitments. \r\n\r\nConclusion\r\nThe unawareness of faculty regarding IPE concept and competencies confirm that DMIHER faculty had insufficient experience and were unfamiliar with a team based approach like IPE. However, positive perception for IPE held in common by faculties from all disciplines indicated that faculties are keen in incorporating IPE in post graduate health science curricula.\r\n', 'VIDYEN/1000047', '11-09-2025', 2, 0),
(12, 'VIDYEN/1000035', 'AUT000012', 'Technology-Driven Innovations in Dental Education', 'Posters', 'Narrative Review', 'Engaging Minds and Enhancing Skills: Digital Interactivity in Dental Education', 'Dental education, simulation, AR, VR', 'Engaging Minds and Enhancing Skills: Digital Interactivity in Dental Education\r\nThe integration of interactive digital tools in dental education has revolutionized traditional teaching methodologies, enhancing both the delivery and assimilation of complex concepts. Interactive digital tools include the role of digital technologies such as virtual simulations, augmented reality (AR), virtual reality (VR), 3D modeling, and online collaborative platforms in modern dental curricula. These tools offer immersive, hands-on learning experiences that allow students to practice clinical procedures, visualize anatomical structures, and receive immediate feedback in a risk-free environment for better learning outcomes. Moreover, interactive platforms promote self-paced learning and improve student engagement, knowledge retention, and clinical competence. The use of these technologies also supports remote learning, making dental education more accessible and flexible. Despite challenges such as high costs, technical limitations, and the need for faculty training, the benefits of digital interactivity in dental education are substantial. As digital tools continue to evolve, their integration promises to further enhance the quality and effectiveness of dental training, preparing students for real-world clinical practice with greater confidence and proficiency.\r\n', 'VIDYEN/1000035', '13-09-2025', 2, 0),
(14, 'VIDYEN/1000069', 'AUT000014', 'Blended Learning Strategies in Dental Education', 'Oral Presentations for research submission', 'Original Research Medical / Dental Education', 'Innovating Dental Education: Blended Learning Strategies for Domestic Violence Intervention', 'Blended learning, domestic violence, trauma-informed care, interprofessional collaboration, referral pathways', 'Background:\r\nDomestic violence (DV) is a critical public health issue, particularly in rural and remote communities where access to support services is limited. Dentists are often among the few professionals who may observe signs of DV, making their role in early identification and referral vital. To address this, a collaborative initiative between JCU Dentistry and Social Work developed a blended learning model to build trauma-informed, culturally responsive DV clinical skills among dental students and practitioners.\r\n\r\nAim:\r\nThis presentation explores how scaffolded blended learning strategies—integrating online video scenarios, in-person engagement, and reflective practice—were used to develop and deliver domestic violence-responsive education tailored for dental students working in regional and rural settings in Australia. \r\n\r\nMethod:\r\nA multidisciplinary team employed Participatory Action Research (PAR) to co-design educational resources with input from victim-survivors, students, educators, and community stakeholders. The blended learning model was scaffolded to support progressive skill development and included:\r\n•	Online modules featuring eight scenario-based videos and downloadable print materials\r\n•	In-class discussions and case-based learning to contextualise DV within dental practice\r\n•	Reflective exercises to deepen understanding of trauma-informed care\r\n•	Community partnerships to support real-world application and referral pathways\r\nA mixed-methods evaluation framework guided both the development and assessment phases. This included thematic analysis of participant feedback and an ongoing meta-analysis to evaluate the impact of the resources on clinical learning and practice.\r\n\r\nResults :\r\nThe blended learning model led to increased student engagement and confidence in responding to domestic violence. It fostered enhanced collaboration between dental educators and local DV support services, creating stronger referral pathways and community connections. Learners consistently provided positive feedback on the accessibility and realism of the video scenarios, which helped bridge theoretical knowledge with practical application. Summative evaluations confirmed that this approach significantly improved students’ ability to deliver person-centred, trauma-informed care in regional and rural dental settings. The full suite of training resources, including eight scenario-based videos and downloadable print materials, is freely available on the JCU web portal: https://www.jcu.edu.au/college-of-medicine-and-dentistry/dv-training.\r\n\r\nConclusion:\r\nFunded by the Keeping Women Safe from Violence grant, this initiative produced Australia’s first domestic violence training resources tailored for dental professionals using a blended learning model. These resources empower dental students and practitioners to recognise, respond to, and refer DV cases effectively. The success of this model highlights the value of blended learning in addressing complex and sensitive topics—such as domestic violence—in clinical education.\r\n', 'VIDYEN/1000069', '16-09-2025', 2, 0),
(15, 'VIDYEN/1000071', 'AUT000015', 'Technology-Driven Innovations in Dental Education', 'Oral Presentations for Speciality Research', 'Original Research Medical / Dental Education', 'RELATION OF NICOTINE, EXHALED CARBON MONOXIDE  AND ORAL HEALTH AMONG SMOKERS FOR TOBACCO CESSATION AS A AID IN DENTAL EDUCATION', 'Nicotine, Carbon Monoxide, Oral Health  Status, fagerstorm Scale ', 'Background: Nicotine is the primary factor liable for the dependence forming properties of tobacco items and nicotine dependence is broadly perceived as one of the core factors in the support of tobacco smoking. Several studies have revealed measurement of exhaled CO levels as the useful and easy tool for assessing the habit of smoking, as it is non-invasive; the results are immediate and can be used as tool for the dental education for the cessation of tobacco.\r\nAim: To study the correlation between nicotine dependence, exhaled carbon monoxide levels and   oral health status among smokers at Moradabad city.\r\nMaterial and Methodology: A sample of 400 subjects who reported to the OPD of Department of Public Health Dentistry, Kothiwal Dental College & Research Centre were included in the study. Nicotine was measured using Fagerstrom Test for Nicotine Dependence (FTND), exhaled CO was measured using smokerlyzer and Oral health status was recorded using WHO Oral Health Assessment Form 1997. \r\nResults: There was correlation between FTND Score and exhaled CO with periodontitis, LOA (Loss of Attachment) and DMFT.\r\nConclusion: Results of the present study showed high nicotine dependence and exhaled CO which demonstrate some direct connections with periodontitis, LOA and DMFT. Thus the use of the smokerlyzer showed the oral health status of the population and this can be useful for the tobacco cessation counselling  as a aid of dental education.', 'VIDYEN/1000071', '17-09-2025', 2, 0),
(16, 'VIDYEN/1000020', 'AUT000016', 'Blended Learning Strategies in Dental Education', 'Oral Presentations for Speciality Research', 'Narrative Review', 'Rethinking Education: Emerging Technologies and the Future of Learning.', 'Digital Learning, Virtual and Augmented Reality, Educational Technology, Artificial Intelligence', '                                                            Rethinking Education: Emerging Technologies And The Future Of Learning.\r\n                                                                                                             \r\n                                                                                                    Abstract\r\n\r\nBackground\r\n\r\nThe 21st century has witnessed an accelerated integration of digital technologies in education, driven further by the COVID-19 pandemic. Tools such as artificial intelligence (AI), virtual and augmented reality (VR/AR), mobile learning platforms, and online resources have reshaped teaching and learning practices. However, despite their potential to improve accessibility, engagement, and personalization, challenges related to infrastructure, pedagogy, and equity remain.\r\n\r\nSummary of Work\r\nThis review synthesizes contemporary literature on trends, challenges, and innovations in digital learning. It examines early developments in computer-assisted instruction, the transition to blended and online learning, and the growing roles of MOOCs, mobile platforms, and immersive technologies. The review also explores case studies highlighting effective digital learning practices and outlines strategic recommendations for policymakers and educators.\r\n\r\nMain Findings\r\nThe integration of AI-driven adaptive systems, VR/AR environments, and collaborative online tools has significantly improved student engagement, flexibility, and academic outcomes. Case studies such as the Open University (UK) and Singapore’s Student Learning Space illustrate how digital initiatives can democratize access to education. Nevertheless, barriers including the digital divide, insufficient teacher training, limited accessibility for diverse learners, and concerns over data security persist.\r\n\r\nDiscussion\r\nThe findings emphasize that digital transformation in education is not merely about replacing traditional methods but about creating inclusive, student-centered ecosystems. The review underscores the need for infrastructure investment, professional development for educators, and policies that address socioeconomic and ethical concerns. Future directions point toward AI-based personalization, blockchain-enabled credentialing, microlearning via mobile platforms, and cross-cultural adaptability of digital content.\r\n\r\nConclusion\r\nDigital learning holds immense promise to enhance accessibility, engagement, and personalization in education. While challenges persist, collaborative efforts among governments, institutions, educators, and technology providers can help ensure the equitable and effective integration of technology. By adopting best practices and prioritizing inclusivity, digital learning can transform global education, preparing learners for the evolving demands of the digital age.\r\n\r\n', '', '18-09-2025', 2, 0),
(17, 'VIDYEN/1000020', 'AUT000017', 'Speciality Presentation', 'Yenvision- Lightning talk', 'Narrative Review', 'PHOBIA VS. PREVENTION: THE ORAL HEALTH DILEMMA', 'Dental anxiety, Cognitive Behavioral Therapy, Patient Education, Patient-centered care, Conscious sedation', 'Dental anxiety, from mild unease to severe phobia, is a common barrier to oral healthcare across all age groups. Many patients avoid dental visits due to fear, seeking treatment only when pain becomes unbearable. This delay worsens oral diseases and increases the risk of systemic issues like cardiovascular disease and diabetes. Dental fear often stems from past traumatic experiences, fear of pain, general anxiety, and a perceived lack of control. Social stigma can further reinforce avoidance behavior.\r\nThe consequences of dental fear are both clinical and psychological. Skipping routine dental visits leads to untreated caries, gum disease, tooth loss, and poor oral hygiene. These affect oral function, appearance, self-esteem, and overall quality of life. However, dental fear is treatable. Techniques such as patient education, cognitive behavioral therapy (CBT), sedation, and gradual exposure to dental settings have proven effective—especially in children. Behavioral strategies and CBT are particularly successful in reducing long-term anxiety.\r\n\r\n\r\n“Addressing dental anxiety with evidence-based strategies, gentle care, and open conversation not only improves overall health outcomes but also restores dignity, builds trust, and ensures every smile receives the care it deserves.”\r\n', 'VIDYEN/1000020', '19-09-2025', 2, 0),
(18, 'VIDYEN/1000055', 'AUT000018', 'Speciality Presentation', 'Oral Presentations for Speciality Research', 'Original Research Medical / Dental Education', 'Assessment of cardiovascular disease in patients with periodontal disease', 'Atherosclerosis, periodontitis, Coronary artery disease', 'Introduction: Periodontitis is a biofilm‐induced chronic inflammatory disease that affects the tooth‐supporting structures. The subgingival microbiota may be a source of dissemination and may contribute to the development of atherosclerosis.\r\n\r\nObjective: This study was designed to investigate if the periodontal status of the patient had an influence on the cardiac disease severity in patients with coronary artery disease.\r\n\r\nMethodology: Subgingival and atherosclerotic plaques was extracted from 96 patients with coronary artery disease and were scheduled to undergo coronary angioplasty or CABG procedures in this cross‐sectional analytical study. Clinically the periodontal status of all the  patients was graded. DNA extraction was done for the plaque samples, which was then followed by a nested polymerase chain reaction (PCR). Based on the PCR results, 44 patients were age‐ and gender‐matched and divided into two groups based on the presence (Group A) or absence (Group B) of periodontal bacterial DNA in the atherosclerotic plaque samples. Syntax scoring was done by the cardiologist to grade the cardiac severity. The Pearson Chi‐square test was done to investigate the association between periodontal status and pathogen detection, as well as determine the relationship between periodontal severity and cardiac severity. P < 0.05 was considered to be statistically significant. \r\n\r\nResults: Statistically insignificant association was observed between periodontal severity and the detection of the periodontal pathogens Porphyromonas gingivalis and Tannerella forsythia in the subgingival and atherosclerotic plaques in Group A; however, a significant association was observed for the pathogen Treponema denticola in the subgingival plaque for both Groups A (P = 0.039) and B (P = 0.005). No significant association was observed between the periodontal severity and cardiac severity for Groups A (P = 0.40) and B (P = 0.277). A weak positive but statistically insignificant (P = 0.097) correlation was observed for overall periodontal and cardiac severity. The percentage of patients with high syntax scores was higher in group A compared to group B patients, demonstrating the severity of the cardiac condition.\r\n\r\nConclusion: A higher percentage of patients had generalized chronic periodontitis in the group that tested positive for the pathogens in the atherosclerotic plaques, indicating a possible influence of periodontal status on cardiac outcomes.\r\n', 'VIDYEN/1000055', '19-09-2025', 2, 0),
(19, 'VIDYEN/1000059', 'AUT000019', 'Blended Learning Strategies in Dental Education', 'Oral Presentations for research submission', 'Narrative Review', 'Comparative evaluation on the effectiveness', 'Preventive Dentistry', 'Teaching and learning have always been a continuous process of acquiring knowledge ever since the origin of mankind. The progression from pictorial scriptures to voracious classroooms have been a keen area of focus in todays scenario of providing education. Dental education is on the verge of this transformative learning process as well. The mode of delivering of dental education has abruptly modernized subsequently from these theoritical hourly lecture sessions to an advanced and interactive learning sessions. \r\nThis mode of teaching and learning have exhibitted to impose a positive attitude and outcome with better understanding of concepts. The rapid changeover from abrupt monotonous lecture sessions to active teaching and learning have not only transformed its impact on the student community but also have changed the outlook of the facilitators thereby exemplifying them with more real time teaching strategies.\r\n', 'VIDYEN/1000059', '22-09-2025', 2, 0),
(20, 'VIDYEN/1000007', 'AUT000020', 'Speciality Presentation', 'Oral Presentations for research submission', 'Systematic Review / Metanalysis', 'A Systematic Review on the Application of Bioceramics in Prosthodontics: Advances, Challenges, and Future Directions ', 'Zirconia,crown,bridges', 'Introduction\r\nProsthodontics has evolved significantly over the past few decades, with bioceramic materials emerging as a promising alternative to traditional dental materials. Bioceramics offer a unique combination of biocompatibility, mechanical strength, and aesthetic properties, which are crucial for the restoration of teeth and the rehabilitation of edentulous patients. Bioceramics are increasingly being used in crowns, bridges, dental implants, and abutments. This systematic review aims to summarize the developments in the use of bioceramics in prosthodontics over the past ten years, focusing on their advancements, clinical applications, and ongoing challenges.\r\nObjective: This systematic review aims to evaluate the recent advancements, applications, and challenges of bioceramics in prosthodontics over the past decade (2013–2023). Bioceramics have emerged as a prominent material in dental prosthodontics, offering promising alternatives to traditional materials due to their superior biocompatibility, mechanical properties, and aesthetic qualities.\r\nMethods: A comprehensive search of PubMed, Scopus, and Web of Science was conducted for studies published between 2013 and 2023. Relevant articles on the use of bioceramics in prosthodontics, including full-text clinical trials, in vitro studies, and systematic reviews, were included. Studies addressing materials such as zirconia, bioactive glass, and calcium phosphate ceramics were prioritized.\r\nResults: The review identified significant advancements in bioceramic materials, particularly zirconia, which has become a standard for crowns, bridges, and implant abutments. Recent studies highlight improvements in fracture resistance, translucency, and aesthetic outcomes. Bioactive glasses and calcium phosphates have shown promise in promoting osseointegration and tissue regeneration. However, challenges such as material brittleness, wear resistance, and long-term clinical performance remain a focus of ongoing research.\r\nConclusion: Bioceramics have demonstrated notable potential in prosthodontics over the last decade, with ongoing improvements in material properties and clinical outcomes. However, challenges such as optimizing mechanical strength and long-term durability require further investigation. Future research should focus on enhancing the functionality and cost-effectiveness of bioceramic materials for widespread clinical application.\r\n', 'VIDYEN/1000007', '24-09-2025', 2, 0),
(21, 'VIDYEN/1000080', 'AUT000021', 'Speciality Presentation', 'Oral Presentations for Speciality Research', 'Original Research Medical / Dental Education', 'Efficacy of Canine Guided Versus Bilateral Balanced Occlusion Orthotic Appliances in Managing TMJ Disc Displacement with Reduction: A Randomised Clinical Trial', 'Health, quality of life, temporomandibular joint, Appliance, Orthotic', '\r\n\r\nIntroduction: Among the intracapsular disorders of the temporomandibular joint (TMJ), disc displacement with reduction (DDwR) occurs most frequently, typically presenting with pain, joint sounds such as clicking, and reduced mandibular mobility. The orthotic occlusal stabilization appliance remains one of the most widely utilized therapeutic modalities for the management of temporomandibular joint disorders (TMDs). \r\n\r\nObjectives: To evaluate the pain reduction in patients with disc displacement with reduction of the temporomandibular joint using canine guidance and balanced occlusion orthotic appliance. To compare and evaluate difference in the pain reduction between the 2 different orthotic appliance designs \r\n\r\nMethodology: This study included 68 cases of DDwR of the TMJ associated with pain, classified as Group IIa according to the RDC/TMD diagnostic criteria. Participants were randomly allocated into two groups: Group I received a canine-guided orthotic appliance, and Group II received a bilateral balanced occlusion orthotic appliance. Visual Analog Scale (VAS) was used to assess the pain intensity at 0,15, 30, and 90 days.\r\n\r\nResults: Mann-Whitney U test was used for group comparisons which demonstrated Group 2 achieved significantly lower VAS scores during early assessments, while Group 1 exhibited more notable reductions between 30 and 90 days. Wilcoxon test was used to assess improvement within groups which demonstrated significant improvement in both the groups. \r\n\r\nConclusion: Bilateral balanced occlusion orthotic appliance showed greater and faster pain reduction with consistently lower VAS scores at each time point especially prominent in the early phases 15 and 30 days. Canine guided orthotic appliance however, demonstrated more pain reduction between 30 and 90 days, suggesting a delayed therapeutic effect.\r\n\r\n\r\n\r\n', '', '25-09-2025', 2, 0),
(22, 'VIDYEN/1000037', 'AUT000022', 'Blended Learning Strategies in Dental Education', 'Oral Presentations for research submission', 'Narrative Review', 'Flipped Classroom: An Innovative Hybrid Learning Model in Dental Education', 'Flipped classroom, dental education, active learning, hybrid learning, ', 'Background:\r\nTraditional lecture-based teaching in dental education often results in passive learning, limited critical thinking, and inadequate integration of theoretical knowledge with clinical application. The flipped classroom model, by reversing the order of content delivery and classroom engagement, has emerged as a learner-centered approach that promotes active participation, problem-solving, and self-directed learning.\r\n\r\nAim:\r\nTo explore the effectiveness, benefits, and challenges of flipped classroom teaching as a hybrid pedagogical model in dental education, and to highlight its role in competency-based curriculum reform.\r\n\r\nMethods:\r\nA narrative synthesis of available literature and educational experiences was conducted focusing on the application of flipped classroom pedagogy in dental and health professions education. Pre-class learning resources (video lectures, digital modules, guided readings) and in-class strategies (case-based discussions, group activities, formative assessments) were analyzed for their impact on student engagement, academic outcomes, and clinical preparedness.\r\n\r\nResults:\r\nStudies consistently report that flipped classroom models improve knowledge acquisition, enhance higher-order cognitive skills, and increase student satisfaction compared to conventional teaching. Students in flipped settings demonstrate better preparation for clinical reasoning and problem-based tasks. Faculty members are able to provide individualized guidance, foster interactive learning environments, and receive real-time feedback on student understanding. However, challenges include technological dependence, student adaptation to self-learning, and increased faculty preparation time.\r\n\r\nConclusion:\r\nThe flipped classroom represents a promising hybrid teaching strategy for dental education. By blending pre-class digital learning with interactive in-class engagement, it fosters competency-based training, critical thinking, and collaborative learning. With institutional support and faculty training, flipped classrooms can significantly contribute to the modernization of dental curricula and align with the vision of learner-centered, hybrid education models emphasized in VIDYEN 3.0.', 'VIDYEN/1000037', '01-10-2025', 2, 0);
INSERT INTO `abstract` (`id`, `registration_id`, `abstract_id`, `sub_theme`, `type_of_presentation`, `category_presentation`, `paper_title`, `keywords`, `paper_abstract`, `created_by`, `created_on`, `status`, `flag`) VALUES
(23, 'VIDYEN/1000079', 'AUT000023', 'Blended Learning Strategies in Dental Education', 'Oral Presentations for research submission', 'Interprofessional Research', '“Enhancing Collaborative Competence through IPE in Oral Health and Tobacco Control”', 'TOBACCO,IPE,IPP, DENTAL,MEDICAL, STUDENTS', 'Background\r\nTobacco use remains a leading cause of preventable morbidity and mortality, with significant oral and systemic health consequences. Dentists, by virtue of their routine patient interactions and ability to detect early oral manifestations of tobacco use, hold a unique position in delivering tobacco cessation counseling (TCC). However, addressing tobacco dependence requires a collaborative, interprofessional approach, as it encompasses behavioural, psychological, and medical dimensions beyond dentistry alone. \r\nSummary of work\r\nInterprofessional Education (IPE) provides a platform for dental professionals to work alongside medical, nursing, and allied health students, fostering mutual understanding, role clarity, and teamwork in patient-centered tobacco cessation strategies. Within IPE frameworks, dentists contribute expertise in risk identification, oral health consequences, and reinforcement of cessation efforts, while benefiting from the knowledge of other professionals in pharmacotherapy, behavioural therapy, and long-term addiction management.\r\nMain findings\r\nDespite existing challenges—such as limited curricular integration, time constraints, and lack of standardized assessment tools—IPE in TCC equips dentists with the competence to act as effective collaborators and advocates in tobacco control. My review explores from a dentist’s perspective, IPE is not merely complementary but essential in creating a unified healthcare response to combat tobacco use.\r\nDiscussion\r\nThis review highlights the value of interprofessional education (IPE) in strengthening the role of dental professionals in tobacco cessation counseling (TCC). The significant improvement in knowledge and confidence across participants confirms earlier reports that IPE fosters better understanding of complementary professional roles and enhances collaborative practice. For dentists, participation in IPE emphasized their unique responsibility in early detection of oral manifestations and consistent reinforcement of cessation advice during routine care.\r\nConclusion \r\nSuch collaboration enhances communication skills, builds confidence, and ensures holistic patient care. \r\n', 'VIDYEN/1000079', '01-10-2025', 2, 0),
(24, 'VIDYEN/1000025', 'AUT000024', 'Speciality Presentation', 'Oral Presentations for Speciality Research', 'Original Research Medical / Dental Education', 'Antimicrobial evaluation and Molecular Docking analysis of Zingiber officinale and Allium sativum against Fusobacterium Nucleatum.', 'Antibacterial, Allium sativum, Molecular Docking, Zingiber Officinale', 'Background: The success of endodontic treatment depends mainly on the eradication of microorganisms from the root canal system and prevention of re-infection. A bacteria free root canal is difficult to achieve due to the anatomical complexities of root canals, organic residues and unreachable bacteria located deep inside the dentinal tubules. Endodontic infections are currently treated by mechanical debridement followed by chemical disinfection. Because of the shortcomings of current antibiofilm strategies in root canal treatment, phytochemicals are under research for their effectiveness against endodontic pathogens. Recent research has identified Fusobacterium nucleatum has a keystone species in primary and secondary endodontic infections.\r\nObjectives: To evaluate the antibacterial efficacy and Molecular docking analysis of Zingiber officinale and Allium sativum against Fusobacterium Nucleatum.\r\nMethodology: Antibacterial activity of the test solutions by Agar well diffusion technique (ZOI). MIC will be determined. Group 1- NaOCl, Group 2- Zingiber Officinale, Group 3 – Allium sativum, Group 4 - Saline. Molecular Docking analysis will be carried out. Data will be collected and subjected to statistical analysis.\r\nExpected Outcomes: Antimicrobial efficacy and molecular docking analysis of Zingiber officinale and Allium sativum against Fusobacterium Nucleatum. The molecular docking approach can be used to model the interaction between a small molecule and a protein at the atomic level, which allow us to characterize the behavior of small molecules in the binding site of target proteins as well as to elucidate fundamental biochemical processes and antimicrobial property.\r\n', 'VIDYEN/1000025', '06-10-2025', 2, 0),
(25, 'VIDYEN/1000116', 'AUT000025', 'Speciality Presentation', 'Yenvision- Lightning talk', 'Original Research Medical / Dental Education', 'Oral Hygiene Practices and Knowledge on Periodontal Diseases and Therapy A Cross‑Sectional Questionnaire Study on Gypsy Narikuravars in Puducherry.', 'Gypsy, knowledge, Narikuravar, oral hygiene practices, periodontal \r\ndisease, tribes.\r\n', 'Gypsy “Narikuravars” constituted separate sociocultural groups having distinct cultures, customs, traditions, and lifestyles. Oral health‑seeking \r\nbehavior of this group remains to be an ignored part. This study aims to assess the oral hygiene practices and knowledge on periodontal diseases and therapy \r\namong Gypsy Narikuravars in Puducherry. The total study population consisted of 100 subjects, and a performed validated proforma about oral hygiene practices and knowledge on periodontal diseases was used.There is no significant association between sociodemographic factors and knowledge on periodontal disease and therapy. Majority (90%) of the participants have poor knowledge of periodontal disease and therapy. 56% of the participants used their fingers to clean the teeth, and very few subjects (13%) used toothbrush to clean their teeth, and most of the participants (92%) brushes once daily using manual method. The practice of poor oral hygiene and lack of knowledge on periodontal disease and therapy was observed. Hence, the implementation of oral health programs and provision of comprehensive health services for these Gypsy population should be a high priority.\r\n', 'VIDYEN/1000116', '07-10-2025', 2, 0),
(26, 'VIDYEN/1000062', 'AUT000026', 'Virtual Simulations and Hands-On Training: Bridging the Gap', 'Posters', 'Systematic Review / Metanalysis', 'Haptic Virtual-Reality Simulators in Dental Education — A Structured Systematic Review', 'virtual reality simulators', 'Background: Haptic Virtual Reality simulators (e.g., Simodont, DentSim, Unidental) are increasingly integrated into hybrid dental curricula to combine hands-on training with digital feedback.\r\nObjective: To synthesize evidence on the effectiveness, educational outcomes, learner experience, transfer to patient care, and limitations of haptic Virtual Reality simulators in undergraduate dental education.\r\nMethods: We performed a structured synthesis of peer-reviewed systematic reviews  published through 2025, focusing on outcomes: psychomotor skill acquisition, knowledge, student satisfaction, transfer to clinical performance and cost/feasibility. \r\nResults: Evidence consistently shows that haptic Virtual Reality simulators improve early psychomotor skill acquisition and provide objective, repeatable feedback compared with traditional phantom-head training; learner satisfaction is generally high. However, evidence for direct transfer and long-term clinical performance is limited and heterogeneous. Cost, faculty training needs, and variable haptic fidelity are recurring barriers.\r\nConclusions: Haptic Virtual Reality  simulators are valuable components of hybrid dental education for preclinical skill training, especially for early deliberate practice and objective assessment. More high-quality randomized trials and longitudinal studies measuring patient-level outcomes and cost-effectiveness are required.\r\n', 'VIDYEN/1000062', '07-10-2025', 2, 0),
(27, 'VIDYEN/1000116', 'AUT000027', 'Speciality Presentation', 'Oral Presentations for Speciality Research', 'Original Research Medical / Dental Education', 'Clinical approach regarding Periodontal Practice by general Dental Practitioners of Pondicherry –   A survey.', 'General dental practitioner, periodontal, survey', 'CLINICAL APPROACH REGARDING PERIODONTAL PRACTICE BY GENERAL DENTAL PRACTITIONERS OF PUDUCHERRY –   A   SURVEY \r\nBACKGROUND : The do\'s and don’ts in General Dental practice struggle to find the boundaries of their own at the cost of patient’s well being, overall care, and treatment. This fine line especially has difficulty to find ground when it comes to different specializations, one of which is Periodontology. Newer studies, research, and advancement in armamentarium and materials changing the face of Periodontal treatment, it’s implementation, and outcome are being documented, proved, and debated about at a pace that requires dentists to keep up.                                           \r\nSUMMARY: To evaluate the clinical approaches of general dental practitioners. To assess the knowledge, attitude, and practice among the general dental practitioners regarding periodontal practice in Puducherry. This cross-sectional survey shall be carried out involving General dental practitioners who are registered and are practicing in either urban or rural areas of Puducherry, India, with focus on Periodontal specialty, and a structured questionnaire. \r\nMAIN  FINDINGS : Based on the results of this survey, we have identified certain factors that could be improved for the betterment of society. These factors are categorized into three groups: periodontist-related factors, general dentist–related factors, and patient-related factors.\r\nDISCUSSION : Out of 37 participants, there were 23 males and 14 females.7 of which were practicing in rural areas while 30 were from urban. Majority of them were practicing for 1 to 5 years (51.3%), followed by 6 to 10 years (18.4%) and then the rest procedures. While 67.6% refer their patients to a periodontist for Phase-I therapy, 32.4% do not refer their patients, whereas 83.8% of the doctors refer their patients when it comes to surgical procedures and remaining 16.2% of them do not refer their patients to a periodontist for even surgical. Thus, there is high level of satisfaction with the treatment of the most common periodontal complaints.\r\nCONCLUSION : Future studies of this nature should be conducted to gain a comprehensive understanding of the perceptions of general dentists toward periodontal treatment in India. Repeating such studies at regular intervals within the same regions can help track changing trends and patterns in the dental treatment practices of general practitioners. These investigations can also serve as an early warning system, prompting both general dentists and periodontists to reflect on their practices and work toward the advancement of the specialty.\r\n', 'VIDYEN/1000116', '08-10-2025', 2, 0),
(28, 'VIDYEN/1000049', 'AUT000028', 'Virtual Simulations and Hands-On Training: Bridging the Gap', 'Yenvision- Lightning talk', 'Interprofessional Research', 'Interprofessional Education for Medical Emergencies Management for Undergraduate Healthcare Students', 'Interprofessional Education, Medical Emergencies,Healthcare Students,simulation', 'Background:Interprofessional education (IPE) has is an emerging field of healthcare education. Teamwork and collaboration foster a healthy working environment, and IPE aims at learning about, from, and with each other. For this to occur, educational institutions and healthcare services have recognized the need for all members of the team to be educated together to deliver this holistic care to a patient. As health professionals, dental students, medical students, and nurses should be prepared to recognize and manage common medical emergencies that may arise in the dental office or dental school clinic.The aim of the present study is to explore the impact of Interprofessional simulation-based medical emergencies management in dental practice. The objectives of the present study was to explore the impact of Interprofessional simulation-based medical emergency management among dental practice in undergraduate healthcare professions on sustainable learning and skill development.\r\nMethods: Mixed method study. The entire student sample were randomly divided into groups; each group will have students from Medical, Dental, and Nursing backgrounds. Stations created with themes: altered consciousness, chest pain, drug-related emergencies, unconsciousness, and respiratory distress. The students were individually assessed by a single select peer during one of two standardized medical emergency scenarios. Mean SPICE-R2 score was used to assess teamwork and collaboration. Qualitative data- thematic analysis of in-depth interview was analyzed using N vivo software. We used a 75% “pass” criterion for successful checklist completion based on Interprofessional simulation curriculum assessment. Five distinct themes identified (in order of strength): Facilitation; Incorporation of IPE Curriculum; Roles and Responsibilities; Importance of IPE in medical emergency management, Communication.\r\nImplications: Qualitative study emerged with three broad themes with the need to introduce simulation based Interprofessional educational practices in medical emergency management by healthcare professionals. There lies need to aware both students and faculty for Interprofessional collaboration in this digital era.\r\nConclusion: Simulation-based training models have been successfully demonstrated in aviation’s crew resource management training programs. The model of care can be adapted to healthcare education for patient care.\r\n\r\n', 'VIDYEN/1000049', '08-10-2025', 2, 0),
(29, 'VIDYEN/1000049', 'AUT000029', 'Enhancing Student Engagement in Hybrid Learning Environments', 'Oral Presentations for research submission', 'Interprofessional Research', 'Advanced Learner Perspectives: An IPE Training for Medical Emergencies Management', ' Interprofessional education,Simulation, medical emergency management', 'Background:Interprofessional education (IPE) has is an emerging field of healthcare education. Teamwork and collaboration foster a healthy working environment, and IPE aims at learning about, from, and with each other. For this to occur, educational institutions and healthcare services have recognized the need for all members of the team to be educated together to deliver this holistic care to a patient. As health professionals, dental students, medical students, and nurses should be prepared to recognize and manage common medical emergencies that may arise in the dental office or dental school clinic.\r\nMethods: Mixed method study. The entire student sample were randomly divided into groups; each group will have students from Medical, Dental, and Nursing backgrounds. Stations created with themes: altered consciousness, chest pain, drug-related emergencies, unconsciousness, and respiratory distress. \r\nResult:Qualitative study emerged with three broad themes with the need to introduce simulation based Interprofessional educational practices in medical emergency management by healthcare professionals. There lies need to aware both students and faculty for Interprofessional collaboration in this digital era.\r\nConclusion: Simulation-based training models have been successfully demonstrated in aviation’s crew resource management training programs. The model of care can be adapted to healthcare education for patient care.', 'VIDYEN/1000049', '08-10-2025', 2, 0),
(30, 'VIDYEN/1000095', 'AUT000030', 'Virtual Simulations and Hands-On Training: Bridging the Gap', 'Yenvision- Lightning talk', 'Narrative Review', 'Immersive Learning in Dentistry: The Synergy of VR and Hands-On Simulation', 'Virtual reality, immersive learning, skill training, simulation', 'Virtual Reality (VR) and hands-on simulation are transforming dental education by bridging the gap between theoretical instruction and clinical practice. VR enables immersive, interactive environments where students can explore complex oral anatomy, practice procedures, and refine diagnostic skills without patient risk. Complementing this, hands-on simulation—using dental mannequins and haptic devices—provides tactile feedback and procedural realism essential for developing fine motor skills and clinical confidence. Together, these modalities foster a blended learning approach that enhances student engagement, accelerates skill acquisition, and supports competency-based education. By simulating diverse clinical scenarios, educators can expose students to rare cases, reinforce safety protocols, and assess performance objectively. This integration not only improves educational outcomes but also prepares future dentists for real-world challenges with greater precision and empathy. As technology evolves, the synergy between VR and simulation will continue to elevate dental training, making it more accessible, efficient, and student-centered.', 'VIDYEN/1000095', '09-10-2025', 2, 0),
(31, 'VIDYEN/1000101', 'AUT000031', 'Enhancing Student Engagement in Hybrid Learning Environments', 'Oral Presentations for research submission', 'Original Research Medical / Dental Education', 'EFFECT OF PERSONALITY TRAITS AND TRAINING IN AFFECTIVE COMPETENCIES ON GERIATRIC DENTAL CARE - A MIXED-METHODS STUDY AMONG DENTAL INTERNS', 'empathy, personality traits, geriatrics, dental education, affective competencies', 'Background: Delivering effective geriatric dental care requires both clinical skill and affective competence. While personality traits shape interpersonal tendencies, structured training may enhance empathy and patient engagement, especially in elderly care. Objectives: To assess the effect of dental interns’ personality traits and training in affective competencies on their performance in geriatric dental care. Materials and methods: A mixed-methods study was conducted among 89 final-year dental interns. Personality types were identified using the Myers-Briggs Type Indicator (MBTI). Affective competence was measured using the Jefferson Scale of Empathy–Health Professions Student version (JSE-HPS) before and after a structured three-day affective training program (blended module) focused on empathy, communication, and patient-centered care. Clinical interactions with geriatric patients were evaluated by faculty using structured rubrics. Quantitative data were analyzed using SPSS v26. Paired t-tests assessed pre- and post-training differences. ANOVA and multiple regression were used to correlate personality traits with affective performance. Qualitative data from reflective journals and patient feedback were analyzed thematically. Results: Post-training empathy scores improved significantly (mean increase = 12.6%, p < 0.001). Interns with dominant extroversion and feeling traits (e.g., ENFJ, ESFJ) showed the highest gains. Regression analysis revealed personality type and training participation as independent predictors of improved geriatric patient satisfaction (R² = 0.41, p < 0.01). Thematic analysis showed enhanced confidence, empathy, and rapport-building. Conclusion: Blended Learning module enhanced students interaction. Personality traits influence how effectively interns respond to affective training. Integrating personality-informed affective training in dental education may enhance geriatric care quality and empathy in future clinicians.', 'VIDYEN/1000101', '10-10-2025', 2, 0),
(32, 'VIDYEN/1000058', 'AUT000032', 'Enhancing Student Engagement in Hybrid Learning Environments', 'Oral Presentations for research submission', 'Original Research Medical / Dental Education', 'Toothopia: Transforming Oral Health Education Through Gamified Learning', 'Game-based learning, Oral health education, Health promotion, Gamification, Educational innovation', 'Abstract\r\n\r\nBackground: Oral health education often relies on didactic methods such as lectures or brochures, which fail to sustain engagement or foster behavioral change. “Toothopia” is a game-based pedagogical innovation designed to make oral hygiene education interactive, enjoyable, and effective for dental students. The game also serves as a dual-purpose tool for dental students, allowing them to act as facilitators while strengthening their own communication and teaching skills for imparting oral health education.\r\n\r\nObjectives: \r\n\r\n1. Develop a board-and-card game promoting oral hygiene knowledge and behavior.\r\n\r\n2. Evaluate the game’s educational impact on knowledge improvement and retention.\r\n\r\n3. Assess user satisfaction among participants and facilitators.\r\n\r\nMethodology\r\nA quasi-experimental, single-group study was conducted using consensus sampling. Participants (n=100) were final year dental students, divided into small play groups. “Toothopia” included four interactive card categories—Tooth Trivia, Yay or Nay, Brush Blaster, and Healthy Choices—each designed to reinforce essential oral hygiene concepts. Knowledge was assessed at three points: pre-assessment, post-assessment I, and post-assessment II (total marks: 15). A structured feedback questionnaire measured perceived usefulness, ease of understanding, and enjoyment.\r\n\r\nResults\r\nKnowledge scores saw a marked improvement after gameplay, rising from a pre-assessment mean of 8.00 to 11.71 (post-assessment I) and 11.82 (post-assessment II), with statistical significance (p < 0.001). User satisfaction ratings were high, with perceived usefulness and ease of understanding both scoring 4.02, and enjoyment at 3.70 on a 5-point scale.\r\n\r\nConclusion\r\n“Toothopia” proved effective in improving oral health knowledge and retention among dental students while creating an engaging, team-based learning environment. Dental students also reported enhanced confidence and communication skills. The study demonstrates the potential of gamified learning as a scalable, enjoyable, and evidence-based approach to oral health education.', 'VIDYEN/1000058', '11-10-2025', 2, 0),
(33, 'VIDYEN/1000104', 'AUT000033', 'Blended Learning Strategies in Dental Education', 'Oral Presentations for research submission', 'Narrative Review', 'From Ideas to Insights: A Review of Mind Mapping in Blended Learning', 'Mind mapping, Blended learning, Active learning, Visual learning, Constructivism, Higher education', 'Mind mapping, a visual and cognitive strategy for organizing and linking ideas, has emerged as an effective tool to enhance blended learning, which combines traditional classroom teaching with online instruction. By enabling learners to visualize relationships between concepts, mind mapping promotes critical thinking, active engagement, and deeper understanding. It helps students integrate diverse learning materials, encourages creativity, reflection, and self-directed learning, and supports meaningful knowledge construction. For educators, mind mapping offers a flexible approach to plan lessons, structure content, and assess students’ conceptual understanding. Digital mind mapping platforms further enhance collaboration, allowing real-time sharing, discussion, and co-creation of knowledge. The technique aligns with constructivist and cognitive learning principles, engaging both visual and verbal learning channels to improve retention and comprehension.\r\nDespite challenges such as time constraints, limited technological familiarity, and inconsistent integration into curricula, evidence highlights its effectiveness in enhancing learner motivation, engagement, and academic outcomes. This narrative review underscores the value of mind mapping as a practical, innovative strategy in blended learning, providing insights into how it can be systematically applied to make learning more interactive, student-centered, and outcome-driven.\r\n\r\n', 'VIDYEN/1000104', '13-10-2025', 2, 0),
(34, 'VIDYEN/1000126', 'AUT000034', 'Quality assurance in dentistry and its applications in Blended Learning', 'Yenvision- Lightning talk', 'Narrative Review', 'Written by Hand, Learned by Heart: Handwriting and Quality Education in Dentistry', 'handwriting, quality, learning', 'In the digital age, the practice of handwriting is rapidly diminishing, replaced by keyboards, tablets, and speech-to-text tools. While technological integration has transformed education, the decline in handwriting raises important questions, particularly in disciplines like dentistry that demand precision, memory retention, and strong cognitive-motor integration. This presentation explores the cognitive and pedagogical impact of handwriting on learning outcomes in dental education', 'VIDYEN/1000126', '13-10-2025', 2, 0),
(35, 'VIDYEN/1000113', 'AUT000035', 'Quality assurance in dentistry and its applications in Blended Learning', 'Oral Presentations for research submission', 'Narrative Review', 'Creativity and Digital Technology as Imperatives for Innovation in Dental Education and Oral Health Care', 'Dental education; Digital dentistry; Innovation; Creativity', 'Dental education and clinical practice are rapidly evolving, requiring innovative teaching methods to address emerging challenges such as technological advancement, interprofessional collaboration, sustainability, and equity. Innovation—the application of new and improved approaches—is closely linked to creativity, defined as generating ideas that are both novel and useful.\r\nSustained innovation in dental education demands environments that nurture creativity. The 5 A’s framework (Actor, Action, Artifact, Audience, and Affordances) offers a dynamic approach to understanding creativity within institutional contexts. Contributing factors include expertise in content, pedagogy, and technology (as described in the TPACK model), intrinsic motivation, and creativity-related processes such as design thinking, scenario planning, and professional learning communities. Institutional factors such as adequate resources, leadership support, and effective innovation management facilitate progress, while time constraints and limited technical or financial support remain key barriers.\r\nDigital technology is central to transforming both education and clinical care. Tools such as virtual patient simulations, augmented reality, CAD/CAM systems, e-learning platforms, tele-dentistry, 3D printing, and electronic health record (EHR) training enhance learning flexibility and clinical preparedness. In practice, digital impressions from intraoral scanners provide accuracy comparable to traditional methods, while digital planning and clear aligners improve outcomes in complex orthodontic cases. Technologies such as mobile health (mHealth) and artificial intelligence (AI) further expand access to care, particularly in underserved populations like those in sub-Saharan Africa.\r\nIn conclusion, digital dentistry has become integral to contemporary education and practice. Academic leaders must foster creativity, ensure equitable access to digital tools, and strategically invest in innovation to make technology a true enabler of efficient, inclusive, and personalized oral healthcare.\r\n', 'VIDYEN/1000113', '13-10-2025', 2, 0),
(36, 'VIDYEN/1000093', 'AUT000036', 'Blended Learning Strategies in Dental Education', 'Oral Presentations for research submission', 'Narrative Review', 'The Jigsaw Classroom: A Framework for Active and Shared Learning in Modern Education', ' Jigsaw Classroom, Collaborative Learning, Cooperative Education, Student Engagement', 'Background:\r\nCollaborative learning strategies have gained significant attention in modern education, with the Jigsaw Classroom emerging as a promising model for fostering student participation, communication, and interdependence. Originally conceptualised by Elliot Aronson in the 1970s, the Jigsaw method transforms passive classrooms into active learning environments by assigning each student a unique segment of content to master and teach to peers. This approach not only enhances academic engagement but also cultivates empathy, teamwork, and self-directed learning. It will examine its theoretical foundations, implementation strategies, outcomes, and challenges.\r\nAim:\r\nTo explore and synthesize the existing literature on the Jigsaw Classroom as a framework for active and shared learning across diverse educational settings\r\nMethods:\r\nA narrative review will be conducted on peer-reviewed articles, conceptual papers, and implementation reports from major academic databases such as PubMed, Scopus, ERIC, and Google Scholar. The inclusion criteria will focus on studies that discuss the Jigsaw technique within school, higher education, and professional training contexts. The selected literature will be analyzed thematically to identify patterns related to student engagement, collaborative learning outcomes, social skill development, and barriers to effective adoption.\r\nResults:\r\nThe review is expected to highlight the Jigsaw Classroom as an effective pedagogical tool that promotes learner autonomy, communication, and critical thinking. It is anticipated to demonstrate consistent improvement in academic performance and interpersonal dynamics among students, while also identifying practical challenges such as time constraints, uneven participation, and the need for teacher facilitation.\r\nConclusion:\r\nThis narrative review will provide a comprehensive understanding of how the Jigsaw Classroom serves as a framework for active and shared learning. By consolidating global evidence, it aims to support educators and policymakers in integrating cooperative learning models that nurture both intellectual and social competencies in the classroom.\r\n', 'VIDYEN/1000093', '13-10-2025', 2, 0),
(37, 'VIDYEN/1000085', 'AUT000037', 'Assessment and Feedback in Hybrid Learning Models', 'Oral Presentations for research submission', 'Original Research Medical / Dental Education', '“ Evaluating the effect of new teaching and learning method workshop to enhance the knowledge and attitude amongst the dental post graduate students using Kirkpatrick’s model’’', 'Kirkpatrick’s model’’', 'Introduction-Kirkpatrick model- education tool for evaluating and analyzing the results of educational, training and learning programs. MUHS University holds various courses for the staff and residents across all sections and levels, it is necessary for the residents to become familiar with new teaching and learning methods. Thus, this study intends to evaluate Kirkpatrick’s mode1- level 1( Reaction) and 2( learning) of new teaching and learning method  in  the Resident as a teacher workshop\r\nAIM – \r\n•	To evaluate the effect of “ Resident as a teacher workshop” to increase the knowledge and attitude amongst the dental post graduate students using Kirkpatrick’s model\r\nOBJECTIVES – \r\n•	1) To evaluate participants’ reaction toward the training course measured with a  pre-validated questionnaire after the workshop using Kirkpatrick s model (Level-1).\r\n•	2) To evaluate the effect of the program session on participants’ learning outcome measured by pre- and post-test questionnaire using Kirkpatrick’s model (Level -2). \r\n   Educational intervention done -A workshop entitled “Resident as a teacher workshop” will be held over 2 days (10 h total). In this workshop, participants will learn to teach and learn in small groups, team-based learning, role-playing, brainstorming, question and answer, and interactive lectures. T he content of the workshop will include delivering   an interactive lecture, small group teaching and learning, classroom management, time management, group dynamic and etc.\r\n•	Participants’ attitudes were evaluated in the first step via validated   questionnaire regarding the effect of training on their educational ability \r\n•	First level participants’ reaction toward the training course  was measured with a researcher-made questionnaire. The questionnaire had three categories of assessment: a) instructor assessment b) course content assessment and c) course support assessment that was scored based on a 5-point Likert scale from excellent to very weak.\r\nConclusion-Results showed that the training about new teaching and learning methods is an essential factor in delivering effective teaching by post graduate students .\r\n\r\n\r\n', 'VIDYEN/1000085', '14-10-2025', 2, 0),
(39, 'VIDYEN/1000120', 'AUT000039', 'Virtual Simulations and Hands-On Training: Bridging the Gap', 'Posters', 'Narrative Review', 'REVOLUTIONIZING DENTAL TRAINING: THE POWER OF SIMULATION-BASED LEARNING  Preparing the Next Generation of Dentists ', 'Simulation-based learning, dental education, haptics, virtual reality, augmented reality', 'Simulation-based learning is transforming the landscape of dental education by providing students with realistic, technology-driven opportunities to develop clinical competence before treating real patients. Moving beyond traditional training methods that relied on extracted teeth and bench-top models, modern simulation integrates virtual reality, augmented reality, phantom heads, and haptic feedback technologies. These tools immerse students in lifelike clinical scenarios where they can repeatedly practice, receive immediate feedback, and refine both their technical and decision-making skills in a safe environment.\r\n\r\nThe use of haptic simulators introduces a crucial tactile dimension, allowing learners to experience the sensation of working on various dental tissues such as enamel and dentin. This enhances psychomotor skill development and confidence while minimizing patient risk. Simulation-based learning also ensures standardized assessment, exposure to a wider range of clinical conditions, and improved competency outcomes.\r\n\r\nAs dental education continues to evolve, simulation offers a bridge between preclinical and clinical training. With future integration of artificial intelligence, big data analytics, and patient-specific virtual models, simulation-based education holds immense potential to personalize learning and elevate the standards of dental practice and patient care.', 'VIDYEN/1000120', '14-10-2025', 2, 0),
(40, 'VIDYEN/1000119', 'AUT000040', 'Speciality Presentation', 'Oral Presentations for Speciality Research', 'Original Research Medical / Dental Education', 'Development and Cytotoxic Evaluation of a Novel Non-Invasive Formulation Promoting Mucosal Keratinization in the Edentulous Ridge”', 'Moringa', 'Conventional dentures are commonly used to rehabilitate edentulous patients, but after tooth extraction, the residual ridge undergoes resorption, leading to a loss of mucosal support and denture instability. The mucous membrane covering the ridge, in a healthy state, provides resiliency and aids in denture retention. Exfoliative cytology is commonly used to assess these changes, and some studies suggest that using astringent gels can improve keratinization in denture wearers.\r\nHerbal medicines, including Moringa oleifera, are gaining popularity for their therapeutic properties.. The plant contains bioactive compounds such as flavonoids, vitamins, and minerals, which offer anti-inflammatory, antioxidant, and antimicrobial effects.  This study aims to evaluate the efficacy of Moringa oleifera oil in enhancing the keratinization of the edentulous ridge. Improved keratinization could help in the stabilization of dentures, leading to better support, comfort, and overall patient satisfaction.\r\n', 'VIDYEN/1000119', '14-10-2025', 2, 0),
(41, 'VIDYEN/1000092', 'AUT000041', 'Blended Learning Strategies in Dental Education', 'Posters', 'Narrative Review', 'Role of Blended learning in clinical dentistry training', 'Blended learning, dentistry', 'Clinical dentistry is complex and requires a multi-faceted approach to address the many needs of students. Blended learning is an educational model that integrates online digital media with traditional classroom methods. It represents a \"blend\" of face-to-face instruction and technology-mediated learning. In dental science, blended learning offers a flexible and integrated approach where students engage in theoretical coursework, develop practical skills, and receive clinical training. Online learning modules provide flexibility, allowing students to learn at their own pace, while in-person classes support active interaction with instructors and hands-on experience. Online components make it easier for practicing dentists to stay current with the latest advancements and encourages the use of new technologies and pedagogical approaches. By combining different teaching formats, blended learning keeps students engage, motivate and grasp complex concepts and build a deeper understanding. This integrated approach potentially improves both the theoretical knowledge and clinical proficiency. Despite these advantages, the successful implementation of blended learning in dental education requires addressing challenges such as technological limitations, faculty training, and balancing online and hands-on experiences. This approach plays a pivotal role in shaping the future of dental science education and ensuring to face the challenges and opportunities of modern dentistry.', 'VIDYEN/1000092', '14-10-2025', 2, 0),
(42, 'VIDYEN/1000046', 'AUT000042', 'Blended Learning Strategies in Dental Education', 'Oral Presentations for research submission', 'Narrative Review', 'The BLEND revisited - Reviewing the role of hybrid learNing in modern academicia - A SWOT ANALYSIS', 'blended learning, dental education, SWOT analysis', 'The evolving landscape of dental education demands pedagogical models that are both adaptive and impactful. Blended learning—an integration of traditional face-to-face instruction with digital modalities—has emerged as a transformative approach to enhance student engagement, clinical competence, and lifelong learning. This paper explores the implementation of blended learning in dental education through a strategic SWOT (Strengths, Weaknesses, Opportunities, Threats) analysis, with a focus on postgraduate training and public health dentistry.\r\nStrengths of blended learning include its flexibility, scalability, and potential for personalized learning. It enables asynchronous access to lectures, interactive modules, and evidence-based resources, fostering self-directed learning and critical thinking. In clinical settings, blended formats support case-based simulations and virtual patient interactions, enriching diagnostic and decision-making skills.\r\nHowever, weaknesses persist. Faculty readiness, digital infrastructure gaps, and inconsistent student motivation can hinder effectiveness. The lack of standardized evaluation metrics and limited hands-on exposure in virtual formats pose challenges, especially in skill-intensive domains like operative dentistry and community outreach.\r\nOpportunities abound in integrating blended learning with emerging technologies such as AI-driven assessments, 3D visualization, and mobile health platforms. These innovations can support interdisciplinary learning, enhance outreach in underserved areas, and promote tobacco cessation education through culturally sensitive digital campaigns. Moreover, blended models align with competency-based curricula and accreditation standards, offering avenues for curricular reform and faculty development.\r\nThreats include resistance to change, digital fatigue, and inequities in access among students from diverse socioeconomic backgrounds. Institutional inertia and policy constraints may also impede widespread adoption. Addressing these threats requires strategic planning, stakeholder engagement, and robust SOPs to ensure quality assurance and inclusivity.\r\nThis SWOT analysis underscores the need for visionary leadership, structured implementation, and continuous feedback mechanisms to optimize blended learning in dental education. By leveraging its strengths and opportunities while mitigating weaknesses and threats, institutions can foster a resilient, learner-centered ecosystem that prepares dental professionals for the complexities of modern practice and public health challenges.\r\n', 'VIDYEN/1000046', '14-10-2025', 2, 0),
(44, 'VIDYEN/1000064', 'AUT000044', 'Speciality Presentation', 'Posters', 'Interprofessional Research', 'Pemphigus Vulgaris -Navigating Diagnostic complexities and multidisciplinary treatment of Pemphigus Vulgaris ', 'oral manifestation, diagnosis, pemphigus vulgaris, multidisciplinary,', 'Background: Pemphigus vulgaris (PV) initially manifests in the oral cavity in 70-90% of patients, often presenting as desquamative gingivitis, yet diagnosis is frequently delayed. \r\nObjective: To demonstrate the critical role of dental professionals in early PV recognition through systematic clinical decision-making and multidisciplinary management protocols.\r\nCase Presentation: A patient presented with chronic desquamative gingivitis exhibiting persistent gingival erythema, friable epithelium, and positive Nikolsky sign. Diagnostic workup included perilesional biopsy revealing suprabasal acantholysis, direct immunofluorescence showing intercellular IgG deposits. \r\nClinical Decision Tree: Systematic evaluation identified critical referral indicators: persistent oral ulcers >2 weeks, treatment-resistant desquamative gingivitis, and positive Nikolsky sign. Urgent dermatological referral was initiated within 48 hours. \r\nMultidisciplinary Management: Coordinated care involved dentistry, dermatology, oral pathology, and oral medicine specialists. Treatment included systemic immunosuppression and specialized oral hygiene protocols. \r\nConclusions: Dentists occupy a unique position for early PV detection through desquamative gingivitis recognition. Structured clinical decision-making, established referral protocols, and multidisciplinary collaboration are essential for optimal outcomes. Enhanced dental education regarding oral manifestations of autoimmune diseases and standardized referral pathways can significantly improve patient prognosis in this potentially life-threatening condition.\r\n', 'VIDYEN/1000064', '14-10-2025', 2, 0),
(45, 'VIDYEN/1000106', 'AUT000045', 'Blended Learning Strategies in Dental Education', 'Posters', 'Narrative Review', 'Active Learning in Dental Pharmacology Through Crossword ', 'Dental education, Dental pharmacology, Active learning, Crossword puzzles, ', 'Active Learning in Dental Pharmacology Through Crossword Puzzles\r\nAbstract\r\nBackground:\r\nDental pharmacology is a core subject in dental education that requires students to memorize extensive information, including drug names, classifications, mechanisms of action, and therapeutic uses. Traditional lecture-based teaching methods often result in limited engagement, reduced motivation, and poor long-term retention. Active learning strategies, which emphasize student participation and interaction, have been shown to enhance understanding and memory. Among these strategies, crossword puzzles have emerged as an effective tool in medical education to reinforce learning, promote recall, and increase student engagement.\r\nAim:\r\nThe review aims to examine the effectiveness of crossword and puzzle-based learning as a supplementary educational strategy in dental pharmacology, with a focus on knowledge retention, student engagement, and learning satisfaction.\r\nMethods:\r\nA narrative synthesis of existing literature was conducted, highlighting studies that explored the use of crossword puzzles in medical and dental education. Pre-test and post-test assessments and student feedback from structured questionnaires in previous studies were reviewed to evaluate knowledge gain, engagement, and perceived usefulness. Key studies, such as those by Gaikwad and Tankhiwale (2012) and Patrick et al. (2018), were included to assess outcomes relevant to active learning in pharmacology.\r\nResults:\r\nEvidence from medical education demonstrates that crossword puzzles significantly improve students’ recall, understanding, and application of pharmacological concepts. Learners reported that puzzles were interactive, enjoyable, and useful in consolidating knowledge after lectures. Applying these findings to dental pharmacology suggests that puzzle-based learning can enhance active participation, reinforce complex concepts, and improve retention compared to traditional passive learning approaches.\r\nConclusion:\r\nCrossword and puzzle-based learning represents a simple, low-cost, and effective strategy to complement conventional teaching methods in dental pharmacology. By fostering engagement, self-directed learning, and cognitive reinforcement, such tools may improve knowledge retention and overall learning satisfaction among dental students.\r\n', 'VIDYEN/1000106', '14-10-2025', 2, 0),
(46, 'VIDYEN/1000068', 'AUT000046', 'Speciality Presentation', 'Oral Presentations for research submission', 'Original Research Medical / Dental Education', 'Plasma Cell Gingivitis: A Hypersensitivity Reaction Presenting as Gingival Enlargement- A Case Report', 'plasma cell gingivitis, gingival enlargement, gingivitis, periodontal health, hypersensitivity', 'Introduction:\r\nPlasma cell gingivitis (PCG) is a rare chronic inflammatory disorder mainly involving the gingival mucosa. It manifests as erythematous macules of bright red color, often confluent and sharply demarcated from the adjacent healthy tissues. Although lesions are generally asymptomatic, patients may experience a burning sensation and a feeling of local tension. The condition is difficult to manage, as topical corticosteroids usually produce only temporary improvement without long-term stability. The present report discusses the clinical presentation, diagnostic approach, and management of a PCG case diagnosed in March 2025.\r\n\r\nObjectives:\r\nThe objectives of this case report were to describe the clinical characteristics and histopathological features of plasma cell gingivitis and to evaluate the efficacy of photobiomodulation (PBM) combined with non-surgical periodontal therapy in symptom reduction.\r\n\r\nMethods:\r\nA 35-year-old male patient presented with intense erythema and edema affecting the buccal and lingual aspects of the gingival mucosa in both arches. Clinical assessment included evaluation of erythema, bleeding tendency, and patient-reported symptoms using standardized questionnaires. Periodontal charting revealed physiologic probing depth and attachment levels, though pronounced bleeding on probing was recorded. Multiple incisional biopsies were performed from representative gingival sites. Histopathological analysis showed dense plasma cell infiltration in the connective tissue, confirming the diagnosis of PCG. Following diagnosis, the patient underwent PBM therapy in conjunction with mechanical plaque removal and routine non-surgical periodontal debridement.\r\n\r\nResults:\r\nClinical evaluation after therapy revealed no substantial improvement in erythema or mucosal edema. However, there was a noticeable reduction in gingival bleeding and an improvement in the patient’s subjective comfort levels. The findings suggest partial therapeutic benefit, particularly in mitigating bleeding tendencies.\r\n\r\nConclusion:\r\nPlasma cell gingivitis remains a diagnostic and therapeutic challenge due to its chronic, relapsing nature and non-specific etiology. Although PBM therapy combined with non-surgical periodontal treatment showed limited improvement in this case, it resulted in reduced gingival bleeding and enhanced patient comfort. Further long-term studies are required to determine optimal treatment modalities and to elucidate the underlying etiopathogenesis of this rare mucosal condition. Early recognition, elimination of potential allergens, and maintenance of oral hygiene play critical roles in stabilizing the condition and improving clinical outcomes.\r\n', '', '14-10-2025', 2, 0);
INSERT INTO `abstract` (`id`, `registration_id`, `abstract_id`, `sub_theme`, `type_of_presentation`, `category_presentation`, `paper_title`, `keywords`, `paper_abstract`, `created_by`, `created_on`, `status`, `flag`) VALUES
(47, 'VIDYEN/1000091', 'AUT000047', 'Assessment and Feedback in Hybrid Learning Models', 'Posters', 'Narrative Review', '  Reflection as an Assessment Method in Undergraduate Clinical Training', 'reflection,assessment method,professional development', 'In undergraduate clinical training, especially in dentistry, students often struggle to connect textbook knowledge with real patient care. To help bridge this gap, reflection has become an essential educational tool. It allows students to think deeply about their clinical experiences, recognize what they did well, and identify areas for improvement. Reflection comes in two key forms: reflection-in-action, which happens during patient treatment and helps students make quick, informed decisions; and reflection-on-action, which occurs after the procedure, allowing students to evaluate their performance and plan for future growth. As its educational value became clearer, reflection also began to be used as a method of assessment. Tools such as reflective journals, self-assessments, and tutor-guided discussions now help measure how well students are thinking about their clinical practice. These methods promote critical thinking, self-awareness, and professional development. However, assessing reflection is complex. Because it is personal and subjective, grading can be inconsistent. To reduce this subjectivity, educators use clear rubrics that define what high-quality reflection looks like depth of insight, connection to clinical experience, and clear evidence of learning. Creating a safe and supportive environment is also key, encouraging students to reflect honestly rather than superficially. Reflection should be integrated into daily clinical activities through structured prompts and supported by trained faculty who give constructive feedback. When done well, reflection is more than just a task—it becomes a core part of learning and growth, helping shape thoughtful, competent professionals prepared for lifelong learning and patient-centred care.', 'VIDYEN/1000091', '15-10-2025', 2, 0),
(48, 'VIDYEN/1000140', 'AUT000048', 'Artificial Intelligence in dentistry', 'Oral Presentations for research submission', 'Narrative Review', 'Implementation of Artificial Intelligence in Dental curriculum: Transforming Practice, Education, and Equity ', 'Artificial Intelligence, Clinical Competence, Healthcare Workers', 'Artificial Intelligence (AI) is rapidly transforming healthcare and revolutionizing patient care. Preparing the AI qualified generation of healthcare professionals, it is necessary to integrate AI into medical and dental education curriculum.AI-integrated curriculum will improve clinical skills, make students digital literate, improve data interpretation skills, and ethical understanding for responsible use of AI driven technologies. Simulation-based learning and virtual patient models powered by AI gives students realistic training environments. AI tools help’s to enhance critical thinking, clinical reasoning and precision in diagnosis and treatment planning. AI-driven education aims to customise learning by analysing student’s performance and provide feedback tailored to individual learning needs.\nAs dentistry becomes increasingly digital, integrating AI into the dental curriculum is no longer optional, but makes it an essential part of education. Incorporating AI powered simulations, virtual patients, and adaptive learning tools can enrich both preclinical and clinical education, helping students build confidence, problem solving, and evidence-based learning.\nThis review gives an insight to broader implications of AI in dentistry with its legal, ethical, social dimensions and issues; such as data privacy and security. This presentation welcomes AI’s innovation while ensuring its integration into dental education and practice. Thus, such educational module should be organised in the institutes for advance education.\n', 'VIDYEN/1000140', '15-10-2025', 2, 0),
(56, 'VIDYEN/1000140', 'AUT000056', 'Blended Learning Strategies in Dental Education', 'Yenvision- Lightning talk', 'Narrative Review', 'Engaging Minds by a Collaborative and Inquiry Based Approach through pick and speak Topic Exploration\"', 'Active Learning, experimental learning, problem based learning', 'In today’s educational landscape, student centric classrooms have become the norm, emphasizing active participation and critical thinking as the heart of the learning process. This paper introduces an innovative teaching strategy that integrates collaborative learning and inquiry-based learning through an engaging, activity driven approach.\r\nProcess begins by assigning the students skills on a broad topic with prior preparation. The teacher then breaks this topic down into several subheadings, each representing a key concept or aspect of the main theme.Subheadings were written on chits and distributed randomly among the students. Each student selects a chit and presents their understanding of the assigned subtopic, depending on their own research, inquiry, reflection, and preparation.\r\nThis approach promotes student autonomy, peer learning, and active engagement, transforming the classroom into a space for shared knowledge construction. Random selection element introduces a sense of spontaneity and helps reduce presentation anxiety, while still ensuring that student remains accountable for their learning. Moreover, this method enhances critical thinking, communication skills, and deep conceptual understanding of the subject matter. It also gives the student the feel of achieving the biggest task easily when united approach is used.\r\nThe strategy is highly adaptable across different age groups and disciplines, and it aligns well with the goals of National Education Policy 2020, which advocates for inquiry driven, participatory, and holistic education.\r\nThis presentation will explore the theoretical foundations, implementation process, student feedback, and observed outcomes of using pick and speak based collaborative inquiry method in classroom settings. While the approach has shown promising results, initial apprehension among students and occasional gaps in topic coverage remain as areas for improvement.\r\n', 'VIDYEN/1000140', '15-10-2025', 2, 0),
(57, 'VIDYEN/1000084', 'AUT000057', 'Artificial Intelligence in dentistry', 'Oral Presentations for Speciality Research', 'Narrative Review', 'AI-Powered Endodontics: Enhancing Diagnosis, Treatment Planning, and Outcomes', 'Artificial Intelligence, Convolutional Neural Network, Artificial Neural Network, Diagnosis Endodontics', 'TITLE: \r\nAI-Powered Endodontics: Enhancing Diagnosis, Treatment Planning, and Outcomes\r\n\r\nABSTRACT:\r\n\r\nArtificial Intelligence (AI) is a rapidly evolving field that aims to facilitate problem-solving that typically requires human intelligence. It mimics cognitive functions such as reasoning, learning from experience, and adapting to new situations. AI has significantly improved diagnostic accuracy, treatment planning, reduced healthcare costs, thus enhancing overall patient experience. In dentistry, Artificial Neural Networks (ANNs) and Convolutional Neural Networks (CNNs) are revolutionising diagnostics and treatment planning. ANNs are used for predicting diseases like caries and periodontal conditions, personalizing treatment plans, and forecasting outcomes such as implant success. Meanwhile, CNNs excel in analyzing dental images, such as X-rays and CBCT, to detect cavities, periodontal disease, root canal issues, and even early signs of oral cancer. By automating these tasks, both technologies enhance diagnostic accuracy, improve treatment efficiency, and ultimately lead to better patient outcomes, making dentistry more precise and accessible.\r\n', 'VIDYEN/1000084', '15-10-2025', 2, 0),
(58, 'VIDYEN/1000105', 'AUT000058', 'Technology-Driven Innovations in Dental Education', 'Oral Presentations for research submission', 'Narrative Review', 'Transforming Dental Education Through Technology-Driven Innovations: A Narrative Review', 'Dental education; virtual reality; augmented reality; simulation; artificial intelligence; digital dentistry;apt', 'The rapid evolution of digital technologies has transformed dental education, shifting from traditional lecture-based and patient-dependent models toward immersive, technology-enhanced learning environments. This narrative review explores recent innovations such as virtual reality (VR), augmented reality (AR), artificial intelligence (AI), simulation, digital dentistry, and e-learning platforms, which have significantly influenced the pedagogical landscape—particularly following the disruptions of the COVID-19 pandemic. A comprehensive literature search was conducted in PubMed, Scopus, Web of Science, and Google Scholar for English-language studies using key terms related to technology-enhanced dental education. The articles were analyzed. Six major themes emerged: simulation-based learning with VR and haptic devices improved psychomotor precision and procedural confidence; AR enhanced spatial understanding and real-time visualization; e-learning and blended learning achieved comparable or superior cognitive outcomes relative to traditional instruction; AI facilitated personalized feedback, adaptive learning, and automated assessment; integration of digital workflows—including CAD/CAM and 3D printing—aligned academic training with evolving clinical practices; and technology-driven assessment tools improved objectivity, reproducibility, and feedback efficiency. Despite these advances, barriers such as high implementation costs, limited digital literacy among faculty, and insufficient long-term outcome validation remain challenges. Overall, technology-driven innovations are reshaping dental education toward a hybrid, student-centered, and competency-based model that fosters both preclinical and clinical skill development. Sustainable integration will depend on strategic faculty training, institutional investment, and continued pedagogical research. The future of dental education lies in adaptive, immersive, and data-informed learning ecosystems that prepare graduates to thrive in an increasingly digital clinical environment.', 'VIDYEN/1000105', '16-10-2025', 2, 0),
(59, 'VIDYEN/1000103', 'AUT000059', 'Faculty Development for Effective Hybrid Teaching', 'Yenvision- Lightning talk', 'Original Research Medical / Dental Education', 'Journey of a decade from SNACS to FEAT', 'Student support, faculty development', 'Brief description:\r\nAn exploratory journey with passion... The quest to find ways to identify & guide Students Needing Additional Curricular Support (SNACS) from 2014 to designing & conducting a structured & systematic faculty capacity-building program, Faculty Empowerment for Academic Training (FEAT) until 2024... The research-oriented, evidence-based journey that taught me more lessons and is still ongoing with more miles to go.\r\n\r\n\r\nPearl of wisdom message:\r\nGrit: The passion and perseverance of an individual faculty can metamorphose from a research project to university-level policy and best practice \r\n', 'VIDYEN/1000103', '16-10-2025', 2, 0),
(60, 'VIDYEN/1000129', 'AUT000060', 'Artificial Intelligence in dentistry', 'Oral Presentations for Speciality Research', 'Narrative Review', 'Integrating artificial intelligence into modern dental practice: a new era of precision and care ', 'Artificial intelligence, deep learning , automation', 'Introduction:\r\nArtificial Intelligence (AI) is revolutionizing healthcare, and dentistry is no exception. With the integration of machine learning algorithms, computer vision, and big data analytics, AI is enabling dentists to achieve greater precision in diagnosis, treatment planning, and patient management. From caries detection on radiographs to automated orthodontic analyses and prosthetic design, AI systems are steadily transforming conventional dental workflows into data-driven, predictive, and patient-centered processes.\r\n\r\nObjective:\r\nThis presentation aims to explore the applications, benefits, and challenges of integrating Artificial Intelligence in various branches of dentistry. It seeks to highlight how AI enhances diagnostic accuracy, improves clinical efficiency, supports dental education, and contributes to evidence-based personalized care.\r\n\r\nMethodology:\r\nA comprehensive review of current literature, published between 2015 and 2025, was conducted using databases such as PubMed, Scopus, and Google Scholar. Keywords included “Artificial Intelligence in Dentistry,” “Machine Learning in Oral Diagnosis,” and “Deep Learning in Radiology.” Relevant studies were analyzed to assess AI’s role in diagnostics, treatment planning, prosthodontics, orthodontics, and oral pathology. Clinical case examples and AI-based dental software were also reviewed to evaluate practical applications and performance outcomes.\r\n\r\nResults:\r\nAI demonstrated significant accuracy in image-based diagnostics, with several deep learning models achieving over 90% precision in caries and pathology detection. AI-assisted planning tools in orthodontics and implantology improved treatment predictability and reduced human error. In dental education, AI-based simulators enhanced skill acquisition and self-assessment. Despite its potential, challenges such as data privacy, cost of implementation, and lack of standardized protocols remain critical barriers to widespread adoption.\r\n\r\nConclusion:\r\nArtificial Intelligence is poised to redefine the future of dentistry by bridging technology with clinical expertise. Its integration promises improved diagnostic precision, efficient workflows, and personalized patient care. However, the transition requires ethical governance, adequate clinician training, and robust data frameworks. As dental professionals embrace AI, the synergy between human intelligence and machine learning will pave the way for a smarter, safer, and more efficient dental practice.\r\n\r\n', 'VIDYEN/1000129', '16-10-2025', 2, 0),
(61, 'VIDYEN/1000082', 'AUT000061', 'Speciality Presentation', 'Oral Presentations for Speciality Research', 'Original Research Medical / Dental Education', 'In Vitro Evaluation of ZnO Nanoparticles Against Enterococcus faecalis', 'Enterococcus faecalis, Nanoparticles, Zinc Oxide, Nanosphere, Nanorods ', 'Background: Persistent endodontic infections, frequently caused by Enterococcus faecalis, continues to be a major challenge in achieving successful root canal treatment. Conventional disinfection techniques often fail to eliminate bacteria residing within the complex anatomy of root canals. Nanoparticles (NPs) have emerged as promising antimicrobial agents due to their unique physicochemical properties.\r\nAim: This study aimed to compare the antimicrobial efficacy of zinc oxide (ZnO) nanoparticles—specifically nanorods (NR) and nanospheres (NS)—with 3% sodium hypochlorite (NaOCl) against E. faecalis (ATCC 29212 and a clinical oral isolate) using agar well diffusion, minimum inhibitory concentration (MIC), and time-kill assays.\r\nMethods: ZnO nanorods and nanospheres were synthesized and characterized via ultraviolet-visible (UV–Vis) spectrophotometry for optical properties, and transmission electron microscopy (TEM) to determine size, morphology, and distribution. Antimicrobial activity was assessed using agar well diffusion at volumes of 50–150 μL. MIC was determined by the broth microdilution method. Time-kill kinetics were evaluated by quantifying colony-forming units (CFUs) at 15-minute intervals over 90 minutes. Statistical analysis was performed using one-way ANOVA followed by Tukey’s post hoc test (P < 0.05).\r\nResults: UV–Vis analysis showed peaks at 360 nm for ZnO nanorods and 350 nm for ZnO nanospheres. TEM confirmed an average nanoparticle size of 20 nm for both morphologies. Agar well diffusion revealed that ZnO nanorods exhibited superior antibacterial activity compared to nanospheres, although 3% NaOCl remained the most effective at higher volumes (75–150 μL, P = 0.001). MIC values (mg/mL) against the ATCC strain were 18.75 for nanorods and 37.5 for nanospheres; against the clinical isolate, MICs were 37.5 (NRs) and 75 (NSs). In time-kill assays, all NPs demonstrated rapid bactericidal activity within 15 minutes against the ATCC strain, comparable to 3% NaOCl.\r\nDiscussion: ZnO nanoparticles, particularly nanorods, exhibit significant in vitro antimicrobial activity against E. faecalis, comparable to 3% NaOCl in certain assays. The enhanced efficacy of nanorods is attributed to their higher facet density, improved cell wall penetration, and increased reactive oxygen species (ROS) generation, leading to bacterial lysis. \r\nConclusion: These findings suggest potential applications of ZnO NPs in endodontic disinfection, such as incorporation into sealers or gutta-percha coatings. Future studies should assess their biocompatibility and long-term effectiveness in biofilm models.\r\n', 'VIDYEN/1000082', '16-10-2025', 2, 0),
(62, 'VIDYEN/1000123', 'AUT000062', 'Technology-Driven Innovations in Dental Education', 'Posters', 'Original Research Medical / Dental Education', 'USE OF POLL EVERYWHERE AS AN ASSESSMENT TOOL FOR JOURNAL CLUB DISCUSSIONS', 'Journal discussion, Assessment tool, Evaluation', 'Background/Introduction: The Poll Everywhere software allows us to create quiz, competitions at the end of lectures and engages the audience and helps in self-assessment. The aim of this study was to assess the plausible utility of Poll everywhere as an assessment tool in dental education, after the end every journal club discussion\r\nObjective:  \r\n•	Assess the usefulness of Poll everywhere in dental education, after the end every journal club discussion\r\n•	Assess the postgraduate student with a pre and post-test using Poll everywhere\r\nMethods: \r\nConvenient sampling design was used to recruit the samples. This study has been carried out with a sample of 16 postgraduate students of first, second and third year of their study. None of the students had used this tool before, so it is the first time they faced this type of methodology in the classroom. A set of 5 questions were created and presented to the Post graduate students at the end of journal club and their responses were recorded, the scores are also presented real-time. On the day of discussion, a pre-test was conducted to assess their level and at the end of the session a post-test was conducted to evaluate. \r\nResults: \r\nThe object of the activity as expressed by students was to sustain their attention in the journal club and also improved their understanding. The teacher’s motive for introducing digital game-based learning into the classroom was to motivate students’ engagement in meaningful learning.  The students’ responses, therefore, highlighted that the present activity system was associated with a more collective subject formation than evident in paper-based assessment and, indeed, in ‘normal’ academic endeavours in the course. All students unanimously stated that using poll as assessment made the sessions feel ‘Less stressful’ and ‘fun.’ Students claimed that despite the lack of out of class preparations for these tests, they felt they learnt and retained more knowledge from these assessments. \r\nConclusion: It is evident from these documented perceptions that the student’s level of test anxiety diminished when this method of assessment was applied compared to paper-based formative assessment. \r\n', 'VIDYEN/1000123', '16-10-2025', 2, 0),
(63, 'VIDYEN/1000060', 'AUT000063', 'Enhancing Student Engagement in Hybrid Learning Environments', 'Yenvision- Lightning talk', 'Original Research Medical / Dental Education', 'Learning Together: Lessons from a Peer Teaching Experiment in Pediatric Dentistry', 'peer learning, Undergraduate teaching, Mentoring, Reflective learning', 'Brief Description:\r\nTo enhance learning outcomes and prepare students for both theory and clinical examinations, our department implemented a peer learning model in Pediatric dentistry. Final-year BDS students were paired with first-year postgraduate students as mentors in small-group, interactive sessions that incorporated case discussions, flipped classroom activities, mini-assessments, and structured feedback.\r\nThis approach provided tangible benefits for both groups:\r\n•	Undergraduate students improved clinical reasoning, procedural skills, confidence, communication, and reflective thinking.\r\n•	Postgraduate mentors developed teaching and mentoring skills, leadership, and professional judgment, while deepening their own understanding of core pediatric dentistry concepts.\r\nThe program demonstrates that structured peer learning is a low-resource, high-impact strategy that fosters active learning, collaboration, and a supportive academic culture. In this 5-minute talk, I will share key experiences, insights, and lessons from implementing this model, showing how empowering students to teach and learn from each other transforms both learning and teaching in health professions education.\r\nPearl of Wisdom Message:\r\n“Teaching is the highest form of learning — and sometimes, your best teacher is your peer.”\r\n', 'VIDYEN/1000060', '17-10-2025', 2, 0),
(64, 'VIDYEN/1000152', 'AUT000064', 'Speciality Presentation', 'Yenvision- Lightning talk', 'Narrative Review', 'Overcoming the Fear: Implant Placement — It’s Possible, Not Impossible!', 'Implantology Prosthodontics Dental Surgery h h h h h h', 'The thought of placing dental implants often evokes apprehension among clinicians — fear of failure, anatomical challenges, or lack of confidence in surgical precision. However, implant dentistry today is no longer a domain of uncertainty but one of predictability and success when guided by proper planning, training, and understanding of biological principles.\r\nThis session aims to demystify the fears associated with implant placement by highlighting simplified clinical approaches, digital planning tools, and evidence-based protocols that enhance confidence and outcomes. Through real-life cases, common myths will be addressed, and practical insights will be shared on how to overcome hesitation and build surgical competence.\r\nWhether you are a beginner taking your first step into implantology or an experienced clinician seeking refinement, this talk will inspire you to shift your mindset from “What if it fails?” to “I can do it!” — proving that with the right knowledge and attitude, implant placement is possible, not impossible. ', 'VIDYEN/1000152', '17-10-2025', 2, 0),
(65, 'VIDYEN/1000136', 'AUT000065', 'Blended Learning Strategies in Dental Education', 'Posters', 'Original Research Medical / Dental Education', 'Emo-Dent AI', 'Emotion driven biometric system dental tutor : where technology meets empathy', 'Introduction\r\nArtificial intelligence (AI) has emerged as a transformative tool in dental education, enhancing diagnostic precision, simulation realism, and learning efficiency. Despite these advances, traditional AI applications often neglect the emotional and psychological factors that influence student performance. Emotional engagement and stress regulation play critical roles in skill acquisition, decision-making, and empathy formation among dental learners. To address this gap, Emo-Dent AI, an emotion-driven, biometric dental tutor, integrates affective computing and machine learning to adapt instructional strategies based on real-time emotional and physiological data.\r\n\r\nObjective of the Study\r\nThe primary objective of this study was to develop and assess the functionality of Emo-Dent AI, a system designed to detect learners’ emotional states through multimodal biometric feedback and adjust pedagogical delivery accordingly. Specific goals included evaluating its capacity to enhance learning motivation, reduce stress, and improve procedural accuracy among dental students. Additionally, the study aimed to explore the feasibility of integrating emotion-sensitive AI systems into existing virtual and augmented reality (AR/VR) dental training environments.\r\n\r\nMethodology\r\nEmo-Dent AI was developed using a multi modal affective framework combining facial expression recognition, voice tone modulation, heart rate variability, and eye-tracking analytics. Data were collected from undergraduate dental students during simulated clinical sessions utilizing AI-enabled cameras and biometric sensors. The system employed deep learning algorithms to interpret emotional cues and modulate feedback in real time by adjusting instructional pacing, complexity, or supportive guidance. Quantitative measures of performance, engagement, and stress were recorded, supplemented by qualitative student feedback through structured questionnaires.\r\n\r\nResult\r\nPreliminary findings revealed that students utilizing the Emo-Dent AI-enhanced learning module demonstrated improved procedural accuracy and retention compared to those using standard simulation tools. Emotion-adaptive interventions significantly decreased physiological stress indicators and increased subjective engagement levels. Students reported heightened motivation, improved focus, and enhanced empathy during simulated clinical interactions.\r\n\r\nConclusion\r\nThe results suggest that Emo-Dent AI effectively bridges emotional intelligence and artificial intelligence within dental education. By leveraging bio metric and affective data, the system personalizes learning experiences, optimizes stress management, and promotes emotional awareness in clinical training. Future research should focus on long-term evaluations of Emo-Dent AI’s impact on clinical competence and explore its integration into patient-centered care frameworks and professional empathy training.\r\n', '', '18-10-2025', 2, 0),
(66, 'VIDYEN/1000050', 'AUT000066', 'Blended Learning Strategies in Dental Education', 'Posters', 'Original Research Medical / Dental Education', 'CASE BASED LEARNING IN ORAL SURGERY-HYBRID MODE', 'Case-based learning, hybrid learning, oral surgery, undergraduate education, clinical reasoning,', 'Traditional lecture-based teaching in oral surgery has limitations in developing clinical reasoning and practical competencies. Case-based learning (CBL) represents an innovative pedagogical approach that integrates problem-solving with clinical application, particularly beneficial in blended learning.\r\nObjectives: This study aims to evaluate the effectiveness of case-based learning in oral surgery education for fourth-year undergraduate BDS students, assess improvements in clinical decision-making, diagnostic reasoning, and compare learning outcomes in hybrid (online and in-person) delivery modes.\r\nMethodology: Fourth-year BDS students were exposed to structured clinical case scenarios presented through a hybrid platform combining asynchronous online modules and synchronous in-person discussions. Cases represented diverse oral surgical conditions with varying complexity levels. Learning outcomes were evaluated using knowledge-based assessments, clinical reasoning exercises, and student satisfaction surveys.\r\nResults: Students demonstrated significant improvements in clinical reasoning skills, problem-solving abilities, and conceptual understanding compared to traditional teaching. The hybrid approach enhanced engagement and accommodated diverse learning preferences while maintaining academic rigor.\r\nConclusion: Case-based learning in hybrid mode effectively develops competencies essential for contemporary oral surgery practice. This approach prepares fourth-year BDS students to become reflective practitioners capable of managing complex clinical scenarios with evidence-based decision-', 'VIDYEN/1000050', '19-10-2025', 2, 0),
(67, 'VIDYEN/1000094', 'AUT000067', 'Global Collaboration in Hybrid Dental Education', 'Posters', 'Narrative Review', 'Crossing continents, sharing knowledge: The global hybrid learning in dentistry', 'Dentistry, hybrid approach, global health, competency-based , virtual classrooms', 'Crossing continents, sharing knowledge: The global hybrid learning in dentistry\r\n\r\nThe integration of digital technology into professional education has transformed traditional learning paradigms in fields such as health care, the fashion industry, business, aviation and military, etc. Dentistry, much like any other field in healthcare, benefits greatly from cross-cultural exchanges and learning from diverse practices worldwide. The school of dental education is rapidly evolving, driven by technological advancements and the need for precision in clinical practice. Digital simulation technologies offer a transformative solution, enabling students to reinforce practical application. However, simulation alone cannot fully replicate traditional learning outcomes. The hybrid approach improves confidence, reduces procedural errors, enhances critical thinking and accuracy and decision making. The landscape of education in clinical disciplines, particularly dentistry, underwent unprecedented challenges during the COVID-19 pandemic. A huge impact was felt in the regular clinical training. It paved the way more for hybrid education. The field of global health is defined as an area for study, research and practice that places a priority on improving health and achieving equity for all people worldwide. Oral health for all people and elimination of global health inequities through health promotion, disease prevention and appropriate oral care approaches that consider common determinants and solutions and acknowledge oral health as part of overall health. Notably, this frames oral health as a public health matter. The dentist has a duty to promote public welfare. The dental community must have a footprint in global oral health. Integrating competency-based global health into the dental curriculum will increase an understanding of the current global environment and perspectives that play a pivotal role in shaping the modern dentistry, by learning from international dental practices and integrating diverse experiences into education and practice towards the goal to raise awareness of the burden of oral disease, create opportunities for collaborations and partnerships with programmes, research and communities. Successful collaborations such as shared virtual classrooms, augmented realities, webinars, workshops, cloud-based patient simulations, haptic dental simulators, joint research networks have significantly enriched learning.While international practices offer valuable insights, it’s essential to adopt them thoughtfully to suit the local context to surpass certain challenges. Incorporating global perspectives in dentistry is not just a trend; it’s a necessity in today’s interconnected world.\r\n', 'VIDYEN/1000094', '19-10-2025', 2, 0),
(68, 'VIDYEN/1000153', 'AUT000068', 'Blended Learning Strategies in Dental Education', 'Posters', 'Original Research Medical / Dental Education', 'STUDENT–FACULTY CO-CREATION IN REVISITING  FULL MOUTH REHABILITATION - A PILOT STUDY.', 'Co-Creation, blended learning, full mouth rehabilitation', 'Introduction:\r\nCo-creation, where learners actively collaborate with educators to design curricular experiences, is emerging as a transformative approach in higher education. However, its application in Indian postgraduate dental education remains underexplored. As postgraduate students of Prosthodontics, we conducted a pilot study along with our faculty to evaluate a co-created and blended curriculum module on Full Mouth Rehabilitation (FMR), aiming to enhance engagement, confidence, and clinical relevance through an integrated mix of online and in-person learning experiences.\r\nAim:\r\nTo explore the feasibility and immediate impact of student–faculty co-creation in designing and delivering a blended learning module on FMR.\r\nMethods:\r\nWe conducted a one-month mixed-methods study in our postgraduate program. Eight students completed a pre-intervention survey assessing engagement, confidence, and perceived relevance of existing FMR teaching. In collaboration with faculty, we co-designed a two-week blended micro-module incorporating flipped classrooms, peer-led case discussions, and clinical scenario-based learning, supported by online preparatory materials and digital case resources. A post-intervention survey and focus group discussion were used to capture outcome changes and student perceptions.\r\nResults:\r\nFollowing the intervention, 80% of participants reported improved engagement, and 90% felt the module better reflected real-time clinical scenarios. Confidence in treatment planning for FMR improved substantially, with mean self-ratings increasing from 2.9 to 4.2 on a 5-point scale. Perceived relevance of the content improved from 3.1 to 4.5. Focus group feedback highlighted themes of shared ownership, increased motivation, and better connection between theory and clinical application. The blended delivery mode was particularly appreciated for its flexibility and ability to bridge conceptual and practical understanding. No negative feedback on the co-creation process was reported.\r\nConclusion:\r\nThis pilot study demonstrates that co-creation is both feasible and beneficial within the postgraduate dental curriculum. Involving learners in the design and delivery of a blended learning experience for complex content such as Full Mouth Rehabilitation led to improved engagement, confidence, and clinical relevance. Our experience supports further integration of co-creation and blended learning in health professions education and encourages exploration of their long-term impact on academic and clinical outcomes.\r\n\r\n', 'VIDYEN/1000153', '19-10-2025', 2, 0),
(69, 'VIDYEN/1000127', 'AUT000069', 'Blended Learning Strategies in Dental Education', 'Oral Presentations for research submission', 'Narrative Review', '\"Bridging the Gap : Integrating Technology and Tradition in Dental Education\"', 'Hybrid learning, Dental education, E learning, Digital pedagogy', '\r\nVIDYEN id : VIDYEN 1000127\r\n\r\nAbstract \r\nTitle : \"Bridging the Gap : Integrating Technology and Tradition in Dental Education\"\r\n\r\nThe integration of hybrid learning models in dental education has emerged as a transformative approach to enhance competency, flexibility, and student engagement. Combining traditional face-to-face instruction with online learning modalities, hybrid learning offers a comprehensive framework that accommodates diverse learning styles and adapts to the evolving landscape of dental education. This model facilitates dynamic, interactive sessions such as virtual simulations, case-based discussions, and asynchronous coursework, complemented by hands-on clinical practice. Such integration promotes active learning, self-directed study, and immediate feedback, thereby improving knowledge retention and skill acquisition. Additionally, hybrid learning addresses challenges associated with traditional education, including resource limitations and accessibility issues, by widening access to expert-led content and reducing geographic and financial barriers. Evidence from recent studies indicates that students demonstrate comparable or enhanced academic performance and clinical readiness in hybrid settings. The COVID-19 pandemic further accelerated the adoption of this model, compelling institutions to innovate and rethink pedagogical strategies. Despite its advantages, hybrid learning also presents challenges such as technological disparities and the need for faculty training. Moving forward, effective implementation requires careful curriculum design, technological infrastructure, and ongoing evaluation to optimize learning outcomes. Overall, hybrid learning in dental education holds significant potential to prepare future dental professionals with the necessary clinical skills, critical thinking, and adaptability required in modern healthcare ', '', '19-10-2025', 2, 0),
(70, 'VIDYEN/1000017', 'AUT000070', 'Blended Learning Strategies in Dental Education', 'Oral Presentations for research submission', 'Narrative Review', 'Flipping the Curriculum: A Scoping Review of the Flipped Classroom in Medical and Dental Education', 'Flipped Classroom\r\n\r\nMedical Education\r\n\r\nDental Education\r\n\r\nBlended Learning\r\n\r\nTraditional Lectures', 'Background Health Professions Education is evolving from traditional lectures toward active, student-centered models. The flipped classroom (FC), a blended learning approach, delivers foundational content before class to reserve in-person time for active learning. It is hypothesized to enhance clinical reasoning, practical skills, and self-directed learning (SDL) in medical and dental students.\r\nObjective This scoping review maps recent (2020-2025) literature from PubMed and Scopus using a PICO framework. It compares the flipped classroom (I) to traditional lectures (C) for medical and dental students (P) by assessing Outcomes (O) related to knowledge gain, skill acquisition, self-directed learning, faculty perceptions, and digital transition challenges.\r\nMethods Following the Arksey and O\'Malley framework, a systematic search of PubMed and Scopus (Jan 2020 - Oct 2025) was conducted using PICO-based keywords. After screening against inclusion/exclusion criteria, data from systematic reviews, meta-analyses, and primary studies were charted. Findings were then synthesized using a narrative, thematic analysis to identify key themes and research gaps.\r\nFindings Four major themes emerged:\r\nStudent Outcomes: The FC is consistently superior or equivalent to traditional lectures for knowledge gain. Meta-analyses confirm higher scores in both theoretical and practical skills, with particular strength in procedural skills like dental prosthodontics.\r\nSelf-Directed Learning: Students report higher engagement and critical thinking, but objective evidence for improved SDL skills is varied and often confounded by time management challenges.\r\nFaculty & Implementation: Faculty view the FC as pedagogically superior for student engagement, but implementation is hindered by practical barriers. The chief challenges are the substantial, front-loaded time investment for material creation and a lack of institutional/technological support.\r\nStudent Perceptions: The student experience is mostly favorable, citing heightened engagement and collaboration. However, this satisfaction is undermined by two key challenges: increased pre-class workload and dissatisfaction with peers who come unprepared.\r\nConclusion The flipped classroom is an effective strategy for integrating theory with practice in medical and dental education. Its success is not automatic, depending heavily on institutional support, faculty training, and careful instructional design. Future research should focus less on if it works and more on how it works best, specifically regarding long-term skill retention, cost-effectiveness, and objective measurement of SDL', 'VIDYEN/1000017', '19-10-2025', 2, 0),
(71, 'VIDYEN/1000097', 'AUT000071', 'Blended Learning Strategies in Dental Education', 'Posters', 'Original Research Medical / Dental Education', 'Integrating Artificial Intelligence into preclinical dental sciences: enhancing visualisation, understanding and skill assessment', 'artificial intelligence', 'Background: \r\nPreclinical dental education forms the foundation of a student’s journey toward becoming a skilled clinician. It requires mastering both theoretical concepts and precise manual dexterity. \r\nHowever, traditional teaching and assessment methods , such as tooth carving, cavity preparation, and manual grading , are often time-consuming, subjective, and dependent on instructor availability. With the growing influence of technology, Artificial Intelligence presents an opportunity to transform how dental students learn and refine their skills in the preclinical years. \r\n\r\nAim: \r\nTo explore the integration of AI-based tools and applications into preclinical dental subjects such as dental anatomy and skill-based exercises like cavity preparations, and to understand how these technologies can enhance visualization, practice, and feedback for students. \r\n\r\nMethod: \r\nA review of existing literature and emerging AI-driven educational tools, including 3D modelling systems for dental anatomy learning and machine-learning programs designed to evaluate preclinical work such as wax carvings and cavity preparations. \r\n\r\nResults: \r\nAI-based educational tools have shown promise in helping students visualize complex structures more clearly, practice more efficiently, and receive quicker, objective, and personalized feedback compared to conventional evaluation methods. \r\n\r\nConclusion: \r\nSince dentistry is ultimately a hands-on profession, integrating AI into preclinical education bridges the gap between learning and executing. It connects cognitive understanding with motor skill development, promoting accuracy, confidence, and consistency. The adoption of AI in preclinical training can make dental education more standardized, efficient, and engaging, preparing students better for real world clinical practice.', '', '19-10-2025', 2, 0),
(72, 'VIDYEN/1000070', 'AUT000072', 'Speciality Presentation', 'Oral Presentations for research submission', 'Original Research Medical / Dental Education', 'IN VITRO CHARACTERIZATION AND EVALUATION OF DENTAL RESIN COMPOSITE MODIFIED WITH BUTTERFLY PEA EXTRACT LOADED CHITOSAN NANOPARTICLES', 'Chitosan nanoparticles, Streptococcus mutans, Butterfly Pea Extract, cytocompatibility, Dental composite', 'ABSTRACT\r\nSUBTHEME: SPECIALITY PRESENTATION\r\nTITLE OF THE STUDY: IN VITRO CHARACTERIZATION AND EVALUATION OF DENTAL RESIN COMPOSITE MODIFIED WITH BUTTERFLY PEA EXTRACT LOADED CHITOSAN NANOPARTICLES.\r\nAUTHORS: Dr. JANANI KARUNAKARAN\r\n                       Senior Lecturer       \r\nINTRODUCTION: \r\nChitosan nanoparticles (CNPs) offer advantages in dentistry - biocompatibility, antimicrobial effects, dentin bonding enhancement, and enamel remineralization. Butterfly pea (Clitoria ternatea) extract has demonstrated inhibitory effects on Streptococcus mutans, a key contributor to dental caries. However, combining CSNPs with butterfly pea extract for incorporation into dental composites remains unexplored.\r\nAIM:\r\nAIM: To develop and characterize a dental composite resin modified with butterfly pea extract-loaded CNPs and evaluate its antimicrobial properties and cytocompatibility.\r\nOBJECTIVES:\r\n•	Synthesize and characterize CNPs loaded with butterfly pea extract.\r\n•	Incorporate these loaded nanoparticles into a standard Bis-GMA/TEGDMA dental resin composite.\r\n•	Assess antimicrobial activity against S.mutans and Cytocompatibility.\r\nMETHODOLOGY:\r\nGreen synthesis of CSNPs was conducted utilizing Butterfly Pea Extract (BPE). The characterization of the loaded nanoparticles was done through Fourier transform infrared analysis (FTIR) and UV-Vis Spectrophotometer. The size and shape of the nanoparticles was confirmed using Scanning Electron Microscope (SEM). The extract-loaded CNP powder was mixed into the resin matrix at 0.25 -1 wt%. Then the composite was light-cured and assessed for antimicrobial efficacy against Streptococcus mutans, antioxidant property and cytocompatibility was evaluated.\r\n \r\nGROUPING:\r\n• Group 1: Control resin composite (G1)\r\n• Group 2: Resin + 1 wt% CSNP (G2)\r\n• Group 3: Resin + 1 wt% Butterfly Pea extract (G3)\r\n• Group 4: Resin + 1 wt% Butterfly Pea extract-loaded CNP (G4)\r\n\r\nRESULTS:\r\n•	Among the tested samples, G3 showed the highest inhibitory activity against Streptococcus mutans, followed by G4 and G2, while G1 exhibits no activity. \r\n•	All the groups exhibited significant antioxidant activity with Group 4 showing the highest antioxidant activity.\r\n•	The cytotoxicity evaluation showed that all tested samples (G1- G4) exhibited cell viability values between 95.8% and 99.5%, comparable to the control (100%).\r\nCONCLUSION:\r\n    This synergy (Chitosan nanoparticles and Butterfly Pea Extract) could result in longer-lasting protection against dental caries and oxidative damage offering a promising approach for dental material development.', 'VIDYEN/1000070', '19-10-2025', 2, 0),
(73, 'VIDYEN/1000154', 'AUT000073', 'Speciality Presentation', 'Oral Presentations for Speciality Research', 'Interprofessional Research', 'From Molecular Signatures to Clinical Application: Development of Gene Panel for Malignant risk assessment  in Oral Submucous Fibrosis', 'Nanostring, oral submucous fibrosis, malignant transformation, oral squamous cell carcinoma', 'Introduction\r\nOral Submucous Fibrosis (OSMF) is a chronic debilitating disease, frequently found in the South East Asia, with malignant transformation rates of 7-30%. High throughput technologies like Tumor Signaling (TS) 360 Panel (NanoString platform) can aid in genetic expression profiling and to evolve a gene panel for early identification of malignant transformation in OSMF. \r\nObjectives of the study\r\nTo evaluate the gene expression profiling in OSMF and Oral Squamous cell carcinoma (OSCC)  using Nanostring nCounter platform and validate the top differentially expressed genes using Real time Polymerase Chain reaction (RT-PCR) and Immunohistochemistry (IHC) \r\nMethods\r\nInstitutional Ethics committee approval was obtained before the commencement of the study. The RNA was isolated from tissue samples (n=10) of OSMF, OSMF transformed into oral squamous cell carcinoma (OSCC) and healthy controls (HC). The analysis of gene expression was conducted on the nCounter® TS 360™ Paneland nSolver  using NanoString platform . Validation of the top upregulated genes was performed in larger samples using RT-PCR ( Healthy Control: 25; OSMF: 25; OSCC: 50) and IHC (Healthy Control: 30; OSMF:50; OSCC:160) using the standard protocols\r\nResults\r\nnSolver and Rosalind analysis was performed to check the differential expression among the various groups (HC, OSMF, OSCC), which showed significant upregulation of the following genes: BCL2A1, ADORA2A, MUC1, KLRB1, CD19, CD38, IRF4, PTCH1, CXXC5, PRDX6, CSF3R, ALDH1A3, FPR1, CCL19, MLANA, INHBA, CXCL 10, LAMC2, MMP9, NANOG, TP53.  Among the above-mentioned markers, upon validation using RT- PCR, revealed TP53, LAMC2, MMP9, BCL2A1, CD19 & CCL13 to show significant expression. Biomarkers namely p53, LAMC2 & MMP9 showed significant expression in IHC \r\nConclusion\r\nThe present study is the first of its kind to the best of our knowledge, assessing the gene expression using NanoString platform in in different clinical stages of OSMF & OSCC.  A panel of biomarkers namely TP53, LAMC2, MMP9, BCL2A1, CD19 & CCL13 aids to be potentially useful in identifying malignant transformation risk in OSMF. The developed biomarker panel can play  significant role in the identification of underlying molecular changes thereby serving as a promising diagnostic assay in early detection of high-risk cases of OSMF\r\nAcknowledgements and Funding\r\nThe study was funded by the Indian Council of Medical Research (ICMR) – Ref. No. 5/4/2-4/Oral Health/2021-NCD-II.\r\n', '', '20-10-2025', 2, 0),
(74, 'VIDYEN/1000138', 'AUT000074', 'Artificial Intelligence in dentistry', 'Yenvision- Lightning talk', 'Narrative Review', 'The Application of artificial intelligence in restorative Dentistry', 'Artificial intelligenceDiagnosisRestorative materialsBio materialsAesthetics', 'This review explores the transformative impact of artificial intelligence (AI) on restorative dentistry. By discussing the diagnostic processes, treatment planning, image analysis, prosthodontics, and material/biomaterial research, this study highlights the role of AI in optimizing precision and efficiency. It emphasizes personalized material selection, accelerated biomaterial research, and AI-enabled clinical workflows for enhanced patient outcomes. The review concludes with insights into the challenges, ethical considerations, and future trends, emphasizing the collaborative efforts needed for continued innovation in AI-driven restorative dentistrY', 'VIDYEN/1000138', '20-10-2025', 2, 0);
INSERT INTO `abstract` (`id`, `registration_id`, `abstract_id`, `sub_theme`, `type_of_presentation`, `category_presentation`, `paper_title`, `keywords`, `paper_abstract`, `created_by`, `created_on`, `status`, `flag`) VALUES
(75, 'VIDYEN/1000027', 'AUT000075', 'Virtual Simulations and Hands-On Training: Bridging the Gap', 'Oral Presentations for research submission', 'Systematic Review / Metanalysis', 'Effectiveness of  virtual reality in dental  education verses traditional methods : A Systematic review ', 'Virtual reality, dental education, teaching effectiveness, systematic review,  student engagement', 'Background:  Virtual reality (VR) has emerged as a transformative tool in education, offering immersive, interactive experiences that may enhance learning outcomes compared to traditional teaching methods. In dental education, where spatial understanding and psychomotor skill acquisition are critical, VR presents unique advantages.\r\n\r\nAim:  This systematic review evaluates the effectiveness of VR-based instruction relative to conventional approaches across cognitive, psychomotor, and engagement domains.\r\n\r\nMethods: Following PRISMA guidelines, a comprehensive search was conducted across PubMed, Scopus, Web of Science,up to May 2025. Eligible studies included randomized controlled trials and controlled observational studies comparing VR-based teaching with traditional methods in dental education. Primary outcomes assessed included knowledge retention, psychomotor performance, and clinical competence. Secondary outcomes included faculty instructional time, student engagement, and usability. Risk of bias was evaluated using the Newcastle-Ottawa Scale. \r\n\r\nResults: Seven studies involving 271 participants met inclusion criteria. VR was found to be less effective than hands-on training with physical models but superior to lecture-based and 2D imaging methods. Student evaluations consistently favored VR for its interactivity, realism, and engagement. Faculty time requirements were significantly reduced in VR-based instruction.\r\n\r\nConclusions: VR-based teaching offers a promising supplement to traditional dental education. While not a complete substitute for clinical experience, VR enhances visualization, engagement, and efficiency.\r\n', 'VIDYEN/1000027', '20-10-2025', 2, 0),
(76, 'VIDYEN/1000142', 'AUT000076', 'Speciality Presentation', 'Oral Presentations for Speciality Research', 'Original Research Medical / Dental Education', 'Synthesis, Characterisation& Evaluation of antimicrobial efficacy of Metallic Nanoparticles & Biopolymers against E.coli, P.aeruginosa, & L.acidophyllus ', 'Nano particles synthesis characterisation chitosan zinc titanium silver efficacy gel', 'INTRODUCTION:\r\nSuccessful Endodontic treatment depends upon various factors.Calcium hydroxide is the most common intracanal medicament used in Endodontics.But, it cannot be considered as a universal medication against all specimens harboured in root canal.Nanoparticles are a class of newer medicament which are hypothesised to have antibacterial effect due to its small nano structure.  The concept of using Nanoparticles in Endodontics as a new treatment modality was developed recently and their antibacterial efficacy is being evaluated by researchers \r\nAIM & OBJECTIVE:\r\nThe aim of the study is to evaluate the efficacy of silver, zinc, titanium,  chitosan nanoparticles and biopolymer gel against clinical pathogens\r\nMATERIALS & METHODS:\r\nThe teeth was radiographically conformed to have single canal.Cleaning and shaping was done and sodium hypochlorite was used as irrigant.The apex was sealed with GIC and was transferred into a microtube and was autoclave at 121 degree for 15 minutes.The teeth samples were infestated with pathogensand the inoculated samples were incubated in a bacteriological incubator.Colony forming units were evaluated by muller hinton agar plate count method.The samples were divided into 5 groups based on the medicament placed.The colony forming units in the treated samples were assessed by placing them on Muller hinton agar and performing a plate count.\r\nRESULTS:\r\nThe reduction in colony forming units before and after placement was done using chisquare test.\r\nCONCLUSION:\r\nThere was significant reduction in the colony forming in the groups where Nanoparticles were used as intracanal medicament making it a better alternative for the conventional intracanal medicament \r\n\r\n', '', '20-10-2025', 2, 0),
(77, 'VIDYEN/1000156', 'AUT000077', 'Speciality Presentation', 'Posters', 'Original Research Medical / Dental Education', 'Calm Through the Camera: Video Self-Modeling as a Game Changer in Autism Friendly Dentistry', 'Autism spectrum disorder, Pediatric Dentistry, Video self-modeling, Fear, Stress, Cortisol ', 'BACKGROUND/PURPOSE:\r\nAutism Spectrum Disorder (ASD) poses increasing challenges in pediatric dentistry due to its prevalence and associated anxiety during dental visits, leading to poor oral health. Video self-modeling (VSM), where children observe themselves performing tasks successfully, shows potential in reducing stress and enhancing adaptability. This study evaluates VSM\'s efficacy as a behavior guidance tool for improving dental care experiences in children with ASD.\r\n\r\nAIM/OBJECTIVE:\r\nThe aim of the study is to compare the efficacy between systematic desensitization and video self- modeling as behavior guidance technique and estimation of salivary cortisol levels in children with autism spectrum disorder.\r\n\r\nMETHODS: \r\nThis study included 30 children aged 6–12 years with ASD. Children were divided into two groups (n=15 each) using a lottery method: Group 1 received systematic desensitization, and Group 2 underwent video self-modeling. Saliva samples were collected from both the group before and after the interventions for cortisol estimation at an interval of two weeks.\r\n\r\nRESULTS: \r\nIn Group 1 (systematic desensitization), mean salivary cortisol levels decreased significantly from pre-intervention to post-intervention. In Group 2 (video self-modeling), cortisol levels also significantly declined. Comparison between groups showed no statistically significant differences in cortisol levels pre-intervention, post-intervention, or in mean reductions, although Group 2 exhibited a greater reduction in cortisol levels.\r\n\r\nCONCLUSION:\r\nBoth systematic desensitization and video self-modeling significantly reduced salivary cortisol levels in children with ASD, indicating stress reduction. However, the innovative technique of video self-modeling demonstrated a greater reduction in cortisol levels, emphasizing its effectiveness as a superior behavior guidance method for managing stress in pediatric dental settings.\r\n\r\n', 'VIDYEN/1000156', '20-10-2025', 2, 0),
(78, 'VIDYEN/1000053', 'AUT000078', 'Speciality Presentation', 'Oral Presentations for research submission', 'Original Research Medical / Dental Education', 'The antibacterial efficacy of aqueous cinnamon extract on potential periodontal pathogens: Invitro study.', 'cinnamon, periodontitis, periodontal pathogens', '\r\nBackground: Periodontitis is a complex disease with multiple component causes, like genetics, epigenetic influences and environmental factors, and the host immune inflammatory reaction all of which conspire to establish and propagate the periodontitis lesion. \r\nThe role of microorganisms in causing periodontitis is well established.\r\nCinnamon has been used as medicine in Indian and Chinese traditional medicine for decades. Many studies have evaluated the antimicrobial efficacy of Cinnamon on oral pathogens but very few literatures exist with respect to periodontal pathogens.\r\n\r\nAim: In this study the in vitro antibacterial activity of aqueous cinnamon extract on some potential periodontal pathogens (Porpyromonas gingivalis (Pg), Prevotella intermedia(Pi) ,Tannerella forsythia (Tf) and Fusobacterium nucleatum (Fn)) were evaluated using the minimum inhibitory concentration(MIC), zone of inhibition and time kill curve.\r\n\r\nMethod: MIC was determined by broth dilution. Disc diffusion method was used for zone of inhibition and serial dilution was used to determine time kill curve.\r\n\r\n Results: The MIC of Pi, Tf and Fn is 25mg/ml whereas of Pg its 12.5 mg/ml. At 75μ/ml of cinnamon extract the zone of inhibition for Tf and Pi was 18mm, for Pg it was 15mm and 8mm for Fn. At 2μ/ml only Pi was found to have a zone of inhibition of 13 mm. At 2hours all microbes were sensitive to cinnamon extract except Pg.\r\n\r\n Conclusion: The results of the study suggest that cinnamon has potential antimicrobial activity against periodontal pathogens and can be used as an alternative to synthetic substitutes for oral health care.\r\n', '', '20-10-2025', 2, 0),
(79, 'VIDYEN/1000056', 'AUT000079', 'Technology-Driven Innovations in Dental Education', 'Oral Presentations for research submission', 'Narrative Review', 'Revolutionising Peridoontal care in digital era', 'Digital dentistry,Periodontics,personalised dentistry', 'The rapid advancement of digital technologies is transforming dental and surgical education, demanding that clinicians develop not only technical and non-technical skills but also digital fluency. Tools such as e-learning platforms, and immersive simulations are replacing traditional learning methods by providing self-paced, engaging, and risk-free environments for skill acquisition. Digital simulations offer spatial replication and virtual practice that enhance clinical training.\r\nIn clinical settings, digital workflows—featuring CAD/CAM systems, digital radiography, and electronic health records (EHRs)—streamline diagnosis, treatment planning, and interdisciplinary collaboration. Precision-guided and robot-assisted surgeries exemplify digital transformation by offering accuracy and personalized care.\r\nTeledentistry is expanding access to oral healthcare, especially for remote and underserved populations, while EHRs and digital imaging improve care continuity and virtual consultation efficiency. Technologies like virtual reality (VR) and augmented reality (AR) enable surgical planning, rehearsal, and assessment, boosting learning and patient safety.\r\nAdditionally, 3D printing supports the creation of custom surgical guides and paves the way for future biologically compatible dental solutions. Artificial intelligence (AI) and machine learning (ML) are revolutionizing diagnostics and treatment by analyzing large datasets to enhance decision-making and reduce errors.\r\nIn summary, digital innovations are reshaping periodontal surgery and dental education by improving precision, expanding accessibility, and fostering personalized care. This digital shift marks a transformative era, preparing clinicians to meet evolving patient needs with enhanced tools and insights.\r\n', 'VIDYEN/1000056', '20-10-2025', 2, 0),
(80, 'VIDYEN/1000099', 'AUT000080', 'Technology-Driven Innovations in Dental Education', 'Oral Presentations for research submission', 'Narrative Review', 'Augmented reality in dental education', 'Augmented reality, digital dentistry', 'Title - Augmented reality in dental education.\r\n\r\nBackground: The integration of emerging technologies into dental education has transformed traditional teaching methodologies. Among these innovations, Augmented Reality (AR) has gained prominence for its ability to merge real-world clinical environments with interactive digital overlays, enhancing both cognitive understanding and psychomotor skill acquisition.\r\n\r\nObjective: This narrative review aims to explore the current applications of AR in dental education, analyze its pedagogical impact, and identify existing challenges and future opportunities for its integration into dental curriculum.\r\n\r\nMethods: A comprehensive literature search was conducted across major databases including PubMed, Scopus, and Web of Science. Studies published between 2010 and 2025 that evaluated AR-based tools or simulations in undergraduate and postgraduate dental training were reviewed. Key themes such as educational outcomes, student engagement, usability, and technological limitations were synthesized narratively.\r\n\r\nResults: The review revealed that AR applications have been effectively employed in various domains—operative dentistry, endodontics, oral surgery, and dental anatomy. AR-enhanced simulations have demonstrated improved visualization, procedural accuracy, and student motivation compared to conventional teaching methods. However, challenges persist, including high implementation costs, limited faculty expertise, and variability in learning assessment metrics.\r\n\r\nConclusion: Augmented Reality holds substantial promise in bridging the gap between theoretical learning and clinical practice in dentistry. While current evidence supports its educational value, further longitudinal and standardized research is essential to validate its effectiveness, cost-efficiency, and scalability within dental curriculum.', 'VIDYEN/1000099', '20-10-2025', 2, 0),
(81, 'VIDYEN/1000155', 'AUT000081', 'Speciality Presentation', 'Oral Presentations for Speciality Research', 'Original Research Medical / Dental Education', 'Bridging Dental-Forensic Education: An Analytical research of Tongue Prints on Age and Gender', 'Tongue Prints, Forensic odontology, Knowledge, Gender dimorphism.', '\r\nBACKGROUND: Forensic odontology plays a pivotal role in human identification, especially in scenarios involving mass disasters and criminal investigations. Tongue, a vital organ is recognised as a novel forensic tool rapidly flourishing in forensic odontology with its intricate pattern and difficulty to forge. With advancement in technologies, tongue prints have gained popularity in the field of forensic dentistry. \r\n\r\nAIM: To assess the clinical and impression analysis of tongue prints among age and gender\r\nAnd their reliability in personal identification\r\n\r\nMETHODS: The study was carried out in the dental OPD in the Department of Oral\r\nMedicine and Radiology for a period of 2 months comprising of 144 walk- in patients.\r\nClinical and impressional analysis of tongue characteristics such as color, shape, tip, width,\r\nSurface texture, and lateral borders was performed.\r\n\r\nRESULTS: The data recorded was statistically analysed using SPSS software version 23.\r\nChi-square test was performed to compare and assess the relation of tongue characteristics\r\nAmong age and gender. Mann-Whitney test was used to analyse the tongue width. A p-value\r\nOf &lt;0.05 was considered statistically significant. The tongue width marked higher\r\nSignificance framing it as a stalwart parameter of this study.\r\n\r\nCONCLUSION: This research has ensured that each individual has distinctive tongue features\r\nInferring that no two tongues are alike even among identical twins. The outcome of the  Present study emphasises the importance of forensic dental education . Despite its importance, this field in the undergraduate dental curriculum is relatively limited, resulting in gaps in knowledge and preparedness among future dental professionals. Thus there is a pressing need to enhance forensic-based education within dental programs to enhance learning outcomes. This will aid in incorporating dedicated modules with practical skills, bridging existing knowledge gaps, and equipping future dental professionals with essential skills in forensics.\r\n', 'VIDYEN/1000155', '20-10-2025', 2, 0),
(82, 'VIDYEN/1000135', 'AUT000082', 'Speciality Presentation', 'Oral Presentations for Speciality Research', 'Narrative Review', 'EMERGING ROLE OF 3D BIOPRINTING IN DENTAL BONE TISSUE ENGINEERING', '3D BIOPRINTING, BONE DEFECTS, TISSUE ENGINEERING ', 'Bone defects in the maxillofacial region present a significant clinical challenge in dentistry, often requiring grafting procedures that come with limitations such as donor site morbidity, risk of infection, and unpredictable outcomes. With the growing demand for patient-specific solutions and improved regenerative outcomes, 3D bioprinting has emerged as a promising technology in bone tissue engineering. This method allows precise layer-by-layer fabrication of scaffolds using biomaterials, cells, and growth factors to mimic the natural bone architecture. This review highlights the current applications, benefits, and challenges of 3D bioprinting in dental bone regeneration. It discusses commonly used bioinks, including hydrogels, and composite materials, along with their ideal properties such as biocompatibility, mechanical strength, and osteoconductivity.\r\nIn conclusion, 3D bioprinting represents a transformative approach for bone tissue engineering in dentistry. It offers the possibility of producing customized, biologically functional grafts that can enhance bone regeneration with greater precision and predictability. Further research and interdisciplinary collaboration are essential to translate this innovative technology from the laboratory to routine clinical practice.', 'VIDYEN/1000135', '20-10-2025', 2, 0),
(83, 'VIDYEN/1000158', 'AUT000083', 'Blended Learning Strategies in Dental Education', 'Oral Presentations for research submission', 'Narrative Review', 'Unlocking Learning : Integrating Escape Rooms into Classroom Education', 'Gamification, Educational Escape Rooms, Experiential Learning, Active Learning, Student Engagement', 'Background:\r\nGamification has become an increasingly effective educational approach, transforming traditional passive learning environments into engaging, student-centered experiences. By integrating elements of play, competition, and problem-solving into instruction, gamification fosters deeper involvement, motivation, and curiosity among learners. Among the diverse range of gamified strategies, educational escape rooms have recently emerged as a creative and immersive tool for teaching and assessment. These escape rooms simulate real-world challenges that require participants to apply knowledge, collaborate, and think critically within a time-bound and goal-oriented setting. This approach aligns with principles of experiential learning, active participation, and self-directed exploration—core components of modern educational pedagogy.\r\nObjective:\r\nThis narrative review aims to explore the integration of educational escape rooms into school and university curricula, emphasizing their theoretical foundations, educational impact, and implementation challenges. The review also discusses their role in promoting engagement, teamwork, and cognitive development, while identifying potential barriers and best practices for sustainable adoption in academic institutions.\r\nMethods:\r\nA comprehensive literature search was conducted in electronic databases including PubMed, Scopus, Web of Science, and Google Scholar. Keywords used in the search included “Gamification,” “Educational escape rooms,” “Experiential learning,” “Student engagement,” “Higher education,” and “Active learning.” The review focused on studies that evaluated the design, implementation, and educational outcomes of escape room–based learning activities. Relevant articles were analyzed to identify recurring themes, theoretical, observed benefits, and reported limitations.\r\nResults:\r\nEvidence from the reviewed literature indicates that educational escape rooms significantly enhance student motivation, engagement, and retention of knowledge. They promote teamwork, communication, and problem-solving skills while fostering creativity and a sense of accomplishment. The active participation required during these sessions encourages deeper conceptual understanding through experiential learning. Moreover, escape rooms have been found effective across disciplines—including medicine, nursing, dentistry, and engineering—demonstrating their versatility as a teaching tool. However, challenges to widespread implementation persist, such as complex design requirements, time constraints, limited institutional support, and the need for faculty training.\r\nConclusion:\r\nWhen effectively designed and aligned with curricular objectives, educational escape rooms represent a powerful and adaptable method to transform conventional classroom experiences into dynamic, collaborative, and meaningful learning environments. By bridging theory with practice, they cultivate essential skills such as critical thinking, teamwork, and self-directed learning, making them a promising strategy for the future of education.\r\n', '', '21-10-2025', 2, 0),
(84, 'VIDYEN/1000121', 'AUT000084', 'Enhancing Student Engagement in Hybrid Learning Environments', 'Oral Presentations for research submission', 'Original Research Medical / Dental Education', 'Enhancing Oral Pathology Learning through Gamification: A Study on First-Year Dental Students', 'Dental Education Gamification  Puzzle Active Learning Innovative Teaching Methods', 'Introduction:\r\nActive learning strategies are gaining traction in medical and dental education to enhance student engagement and knowledge retention. This study evaluates the impact of crossword puzzle gamification as an innovative teaching tool in oral pathology among first-year Bachelor of Dental Surgery (BDS) students.\r\n\r\nObjective: To evaluate the effectiveness of the gamified educational tool in enhancing knowledge levels among undergraduate dental students through pre- and post-intervention assessments. To explore undergraduate dental students and faculty perceptions, experiences, and satisfaction with the gamified learning tool. \r\n\r\nMethods:\r\nA comparative experimental study was conducted among first-year dental students, who were randomly divided into two groups. Group A (control group) was taught using conventional lecture-based methods, while Group B (test group) received the same content supplemented with a gamified crossword puzzle activity designed specifically for oral pathology topics. A validated pretest was administered to both groups before the intervention, and a posttest was conducted after the teaching sessions to assess learning outcomes.\r\n\r\nResults:\r\nPretest scores between the two groups were statistically comparable, indicating similar baseline knowledge levels. However, the posttest scores in Group B showed a significant improvement compared to Group A (p < 0.05), suggesting that the incorporation of crossword puzzles enhanced comprehension and retention of oral pathology concepts. Student feedback from the test group also indicated increased motivation, enjoyment, and active participation during the sessions.\r\n\r\nConclusion:\r\nGamification through crossword puzzles appears to be an effective and engaging educational tool for teaching oral pathology to first-year dental students. The structured integration of this method not only improved academic performance but also fostered a more interactive learning environment. This innovative approach, which has been granted copyright protection, demonstrates potential for broader application in dental and medical curricula to enhance student learning experiences.\r\n', 'VIDYEN/1000121', '22-10-2025', 2, 0),
(85, 'VIDYEN/1000164', 'AUT000085', 'Speciality Presentation', 'Oral Presentations for research submission', 'Original Research Medical / Dental Education', 'Evaluation of onset, duration, anesthetic efficacy and post operative analgesia of magnesium sulphate as an adjuvant with articaine and lignocaine – A Randomised controlled clinical trial. ', 'Anaesthetic effectiveness, Articaine, Lidocaine, Magnesium Sulfate, Postoperative analgesia', 'Background: Because of central sensitization and altered nociceptive processing, it is still difficult to provide effective anesthesia for mandibular molars with apical periodontitis and symptomatic irreversible pulpitis. The anesthetic and analgesic effectiveness of inferior alveolar nerve blocks (IANBs) using 2% lidocaine and 4% articaine, both with and without the addition of 75 mg magnesium sulfate (MgSO₄), was evaluated in this randomized clinical trial.\r\nMethods:45 patients between the ages of 20 and 60 were divided into four groups at random: Group 1 received lidocaine; Group 2 received lidocaine plus magnesium sulfate; Group 3 received articaine; and Group 4 received articaine plus magnesium sulfate. Electric pulp testing was used to measure the start of anesthesia, the Heft-Parker Visual Analog Scale (HP-VAS) was used to measure intraoperative pain, and postoperative analgesia was tracked at 2, 6, 12, 24, and 48 hours.\r\nResults: All groups had statistically similar preoperative pain scores (p = 0.982). Group 4 had the highest intraoperative comfort and the fastest anesthesia onset (2.36 ± 0.45 minutes, p < 0.001). At all time points, Group 4 had consistently lower postoperative pain levels (p < 0.05), followed by Group 2, Group 3, and Group 1.\r\nConclusion: MgSO₄ and Articaine together greatly enhanced the onset of anesthesia and the management of postoperative pain. According to these findings, MgSO₄ can be used as a useful adjuvant to improve IANB success when treating inflamed mandibular molars endodontically.', 'VIDYEN/1000164', '22-10-2025', 2, 0),
(86, 'VIDYEN/1000148', 'AUT000086', 'Speciality Presentation', 'Oral Presentations for Speciality Research', 'Narrative Review', 'Hope or Hype? A Critical Look at the Emerging Role of Probiotics in Oral Cancer Prevention', 'carcinogenesis, probiotics, prevention, oral cancer ', 'Probiotics have been studied extensively. Probiotics modulate immune responses, enhance anti-tumoral immune surveillance, promote apoptosis of cancer cells, suppress tumor progression by their cytotoxic activity, and target the epigenetic changes in the cancer cell population.  Probiotics intervene in early stage of carcinogenesis by reducing pro-inflammatory cytokines, activating phagocytes, accentuating natural killer cells activity. Some in-vitro studies have concluded the antiproliferative and cytotoxic action of strains of lactobacillus and bifidobacterium. Since probiotics are biologically active, there are concerns about systemic infection, gene transfer, altered metabolism, and excessive immune stimulation in susceptible individuals. Probiotics in carcinogenesis is a promising field of research, and clinical trials are required to assess and analyze the real-world impact on cancer incidence.\r\nKeywords: carcinogenesis, probiotics, prevention, oral cancer \r\n', 'VIDYEN/1000148', '22-10-2025', 2, 0),
(87, 'VIDYEN/1000150', 'AUT000087', 'Blended Learning Strategies in Dental Education', 'Yenvision- Lightning talk', 'Narrative Review', 'Where Hands Meet Screens:Hybrid Dental Education', 'Hybrid Learning, Flipped Classroom, Dental Education, Active Learning, Educational Innovation', 'Title: Where Hands Meet Screens: Hybrid Dental Education\r\n\r\nAuthor: Dr. Mangesh Shenoy BDS, MDS\r\n\r\nBackground:\r\nThe rapid evolution of educational technology has transformed how learning occurs in health sciences. Dental education, traditionally rooted in face-to-face instruction, is now embracing hybrid models that integrate online flexibility with hands-on engagement. These approaches go beyond physical boundaries, fostering active, student-centered learning and improving accessibility.\r\n\r\nObjectives:\r\n• To explore innovative hybrid models applicable to dental education.\r\n• To highlight evidence-based benefits of flipped, team-based, and case-based learning.\r\n• To identify challenges and propose strategies for effective hybrid implementation.\r\n\r\nContent Overview:\r\nThis presentation discusses how hybrid learning models—combining online asynchronous modules with in-person interactive sessions—are reshaping dental classrooms.\r\nExamples include flipped classrooms for foundational sciences, team-based clinical case discussions, and integration of digital tools for self-directed learning.\r\nEmerging research demonstrates improved student engagement, satisfaction, and performance compared to conventional teaching methods (Ali et al., J Dent Educ, 2023).\r\n\r\nChallenges & Solutions:\r\nKey barriers include technology access, faculty readiness, and time constraints. Successful implementation depends on structured learning management systems (LMS), faculty training, and digital literacy support.\r\n\r\nConclusion:\r\nHybrid models redefine the dental classroom by bridging boundaries of space and time, creating a flexible, inclusive, and interactive learning experience. The goal is not to replace traditional teaching but to enhance it—transforming the classroom into a connected learning ecosystem.\r\n\r\nKeywords: Hybrid Learning, Flipped Classroom, Dental Education, Active Learning, Educational Innovation', 'VIDYEN/1000150', '22-10-2025', 2, 0),
(88, 'VIDYEN/1000157', 'AUT000088', 'Speciality Presentation', 'Posters', 'Systematic Review / Metanalysis', 'Photogrammetry in Implant Dentistry ', 'Photogrammetry, Implantology, Digital Workflow ', 'Photogrammetry in Implant Dentistry \r\n \r\nDigital intraoral scanning has revolutionized modern dentistry, merging precision with innovation to create a seamless experience for both clinicians and patients. The cutting-edge technology utilised not only enhances diagnostic accuracy but also streamlines treatment workflows, allowing for quicker, more personalized care which opens the door to a new era where precision, speed, and patient comfort converge in the art of dentistry. The goal of IOS is to record with precision the 3D geometry of an object with various IOS technologies such as Triangulation, Confocal Imaging, Active Wavefront Sampling & Stereophotogrammetry. Triangulation in intraoral scanning is limited by its depth of field, sensitivity to surface reflectivity, and requirement for a clear line of sight. Confocal imaging is slower with a limited field of view and higher complexity, while Active Wavefront Sampling is sensitive to motion artifacts and environmental factors, requiring careful calibration. The 1900s marked a rise in Photogrammetry\'s use in cartography and architecture, with aerial photography during World War I making it essential for mapping and reconnaissance. In Mid-20th century dentists began using stereophotogrammetry to capture 3D images of dental structures, enhancing diagnostics and treatment planning. This technique uses precise photographic measurements to create highly accurate 3D models using reference points, eliminating the need for superimposed images to create highly accurate 3D models aiding in complete arch rehabilitation offering improved outcomes, reduced chair time, and enhanced patient comfort.', 'VIDYEN/1000157', '22-10-2025', 2, 0),
(89, 'VIDYEN/1000132', 'AUT000089', 'Speciality Presentation', 'Oral Presentations for research submission', 'Narrative Review', 'Prosthodontic Management of Malpositioned Implants', 'Dental implants, Prosthodontic management, Implant malposition, Biomechanics, Angled abutments', 'Abstract\r\nIntroduction:\r\nDental implants have revolutionized prosthodontic rehabilitation by providing function and aesthetics comparable to natural dentition. However, improper implant positioning can compromise biomechanics, aesthetics, and long-term success. Malpositioned implants often result from anatomical limitations, surgical errors, or prosthetic miscommunication, leading to functional and aesthetic challenges that require both surgical and prosthodontic intervention.\r\nObjective of the Study:\r\nThe study aims to evaluate the prosthodontic management of malpositioned implants by identifying causes, biomechanical implications, and the various surgical and non-surgical treatment modalities available to correct or compensate for implant misalignment.\r\nMethodology:\r\nA comprehensive literature-based approach was adopted to analyze existing data on implant positioning principles, biomechanics, and management techniques. The study reviews clinical procedures, including implant repositioning, osteotomy, distraction osteogenesis, and prosthodontic rehabilitation using prefabricated, angled, and custom abutments.\r\nResults:\r\nFindings highlight that accurate implant placement is critical for prosthesis longevity and aesthetics. Malpositioning, whether due to bone morphology or surgical error, increases non-axial loading and stress concentrations that may lead to implant failure. Successful management depends on case-specific evaluation — surgical correction is indicated for severe misalignments, whereas prosthetic interventions using angled or custom abutments can restore functionality and aesthetics in moderate cases. Advanced techniques such as CAD-CAM customized abutments and distraction osteogenesis have improved treatment predictability.\r\nConclusion:\r\nProsthodontic management of malpositioned implants requires an interdisciplinary, restorative-driven approach beginning from treatment planning to final prosthesis delivery. Efforts should be made to avoid or reduce complications by proper patient selection and evaluation. A careful evaluation and understanding of the bone anatomy and architecture, including the quantity and quality of available bone, are mandatory before implant placement, thereby enhancing implant success and patient satisfaction.\r\n', '', '22-10-2025', 2, 0),
(90, 'VIDYEN/1000147', 'AUT000090', 'Speciality Presentation', 'Oral Presentations for Speciality Research', 'Original Research Medical / Dental Education', 'A comparative study of smartphone photography and radiovisiography in diagnosis of occlusal caries', 'Occlusal caries, Radiovisiography ,Smartphone photography, Visual examination,.  ICADS II, Sensitivity', 'ABSTRACT\r\nObjective: Dental caries is one of the most prevalent chronic conditions. The purpose of this study is to compare the efficiency of radiovisiography and smartphone photography to that of visual examination in order to find the best method of assessment and maintenance of physical/digital record of evidence of the presence of caries for tele-dentistry and student education.\r\nMaterials and Method: A total of 70 occlusal caries in permanent teeth were assessed by three systems, by two experienced examiners using standardized method (ICDAS II) in vivo. The photographic equipment included a Samsung Galaxy S20 and radiovisiography was done with DIGORA FMX reader and software. The teeth were evaluated and assessed at two thresholds, i.e, S1(enamel caries) and S2 (Dentin caries), with visual examination as reference standard for the statistical analysis. The statistical calculations were done using the R software 3.6 3 version. The inter examiner agreement, sensitivity, specificity, positive and negative likelihood ratios were calculated.\r\nResults: Smartphone photography showed significantly higher sensitivity (100%) for lesions limited to enamel, than radiovisiography (59%), with no significant differences in specificity. Sensitivity and specificity for dentinal caries in both systems showed no difference. Cohen’s kappa value of inter-examiner repeatability for the two systems were similar.\r\nConclusion: According to (ICDAS II) Smartphone photography proved to be a better adjunct and aid to visual examination in diagnosis of enamel caries, while both smartphone photography and digital radiography served as good adjuncts in diagnosis of caries involving the dentin. \r\n', 'VIDYEN/1000147', '22-10-2025', 2, 0),
(91, 'VIDYEN/1000165', 'AUT000091', 'Artificial Intelligence in dentistry', 'Oral Presentations for Speciality Research', 'Narrative Review', 'Artificial Intelligence in Dentistry: Transforming Oral Health Care and Public Health Practice', 'Artificial Intelligence, Dentistry, Diagnostic Systems,Machine Learning, Public Health Dentistry', 'Background:\r\nArtificial Intelligence (AI) is revolutionizing healthcare by enabling machines to emulate human intelligence, analyze vast datasets, and support evidence-based decision-making. In dentistry, AI offers immense potential for improving diagnostic accuracy, treatment precision, patient management, and public health outcomes.\r\nObjective:\r\nThis narrative review explores the current and emerging applications of AI in dentistry and public health dentistry, highlighting its benefits, challenges, and implications for the future of oral healthcare.\r\nMethods:\r\nA comprehensive literature review was conducted across databases such as PubMed, Scopus, Web of Science, and Google Scholar to identify relevant studies on AI in dental and public health contexts. The selected articles were analyzed to summarize the applications, advantages, and limitations of AI-driven systems in clinical and community settings.\r\nResults:\r\nAI has demonstrated significant utility across diagnostic dentistry, prosthodontics, endodontics, orthodontics, and implantology through image analysis, computer-aided design, and predictive modeling. In public health dentistry, AI facilitates health protection through real-time disease surveillance, health promotion via personalized risk assessment, and improved health service efficiency through automated data management, tele-consultations, and decision-support systems. AI-based tools enhance literature review processes, electronic health record management, and policy formulation through automated evidence synthesis. Despite its promise, AI implementation faces barriers such as system complexity, high costs, limited training, and data-related biases.\r\nConclusion:\r\nAI is transforming dentistry from both clinical and public health perspectives by improving diagnostic precision, enhancing preventive care, and supporting data-driven decision-making. While it cannot replace human judgment, AI serves as a powerful adjunct, augmenting professional capabilities and paving the way toward precision and equitable oral healthcare.\r\n\r\n', 'VIDYEN/1000165', '23-10-2025', 2, 0),
(92, 'VIDYEN/1000101', 'AUT000092', 'Artificial Intelligence in dentistry', 'Posters', 'Original Research Medical / Dental Education', 'Enhancing Preclinical Dental Education through AI: Intelligent Image Analysis for Learning Kennedy Classification and RPD Design Principles', 'AI Image analysis, rpd classification, preclinical prosthodontics, ', 'Background:\r\nAccurate identification of partially edentulous arches and proper Removable Partial Denture (RPD) design are core skills in preclinical prosthodontics. Students often struggle with classification accuracy and component selection due to limited visual experience and variability in feedback. Artificial Intelligence (AI) can offer objective, consistent, and immediate guidance that supports self-directed learning and reinforces theoretical understanding.\r\nObjective:\r\nThis study aimed to evaluate the educational effectiveness of an AI-driven image analysis tool developed to identify Kennedy classifications and suggest appropriate RPD design components, and to assess its impact on students’ diagnostic accuracy, learning confidence, and engagement.\r\nMethods:\r\nAn AI tool was developed using a dataset of 1,200 images of partially edentulous maxillary and mandibular arches (Kennedy Classes I–IV, with modifications). The system automatically identifies edentulous spaces, assigns a Kennedy classification, and suggests relevant RPD components such as major connectors, rests, and direct retainers.\r\n80 IInd BDS students participated in a two-phase learning module. In Phase 1, students analyzed and classified a set of clinical images without AI assistance. In Phase 2, they repeated a comparable set of cases using the AI tool, which provided immediate visual feedback and suggested design components. Accuracy of classification and RPD design, completion time, and self-reported confidence were recorded and compared between phases.\r\nResults:\r\nThe AI system correctly identified Kennedy classifications in 94% of test images and suggested appropriate design components in 89% of cases, as validated by faculty experts. Student performance improved significantly with AI support: classification accuracy increased from 67% to 85%, and RPD design accuracy from 63% to 82%. The average completion time per case was reduced by 22%. Post-session surveys indicated that 91% of students felt the AI feedback enhanced their understanding, and 88% reported increased confidence in RPD design planning.\r\nConclusion:\r\nUsing an AI-based image analysis tool as a learning aid in preclinical prosthodontics improved diagnostic accuracy, efficiency, and student confidence. The results demonstrate that AI can complement traditional teaching by providing individualized, objective feedback that reinforces conceptual learning. Integrating such tools into dental curricula could modernize prosthodontic education and better prepare students for clinical decision-making.', 'VIDYEN/1000101', '23-10-2025', 2, 0),
(93, 'VIDYEN/1000066', 'AUT000093', 'Artificial Intelligence in dentistry', 'Posters', 'Narrative Review', 'Integrating AI for Precise Periodontal Disease Diagnosis', 'Artificial Intelligence, Periodontal diseases, Diagnosis ,Precision Dentistry.', 'The periodontium, comprising gingiva, periodontal ligament, cementum, and alveolar bone, plays a vital role in maintaining oral health, with its disruption leading to periodontal diseases among the most prevalent oral conditions worldwide. Traditionally, periodontal diagnosis has relied on clinical parameters such as probing depth, bleeding on probing, clinical attachment loss, and radiographic assessment, all of which are susceptible to examiner variability and subjectivity. Advances in artificial intelligence (AI), particularly machine learning (ML) and deep learning (DL), offer opportunities to enhance precision, objectivity, and reproducibility in periodontal diagnostics. AI-based systems have demonstrated high accuracy in identifying dental plaque (up to 99%), detecting gingivitis (67–78%), and predicting periodontal disease severity (47–75.5%) through clinical and radiographic data. Customized convolutional neural networks (CNNs), Mask R-CNN architectures, and the DualFit model have been applied to panoramic, periapical, and bitewing radiographs, achieving diagnostic accuracies between 47% and 81% for alveolar bone loss detection. Additionally, fuzzy rule-based systems (FRBS) and integration with electronic dental records (EDRs) present avenues for personalized risk assessment, treatment planning, and surgical decision support. Despite these advances, limitations persist, including variability in real-world performance, dependence on training data quality, and lack of interpretability. AI is therefore best positioned as a decision-support tool, augmenting clinician expertise rather than replacing it. By standardizing evaluations and reducing diagnostic variability, AI has the potential to revolutionize periodontal diagnostics, fostering precision and personalized dentistry while ensuring patient centred care.', '', '23-10-2025', 2, 0),
(94, 'VIDYEN/1000149', 'AUT000094', 'Virtual Simulations and Hands-On Training: Bridging the Gap', 'Oral Presentations for Speciality Research', 'Systematic Review / Metanalysis', 'Oral Potentially Malignant Disorders and Oral Cancer- AI in Diagnostic and Prognostic evaluation', 'Oral Cancer', 'Abstract\r\nIntroduction: Oral Potentially Malignant Disorders (OPMDs) represent a crucial stage for early cancer interception.The integration ofArtificial Intelligence (AI), particularly Machine Learning (ML) and Deep Learning (DL)offers a promising path to enhance diagnostic accuracy, predict malignant transformation, and improve prognostic assessment. This systematic review aims to synthesize the current evidence on the application, performanceand clinical utility of AI models in the detection and management of OPMDs and Oral Squamous Cell Carcinoma (OSCC).\r\nMethods: A comprehensive search was performed across databases, identifying relevant studies focusing on AI applications in OPMD and OSCC. Data extraction included study characteristics (e.g., year, author, journal), AI task (e.g.,diagnosis,prognosis, lymph node metastasis prediction) and specific DL/MLmodels.The risk of bias was assessed using appropriate toolssuch as QUADAS-2 for diagnostic accuracy studies.\r\nResults:Thirty nine relevant articles were identifiedwith a significant concentration of publications in 2024 and 2025, reflecting the field\'s rapid growth. Key areas of AI application include: (1) Automated Diagnosis from clinical images and histopathology; (2) Prognosis and Risk Prediction, particularly for occult lymph node metastasis; and (3) Systematic Evaluations, with several recent studies constituting systematic reviews themselves. Preliminary data indicate high diagnostic accuracy for AI models in classifying malignant and potentially malignant lesions.\r\nConclusion: AI demonstrates substantial potential as a decision-support tool in the diagnosis and risk stratification of OPMDs and OSCC. While the number of published studies is increasing, further high-quality, externally validated, prospective studies are required to establish the clinical feasibility and generalizability of these AI-powered solutions in a real-world setting.\r\n\r\n', 'VIDYEN/1000149', '24-10-2025', 2, 0),
(95, 'VIDYEN/1000112', 'AUT000095', 'Enhancing Student Engagement in Hybrid Learning Environments', 'Oral Presentations for research submission', 'Narrative Review', 'Cinemeducation: An Innovative Approach to Building Communication and Professional Competencies in Health Professional Education', 'Cinemeducation, Competency-based learning, Communication skills, Professionalism, Reflective learning, Health education', 'Background:\r\nCompetency-based education in health professions emphasizes not only clinical proficiency but also the development of communication, empathy, ethical judgment, and professionalism. Traditional classroom methods often focus heavily on cognitive skills while leaving affective and behavioral domains under-addressed. Cinemeducation, the use of cinema as an educational tool, offers an engaging and reflective approach to bridge this gap by bringing human experiences, emotions, and ethical dilemmas to life.\r\n\r\nObjective:\r\nTo explore the role of cinemeducation as an innovative teaching-learning method for developing communication and professional competencies among health professional learners.\r\n\r\nMethodology:\r\nCinemeducation involves the purposeful selection of films or film clips depicting health-related or socially relevant scenarios, followed by guided reflection and discussion. Learners observe interpersonal communication, ethical decision-making, and professional behavior as portrayed in the narrative. The method draws upon experiential and reflective learning frameworks—such as Kolb’s learning cycle—allowing learners to connect cinematic experiences with real-life clinical practice. Facilitated group discussions, reflection notes, or short assignments help reinforce understanding and self-assessment.\r\n\r\nDiscussion:\r\nFilms evoke emotional engagement and empathy, promoting deeper learning beyond conventional lectures. Through visual storytelling, students critically analyze both effective and ineffective communication styles, patient–provider relationships, teamwork, and moral reasoning. For instance, movies like Patch Adams, The Doctor, and Munna Bhai M.B.B.S. highlight compassion and patient-centered care, while Taare Zameen Par encourages sensitivity towards individual differences. Such sessions can help dental and health science learners internalize core professional values and understand the human dimensions of healthcare.\r\n\r\nConclusion:\r\nCinemeducation transforms passive learning into active, emotionally resonant, and reflective experiences. It complements traditional teaching by cultivating empathy, professionalism, and communication competence—qualities essential for competent and compassionate healthcare delivery. Integrating cinemeducation into competency-based curricula can therefore contribute meaningfully to shaping holistic and socially responsible professionals.', 'VIDYEN/1000112', '24-10-2025', 2, 0);
INSERT INTO `abstract` (`id`, `registration_id`, `abstract_id`, `sub_theme`, `type_of_presentation`, `category_presentation`, `paper_title`, `keywords`, `paper_abstract`, `created_by`, `created_on`, `status`, `flag`) VALUES
(96, 'VIDYEN/1000163', 'AUT000096', 'Speciality Presentation', 'Oral Presentations for Speciality Research', 'Systematic Review / Metanalysis', 'ROLE OF CURCUMIN AS A PHOTOSENSITIZER IN PHOTODYNAMIC THERAPY IN THE MANAGEMENT OF ORAL MUCOSAL LESIONS -A SYSTEMATIC REVIEW ', 'Curcumin, PDT, Photodynamic therapy, Role ', 'BACKGROUND: Oral Mucositis is a common complication of Radiotherapy and Chemotherapy in head and neck Tumours, which presents as Erythema, Atrophy/Ulceration of Oral Mucosa.Beyond various conventional treatment Modalities used;Photodynamic therapy proves to be a non invasive treatment which helps in reducing the lesion size. Curcumin as a photosensitizer helps in Reducing the Adverse effects compared to that of other Photosensitizers.\r\n\r\nAIM: To assess the effectiveness of Curcumin mediated photodynamic therapy in the management of Oral Mucositis\r\n\r\nOBJECTIVE: The primary objective of the study is to gather the evidence on effectiveness of curcumin as a photosensitizer in the management of oral mucositis.\r\n\r\nMETHODOLOGY : The studies included in this systematic review were identified by a comprehensive search from electronic databases such as PubMed, Google Scholar, Science-Direct, Cochrane Library and Web of Science for last 5 years using keyword search and MeSH terms. Studies using Curcumin as a Photosensitizer in photodynamic therapy for the treatment of oral Mucositis and that have compared the intervention either with placebo or with other drugs were included.  Articles were selected based on the selection criteria. Titles, abstracted full texts of studies identified from the literature search were screened by two authors. For all the included studies, data extraction and analysis of studies for quality were performed. Risk of bias was analysed by Rev-man Version 5 Risk of Bias tool. The outcome measure was to evaluate the reduction in the lesion grading,Adverse effects \r\n\r\n\r\nRESULTS: The search yielded a total of 23 Articles from Web of Science, PubMed, Cochran and Science direct and 421 from Google scholar out of which 3 articles were included based on the eligibility criteria. From the 3 included studies, a sample size of 122 patients have proven that Curcumin acts as a Photosensitizer and can be used in the treatment of oral mucositis. Among the three clinical trials, one had low risk of bias and other two had intermediate risk of bias.\r\n\r\nCONCLUSION: Therefore, well-designed randomised clinical trials with an adequate sample size and sufficiently long-term follow- up period as well as standardised laser parameters are highly recommended to validate the effectiveness of PDT.The follow up period ranged from 1 to 3 months, which seems inadequate, and longer follow-up periods could have yielded different results. Therefore, further studies with sufficient follow-up period are recommended to make definitive conclusions on the effectiveness of PDT in the treatment of oral mucositis.\r\n', 'VIDYEN/1000163', '24-10-2025', 2, 0),
(97, 'VIDYEN/1000163', 'AUT000097', 'Speciality Presentation', 'Oral Presentations for Speciality Research', 'Systematic Review / Metanalysis', 'ROLE OF CURCUMIN AS A PHOTOSENSITIZER IN PHOTODYNAMIC THERAPY IN THE MANAGEMENT OF ORAL MUCOSAL LESIONS -A SYSTEMATIC REVIEW ', 'Curcumin, PDT, Photodynamic therapy, Role ', 'BACKGROUND: Oral Mucositis is a common complication of Radiotherapy and Chemotherapy in head and neck Tumours, which presents as Erythema, Atrophy/Ulceration of Oral Mucosa.Beyond various conventional treatment Modalities used;Photodynamic therapy proves to be a non invasive treatment which helps in reducing the lesion size. Curcumin as a photosensitizer helps in Reducing the Adverse effects compared to that of other Photosensitizers.\r\n\r\nAIM: To assess the effectiveness of Curcumin mediated photodynamic therapy in the management of Oral Mucositis\r\n\r\nOBJECTIVE: The primary objective of the study is to gather the evidence on effectiveness of curcumin as a photosensitizer in the management of oral mucositis.\r\n\r\nMETHODOLOGY : The studies included in this systematic review were identified by a comprehensive search from electronic databases such as PubMed, Google Scholar, Science-Direct, Cochrane Library and Web of Science for last 5 years using keyword search and MeSH terms. Studies using Curcumin as a Photosensitizer in photodynamic therapy for the treatment of oral Mucositis and that have compared the intervention either with placebo or with other drugs were included.  Articles were selected based on the selection criteria. Titles, abstracted full texts of studies identified from the literature search were screened by two authors. For all the included studies, data extraction and analysis of studies for quality were performed. Risk of bias was analysed by Rev-man Version 5 Risk of Bias tool. The outcome measure was to evaluate the reduction in the lesion grading,Adverse effects \r\n\r\n\r\nRESULTS: The search yielded a total of 23 Articles from Web of Science, PubMed, Cochran and Science direct and 421 from Google scholar out of which 3 articles were included based on the eligibility criteria. From the 3 included studies, a sample size of 122 patients have proven that Curcumin acts as a Photosensitizer and can be used in the treatment of oral mucositis. Among the three clinical trials, one had low risk of bias and other two had intermediate risk of bias.\r\n\r\nCONCLUSION: Therefore, well-designed randomised clinical trials with an adequate sample size and sufficiently long-term follow- up period as well as standardised laser parameters are highly recommended to validate the effectiveness of PDT.The follow up period ranged from 1 to 3 months, which seems inadequate, and longer follow-up periods could have yielded different results. Therefore, further studies with sufficient follow-up period are recommended to make definitive conclusions on the effectiveness of PDT in the treatment of oral mucositis.\r\n', 'VIDYEN/1000163', '24-10-2025', 2, 0),
(98, 'VIDYEN/1000146', 'AUT000098', 'Speciality Presentation', 'Yenvision- Lightning talk', 'Interprofessional Research', 'Interdisciplinary Management in Dentistry', 'Interdisciplinary management, education, patient care, comprehensive care', 'An interdisciplinary approach to patient management in dentistry involves a collaborative team of specialists from different dental fields to create a comprehensive and integrated treatment plan for complex cases. This approach enhances patient care by combining expertise from areas like oral from  various specialities to achieve better functional, aesthetic, and long-term outcomes, which can lead to reduced treatment time, fewer complications, and improved patient satisfaction compared to single-discipline care. This talk will highlight on Integrated patient care, Comprehensive evaluation and patient care.', 'VIDYEN/1000146', '25-10-2025', 2, 0),
(99, 'VIDYEN/1000128', 'AUT000099', 'Quality assurance in dentistry and its applications in Blended Learning', 'Oral Presentations for Speciality Research', 'Narrative Review', 'Enhancing Quality Assurance in Dental Education: Applications and Impact of Blended Learning', 'Quality Assurance; Dental Education; Blended Learning; Curriculum Evaluation; ', 'ABSTRACT FOR SCIENTIFIC PAPER\r\nTitle of the Poster: Enhancing Quality Assurance in Dental Education: Applications and Impact of Blended Learning\r\nName of the student: Dr. Kadeejathul Shahazia\r\nConference Registration ID: VIDYEN/1000128\r\nYear of study: III MDS-Public Health Dentistry\r\nInstitute name: Yenepoya Dental College, Mangalore\r\nAbstract: Enhancing Quality Assurance in Dental Education: Applications and Impact of Blended Learning\r\nINTRODUCTION:\r\nQuality assurance (QA) is essential for maintaining educational and clinical standards in dental education. With the rise of blended learning that integrates digital and traditional methods, the need for robust QA mechanisms has increased. QA ensures that teaching, learning, and clinical outcomes remain consistent and effective despite the shift toward technology-enhanced education.\r\nOBJECTIVE:\r\nTo review existing quality assurance mechanisms in dental education and explore their application in blended learning environments.\r\nMETHODOLOGY:\r\nA review of published articles and institutional documents from databases such as PubMed, Scopus, and Google Scholar was conducted. Studies from 2015–2025 were analyzed for QA principles, frameworks, and implementation strategies relevant to hybrid teaching models in dentistry.\r\nRESULTS:\r\nThe review showed that traditional QA models focus on curriculum and faculty standards, while blended learning requires additional emphasis on digital content quality, online teaching effectiveness, and assessment reliability. Institutions integrating structured QA frameworks reported improved learning outcomes and student satisfaction.\r\nCONCLUSION:\r\nQuality assurance remains a cornerstone of dental education. Incorporating QA principles into blended learning enhances educational quality, accountability, and adaptability, helping institutions align with global standards and prepare competent dental professionals for the digital era.\r\n', 'VIDYEN/1000128', '25-10-2025', 2, 0),
(100, 'VIDYEN/1000173', 'AUT000100', 'Artificial Intelligence in dentistry', 'Posters', 'Original Research Medical / Dental Education', 'Impact of AI-Created Visual Explainers on Patient Understanding of Dental Procedures: A Randomized Controlled Study', 'Ai, Ai visuals, dental education, ai created, artificial intelligence ', 'Background:\r\n\r\nEffective patient education is essential for informed consent and treatment acceptance in dentistry. Conventional brochures and verbal counselling may not suit all literacy levels or learning styles. Generative AI enables rapid creation of personalized, visual explainers that may improve comprehension and reduce patient anxiety.\r\n\r\nAim:\r\nTo evaluate the effectiveness of AI-generated visual explainers in improving patient understanding of dental procedures, compared to standard patient education methods.\r\n\r\nMethod:\r\nA randomized controlled trial was conducted among 240 adult dental outpatients (18–70 years) seeking consultation for root canal treatment, scaling, or dental implants. Participants were allocated to either the intervention group (AI-generated visual explainers with short animations) or control group (standard brochure plus verbal counselling). Primary outcome was immediate comprehension (0–20 score). Secondary outcomes included 7-day recall, dental anxiety (MDAS), decision conflict (DCS), time to consent, and treatment acceptance intent. Data were analysed using independent t-test and chi-square tests.\r\n\r\nResults:\r\nComprehension scores were significantly higher in the AI group compared to control (15.35 vs 12.35, p < 0.001). The AI group also showed improved 7-day recall (7.68 vs 6.50, p < 0.001), lower anxiety (MDAS: 11.47 vs 14.64, p < 0.001), and reduced decision conflict (35.45 vs 42.87, p = 0.0002). Time to consent was shorter (15.68 vs 18.74 mins, p = 0.0002). Treatment acceptance intent was higher in the AI group (72.9% vs 58.9%, p = 0.03).\r\n\r\nConclusion:\r\n\r\nAI-generated visual explainers significantly enhanced patient comprehension and recall while reducing anxiety and improving decision-making and treatment acceptance. Generative AI is a promising tool to strengthen patient education and counselling efficiency in dental practice.', 'VIDYEN/1000173', '25-10-2025', 2, 0),
(101, 'VIDYEN/1000186', 'AUT000101', 'Speciality Presentation', 'Oral Presentations for Speciality Research', 'Original Research Medical / Dental Education', 'Analyzing the efficacy of Nigella Sativa against Periodontal pathogens-A Network Pharmacology and Molecular docking study', 'Network Pharmacology; Molecular Dynamic Simulation; Nigella sativa,Periodontitis', 'INTRODUCTION:Periodontal disease, caused by bacterial pathogens, leads to inflammation and damage to the periodontium. Traditional treatments, including antibiotics, face challenges due to rising antibiotic resistance. Nigella sativa (black seed), known for its antimicrobial, anti-inflammatory, and antioxidant properties, offers a promising alternative therapy. \r\nOBJECTIVE:This study aims to explore in silico the potential efficacy of bioactive compounds of Nigella Sativa in combating periodontal pathogens using network pharmacology and molecular docking.\r\nMETHODOLOGY:55 bioactive compounds of Nigella\r\nSativa were identified, of which 8 bioactive compounds and their potential targets were predicted using PubChem based on available literature. Of the 8 compounds, 2 compounds passed the Absorption, Distribution, Metabolism, Excretion and Toxicity analysis and were utilized for Molecular docking analysis to evaluate the binding potential with the bacterial proteins involved in periodontal disease.\r\nRESULTS:Network pharmacology analysis revealed that 8 bioactive compounds of Nigella Sativa interact with key targets involved in periodontal disease, including inflammatory cytokines and bacterial enzymes. Molecular docking studies demonstrated that squalene bioactive compounds exhibited strong binding affinities (-6.8 kcal/mol and-6.1 kcal/mol) to targets, suggesting its potential to inhibit bacterial growth. \r\nCONCLUSION:The results provide evidence that bioactive compounds of Nigella Sativa could serve as a promising adjunctive therapy in the management of periodontal disease. Further experimental studies are warranted to validate these findings.', 'VIDYEN/1000186', '25-10-2025', 2, 0),
(102, 'VIDYEN/1000002', 'AUT000102', 'Technology-Driven Innovations in Dental Education', 'Oral Presentations for Speciality Research', 'Narrative Review', 'Traditional Approaches to Oral Health Education: Revisiting Their Role and Effectiveness in the Modern Era', 'Oral health education, traditional methods, lectures, demonstrations, and oral hygiene ', 'Background:\r\nOral health is an essential component of overall well-being, yet poor oral hygiene practices remain common among young adults in developing countries. Traditional oral health education (OHE) methods such as lectures, demonstrations, posters, and printed materials have been the cornerstone of preventive dentistry for decades. These approaches are based on the assumption that increasing knowledge leads to improved behavior; however, their long-term effectiveness in sustaining behavioral change remains questionable.\r\n\r\nAim:\r\nTo review the effectiveness of traditional oral health education methods in improving oral health behavior and oral hygiene status among young adults.\r\n\r\nMethodology:\r\nA narrative review was conducted using PubMed and Google Scholar databases to identify articles published between 2011 and 2023. Keywords included Oral Health Education, Traditional Methods, Oral Hygiene Practices, and Oral Health Behavior. Only peer-reviewed, English-language, full-text articles were included. The findings were thematically analyzed to assess the impact of lectures, demonstrations, and printed materials on oral health outcomes.\r\n\r\nResults:\r\nStudies consistently show that traditional OHE methods enhance oral health knowledge and result in temporary improvements in oral hygiene indices. Demonstration-based and repeated education sessions produce better outcomes compared to lectures alone. However, the lack of reinforcement and interactivity limits their ability to sustain behavioral change over time.\r\n\r\nConclusion:\r\nTraditional oral health education remains valuable for raising awareness and initiating behavioral improvement. Nonetheless, its limited long-term effectiveness underscores the need for innovative, technology-assisted, and behaviorally reinforced educational strategies.\r\n\r\nKeywords: Oral health education, traditional methods, oral hygiene, behavior change, young adults', 'VIDYEN/1000002', '26-10-2025', 2, 0),
(103, 'VIDYEN/1000162', 'AUT000103', 'Blended Learning Strategies in Dental Education', 'Oral Presentations for research submission', 'Narrative Review', 'The Flipped Classroom ', 'Flip, classroom, learning, education ', 'A flipped classroom is an educational model that inverts traditional teaching methods, prioritizing active, student-centered learning during class time. Instead of listening to a lecture in class and completing homework at home, students engage with instructional materials like videos, readings, or podcasts individually, before class begins. Class time is then used for collaborative projects, problem-solving, and in-depth discussions with peers and the teacher. \r\nKey aspects include:\r\nBefore class: Students learn new concepts and terminology at their own pace using materials provided by the teacher.\r\nDuring class: The teacher acts as a facilitator or guide, addressing student questions, offering personalized assistance, and creating engaging activities that apply the pre-learned information.\r\nOutcome: This approach fosters deeper understanding, critical thinking, and enhanced student engagement by converting the passive reception of information into an interactive, dynamic learning environment.', 'VIDYEN/1000162', '26-10-2025', 2, 0),
(104, 'VIDYEN/1000151', 'AUT000104', 'Technology-Driven Innovations in Dental Education', 'Oral Presentations for Speciality Research', 'Narrative Review', 'Determining Adult Dental Age and Sex Using CBCT Images in Forensic Odontology: A Scoping Review', 'Forensic odontology, CBCT, adult dental age estimation, sex determination.', 'Objective :\r\nThis systematic review aims to evaluate the current methodologies and accuracy of using Cone Beam Computed Tomography (CBCT) for determining dental age and sex in adult individuals within the scope of forensic odontology.\r\n\r\nMethods :\r\nA comprehensive literature search was conducted across multiple databases including PubMed, Science direct, iCite and Web of Science to identify studies published up to February 2025 that utilized CBCT for adult dental age estimation and sex determination. Inclusion criteria focused on peer-reviewed original research involving human adult samples, CBCT-based assessments, and forensic applications. Data extraction and quality assessment were conducted using PRISMA guidelines.\r\n\r\nResults :\r\nThe review identified 23 eligible studies demonstrating the increasing adoption of CBCT in forensic protocols due to its high-resolution, three-dimensional imaging capability. Techniques such as pulp/tooth volume ratio analysis, mandibular measurements, and maxillary sinus morphology were found to be commonly employed. The majority of studies reported moderate to high accuracy in age estimation and sex determination, with variations based on population, tooth selection, and analysis method.\r\n\r\nConclusion :\r\nCBCT imaging shows significant potential as a non-invasive and reliable tool for adult dental age and sex estimation in forensic odontology. However, standardization of methodologies and further validation across diverse populations are necessary to enhance its forensic applicability.', 'VIDYEN/1000151', '27-10-2025', 2, 0),
(105, 'VIDYEN/1000197', 'AUT000105', 'Speciality Presentation', 'Oral Presentations for Speciality Research', 'Original Research Medical / Dental Education', 'BIOACTIVE MORINGA CHIPS: A NEW FRONTIER IN LOCAL DRUG  DELIVERY', 'local drug delivery, moringa, periodontitis', 'Introduction: Chronic inflammation and oxidative stress are central to periodontal disease\r\npathogenesis. Traditional treatment approaches often face limitations in targeting specific\r\nsites and sustaining therapeutic drug concentrations. This study involves development of a\r\nnovel periodontal chip incorporating Moringa oleifera, known for its antioxidant,\r\nantimicrobial, and anti-inflammatory properties.\r\nObjective: To design, formulate and evaluate the antibacterial efficacy of a periodontal chip\r\nincorporated with Moringa oleifera extract and conduct in-vitro characterization of the chip\r\nsuch that it could be used as a local drug delivery system as an adjunct to periodontal\r\ntreatment.\r\nMethodology: A crude Moringa extract was prepared using Soxhlet extraction. 0.2g medium\r\nmolecular weight chitosan was dissolved in 10ml of glacial acetic acid, then mixed with\r\n100L glycerol and 5mL of varying concentrations of the Moringa extract (500, 750, and\r\n1000 mg/mL). Chips were prepared by casting/solvent evaporation, cut to 5x5mm, and\r\nsubjected to physicochemical analysis and tested for bioactivity against P. gingivalis.\r\nResults and Conclusion: The Moringa chip exhibited antibacterial activity in dose\r\ndependent manner against P. gingivalis which has been suggested as a keystone pathogen and\r\nshowed good bioavailability as a local drug delivery system. Further clinical studies are\r\nneeded to confirm these findings', 'VIDYEN/1000197', '27-10-2025', 2, 0),
(106, 'VIDYEN/1000188', 'AUT000106', 'Speciality Presentation', 'Oral Presentations for Speciality Research', 'Original Research Medical / Dental Education', 'Assessment of Knowledge, Awareness and attitude about Oral, Breast and Cervical cancer among Higher Secondary Students of  Mangaluru Taluk, Karnataka, - A Cross-Sectional Study ', 'knowldge, Attitude, Awareness of Oral, Breast, cervical cancer school children', 'Back ground\r\nChildren are key agents of change, making it essential to educate students about cancer risk factors and prevention. Existing studies primarily focus on individual cancers and involve limited school populations, with no school-based programs addressing all three common cancers in India. There is a need for broader awareness initiatives targeting all students to promote cancer prevention and extend knowledge to families and communities.\r\nAim\r\nThe aim is to assess knowledge, awareness, and attitude about cancer among the higher secondary school children by training them through school-based educational program\r\nMethodology\r\nA cross-sectional study was conducted in all CBSE schools of Mangaluru Taluk involving around 5000 students from 8th–10th standard, using a census sampling method. Cancer awareness sessions comprising four validated modules (general, oral, breast, and cervical cancer) were delivered by trained health professionals. A semi-structured, expert-validated questionnaire were shared before and after the sessions. Data collected were statistically analysed to assess knowledge, awareness, and attitude improvement following the program. \r\n\r\nResults\r\n20 schools participated in the training programme which included 5000 children. The result revealed significant improvement among school children in awareness, knowledge and attitude about cancer.\r\nConclusion\r\nModular training programme is found to be effective among school children for implementation of the cancer awareness\r\n', 'VIDYEN/1000188', '27-10-2025', 2, 0),
(107, 'VIDYEN/1000184', 'AUT000107', 'Speciality Presentation', 'Oral Presentations for research submission', 'Interprofessional Research', 'Sex Determination formulae using anatomical landmarks in radiology', 'gender determination , mandible, lateral cephalogram, forensic identification. ', 'Aim: Sex determination is one of the main sources of identification of an individual in medico-legal cases. Mandible is a practical element to analyse in fragmented bones because it is more durable than the other bones . Aim of this study is to assess the validity of a unique formulae derived for sex determination  using 2 bony landmarks among Mangalore population\r\nMethodology -  A retrospective study was conducted on the Manglorean population using 80 lateral cephalograms (40 males and 40 females). Two mandibular measurements i.e.height of mental symphysis (HMS) and height of ascending ramus (HAR) was carried out on a modified version of Ionesuc’s formulae  and subjected to discriminate analysis. \r\nResult - The derived formulae accurately identified 80% of the subjects as males and females respectively.\r\n', 'VIDYEN/1000184', '27-10-2025', 2, 0),
(108, 'VIDYEN/1000202', 'AUT000108', 'Speciality Presentation', 'Oral Presentations for research submission', 'Original Research Medical / Dental Education', 'Assessing the oral health disparities among psychiatric patients ;A single center cross sectional study in Mangalore India    ', 'Mental helath,oral health ,dental caries', 'Introduction; mental health significantly influences overall wellbeing with psychiatric disorders imposing a global health burden .oral diseases nearaly 3.5 billion people .Objective; This study examined the relationship between mental health disorders and oral health among psychiatric patients compared to non psychiatric individuals. methods; A cross sectional study was conducted on 65 psychiatric patients aged over 18 years ,residing in rehabilitation center for at least 6 months. Results ; males showed higher calculus score ,females had deeper pockets,psychosis patients had higher dental caries and missing teeth .bipolar disorder patients had fewer caries. conclusion ;Integrated  care approaches including oral health assessments ,are essentail  to improve the overall health and quality of life in psychiatric patients.', '', '27-10-2025', 2, 0),
(109, 'VIDYEN/1000040', 'AUT000109', 'Artificial Intelligence in dentistry', 'Posters', 'Narrative Review', 'Eye Mapping: Innovative Technique for Precise Iris Positioning in Prosthetic Eye', 'Artificial intelligence,  Eye prosthesis, Iris positioning, Patient ', 'Introduction- A congenital defect, irreversible damage, a painful blind eye, sympathetic ophthalmia, or the requirement for histological confirmation of a suspected illness can all result in the absence or loss of an eye. In such circumstances, meticulous preoperative, surgical, and prosthetic planning using a multidisciplinary approach is imperative for successful rehabilitation. \r\nObjective—An “augmented reality tool” is instigated in the field of maxillofacial prosthesis for an accurate and precise iris positioning in a prosthetic eye.\r\nMethods—A new technique using an augmented reality filter, which provides precise mapping of facial landmarks, has been introduced in iris positioning. A smartphone device (S22) was used, and an artificial intelligence (AI)-generated Instagram application was unfurled, and an augmented reality filter was instituted. The filter available in the application made it possible to see and confirm the iris shell\'s location in three dimensions from various angles. According to the iris placement, it was accomplished. \r\nResult—Accurate positioning of the iris was done using an augmented reality tool, which is popular, easily accessible, less technique sensitive, and can be performed with the slightest efforts in small clinical setups. Relating to the patient, it was a comfortable, economic, and trouble-free procedure.\r\nConclusion—Iris positioning stands as one of the crucial steps in fabricating a patient-specific ocular prosthesis. In the present case report, iris positioning was done using artificial intelligence, which provided an excellent aesthetic result, and patient compliance was met with satisfaction.\r\n', 'VIDYEN/1000040', '04-11-2025', 0, 0),
(110, 'VIDYEN/1000028', 'AUT000110', 'Speciality Presentation', 'Oral Presentations for research submission', 'Original Research Medical / Dental Education', 'Does Blueprinting affect the academic outcome of Undergraduate dental students in theory examinations of Oral and Maxillofacial surgery?', 'Dental Education, Blueprinting, Continuous Internal Examination, Graduate Dental Education', 'Background: Blueprinting in theory exam paper setting is not a widely implemented practice in dental education. Although well known the applications of it has not been studied in dental education.\r\nAim: The present study aimed to evaluate the efficacy of blueprinting in the internal assessment examinations in the subject of Oral and Maxillofacial Surgery in the final year of study in the Bachelor of Dental Surgery.\r\nMaterials and Methods: This was a combined prospective and retrospective study conducted on subjects comprising of 100 in Group A (Prospective Arm) and 100 in Group B (Retrospective Arm) students appearing for three continuous internal assessment examinations. Group A was provided with the topic wise weightage 1 month prior to the exams. Group B had appeared for the exam in the past academic year without the process of blueprinting.\r\nResults: Group A Outnumbered Group B in terms of number of passing students across all exams. Group A outperforms Group B in overall performance across the three exams. Significant difference was seen in the 3rd exam, where Group A scored significantly higher in both individual sections and total marks.\r\nDiscussion: Blueprinting starts to influence objective-type questions as students become accustomed to the structured approach. In subsequent exams, analytical and written expression improves markedly under blueprinting. These trends reflect how different question formats benefit differently from blueprinting, with subjective questions showing the greatest gain due to the structured preparation. As long answer questions require deeper cognitive engagement, the structured alignment provided by blueprinting aids students in formulating more coherent answers.\r\nConclusion: Blueprinting emerges as a pedagogically sound and practically feasible assessment strategy. It demonstrates a positive impact on academic performance promoting higher-order thinking and equitable evaluation which justifies its usage in health education.\r\n', 'VIDYEN/1000028', '04-11-2025', 0, 0),
(111, 'VIDYEN/1000001', 'AUT000111', 'Blended Learning Strategies in Dental Education', 'Oral Presentations for research submission', 'Narrative Review', 'sasadsd', 'sdcdscdscs', 'ew  veg hjkcvdbfgnmh', 'VIDYEN/1000001', '17-04-2026', 2, 0),
