INSERT INTO `pre_conference` (`id`, `registration_id`, `pre_confernce_id`, `sub_theme`, `title_paper`, `keywords`, `abstract_background`, `abstract_rationale`, `abstract_objective`, `abstract_outcome`, `abstract_structure`, `abstract_description`, `participant`, `participant_description`, `max_participants`, `workshop_overview`, `created_by`, `created_on`, `status`, `flag`) VALUES
(1, 'VIDYEN/1000001', 'PRE0001', 'Assessment and Feedback in Hybrid Learning Models', 'Item Analysis', 'Item', 'Assessment drives learning, and ensuring that assessment tools are valid and reliable is critical in dental education. Item analysis offers educators a scientific method to evaluate the quality of multiple-choice questions (MCQs) and other test items. By identifying flawed or ambiguous questions and understanding item difficulty and discrimination, educators can improve both examinations and student learning outcomes.', 'Despite frequent use of MCQs, many dental faculty are unfamiliar with methods of analyzing item performance. This workshop will bridge the gap by providing hands-on training in item analysis, empowering educators to enhance the quality of their assessments and promote evidence-based evaluation.', 'Define key concepts in item analysis (difficulty index, discrimination index, distractor efficiency).\r\n\r\nInterpret item analysis statistics to identify strengths and weaknesses in test items.\r\n\r\nRevise and improve MCQs based on item analysis results.\r\n\r\nApply item analysis to real test data in dentistry.', 'Enhanced ability to design and evaluate valid, reliable MCQs.\r\n\r\nIncreased awareness of the role of item analysis in improving student learning and assessment quality.\r\n\r\nParticipants will leave with practical skills and resources for immediate application in their own institutions.', 'Activity	Time	Description\r\nActivity 1 – Introduction & Concepts	30 min	Interactive lecture on principles of item analysis with dental examples.\r\nActivity 2 – Hands-on Practice	75 min	Participants work in groups to analyze sample MCQ data (difficulty, discrimination, distractors) using spreadsheets/software. Facilitator-guided discussion.\r\nActivity 3 – Application & Reflection	45 min	Groups revise flawed MCQs based on analysis results, share feedback, and discuss how to implement item analysis in their own settings.\r\nWrap-up & Q&A	30 min	Summary of key points, sharing of best practices, take-home resources.', 'Item analysis is an essential quality assurance tool in dental assessments.\r\n\r\nUnderstanding test item performance improves both teaching and learning.\r\n\r\nParticipants gain hands-on experience and resources for immediate application.', 'Dental faculty, postgraduate students involved in teaching, and assessment coordinators interested in improving the quality of examinations.', 'Item analysis is an essential quality assurance tool in dental assessments.\r\n\r\nUnderstanding test item performance improves both teaching and learning.\r\n\r\nParticipants gain hands-on experience and resources for immediate application.', '30 (to ensure interactivity and adequate facilitator attention).', 'Unlock the power of assessment with our Pre-Conference Workshop on Item Analysis in Dentistry. This engaging, hands-on session is designed for dental educators and postgraduate students who want to improve the quality and fairness of their examinations. Through interactive discussions and real-world examples, participants will explore the principles of item analysis, including difficulty index, discrimination index, and distractor efficiency. You’ll practice analyzing sample MCQ data, identify strengths and weaknesses in test items, and learn how to refine flawed questions to enhance validity and reliability. By the end of this three-hour workshop, you will take home practical tools and strategies that can be immediately applied in your own teaching and assessment settings. Join us to transform the way you evaluate learning and ensure your examinations truly reflect student competence!', 'VIDYEN/1000001', '03-10-2025', 2, 0),
(2, 'VIDYEN/1000124', 'PRE0002', 'Enhancing Student Engagement in Hybrid Learning Environments', 'Interactive Teaching-Learning Methods to Promote Student Engagement', 'Active Learning, Student Engagement, Interactive Methods, Technology-Enhanced Learning, Medical Education', 'In health professions education, promoting student engagement is central to effective learning and competency development. Traditional lecture-based teaching often limits active participation, critical thinking, and collaboration. This workshop addresses these gaps by introducing and demonstrating innovative, interactive teaching-learning methods that foster engagement, improve retention, and enhance student-centered learning in dental and medical education.', 'Educators in the health sciences increasingly recognize the need to shift from teacher-centered to learner-centered approaches. However, many faculty members lack exposure to practical, technology-supported interactive strategies. This workshop provides hands-on experience with evidence-based teaching methods—such as flipped classrooms, gamification, and collaborative learning—that are adaptable to both classroom and clinical settings, thereby empowering educators to transform their teaching practice.', 'By the end of the session, participants will be able to:\r\n\r\nDescribe the principles and importance of student engagement in medical and dental education.\r\n\r\nImplement technology-enabled interactive teaching-learning strategies.\r\n\r\nDesign and facilitate flipped classroom\r\n\r\nCreate engaging asynchronous learning environments using digital tools.\r\n\r\nIntegrate active learning methods into their own teaching sessions.', 'Participants will leave with practical experience and ready-to-use strategies to promote engagement in their teaching sessions. They will also develop confidence in designing interactive activities using digital platforms, resulting in improved learner motivation and better learning outcomes.', 'The workshop will begin with an introductory icebreaker and orientation to set expectations and familiarize participants with the concept of student engagement.\r\nThe first session will explore the principles and practical aspects of active learning, emphasizing strategies that encourage participation, questioning, and critical thinking.\r\nThe second session will focus on the flipped classroom approach and demonstrate how educators can use digital platforms such as Google Classroom to support asynchronous learning and continuous engagement outside the classroom.\r\nAfter the lunch break, participants will engage in a session on interactive teaching-learning methods using technology. This session will include demonstrations of online tools, quizzes, polls, and gamification elements to enhance real-time engagement.\r\nThe final session will be a hands-on group activity where participants design and present short interactive teaching modules, followed by a reflection and feedback discussion to consolidate learning.', 'Participants will engage in group discussions, collaborative exercises, and digital tool demonstrations and practice. The workshop emphasizes active involvement through peer learning, problem-solving. Reflection and feedback will reinforce learning outcomes and encourage implementation in participants’ own institutions.', 'Faculty members from medical, dental, and allied health sciences; postgraduate educators; curriculum planners; and teaching-learning committee members interested in enhancing student engagement through innovative, practical approaches.', 'Evidence-based, ready-to-use strategies for engaging students.\r\n\r\nPractical exposure to flipped, and gamified learning methods.\r\n\r\nFamiliarity with technology platforms that support interactive teaching.\r\n\r\nRenewed enthusiasm and confidence in applying active learning.', '30 participants (to ensure individual attention and effective participation).', 'Transform your teaching—engage, inspire, and innovate!\r\nJoin our interactive, hands-on workshop “Interactive Teaching-Learning Methods to Promote Student Engagement” designed for educators in medical, dental, and allied health sciences. Facilitated by Dr. Vinutha Shankar M S, Dr. Naveen Kumar I, Dr. Lokheshwar S, and Dr. Ashwini K Shetty, this dynamic session introduces practical strategies like flipped classrooms, gamification, and collaborative methods to enhance learner participation and motivation. Through guided demonstrations, peer activities, and reflective discussions, participants will explore innovative, technology-supported approaches to make teaching more engaging and impactful. Ideal for faculty eager to create learner-centered classrooms and bring energy and interaction back into their sessions.', 'VIDYEN/1000124', '16-10-2025', 2, 0),
(3, 'VIDYEN/1000103', 'PRE0003', 'Enhancing Student Engagement in Hybrid Learning Environments', 'Student Academic Guidance and Enrichment (SAGE) – Master class workshop for academicians', 'SAGE, SANCS, SPECS', 'Student Academic Guidance and Enrichment (SAGE) is a structured, student-centric approach aimed at fostering holistic academic growth, enhancing learning outcomes, and providing individualized mentorship. With diverse student populations entering higher education, it is essential to have a systematic framework that identifies Students Needing Additional Curricular Support/ Students Provided with Enriched Curricular Support (SNACS/SPECS), and facilitate them with targeted strategies', 'Academic institutions often face the challenge of balancing standardized curricula with individualized student support. This workshop will demonstrate how SAGE can be operationalized through a structured approach, systematic student profiling, and customized academic strategies. Participants will gain hands-on experience in designing and implementing support mechanisms that address varied academic trajectories, learning needs, and personal aspirations of students.', 'By the end of the workshop, participants will be able to:\r\n•\r\nIdentify and categorize students’ SNACS (Students Needing Additional Curricular Support) and SPECS (Students Provided with Enriched Curricular Support).\r\n•\r\nTo assess individual learning needs and areas of interest.\r\n•\r\nDevelop and implement evidence-based support strategies tailored to student profiles.\r\n•\r\nDesign a replicable institutional framework for ongoing student academic guidance and enrichment.', 'Participants will create a draft blueprint of a SAGE framework suitable for their institution.\r\n•\r\nA sample template for student profiling and needs assessment will be developed.\r\n•\r\nParticipants will learn to match academic enrichment strategies to individual student needs.\r\n•\r\nNetworking and collaboration among educators for sharing best practices in student guidance', 'Introduction and Orientation (20 minutes)\r\n•\r\nOverview of SAGE concept and objectives.\r\n•\r\nImportance of structured academic guidance in higher education.\r\nIdentification of SNACS/SPECS (40 minutes)\r\n•\r\nConceptual framework and practical application.\r\n•\r\nTools for gathering student data\r\n•\r\nActivity: Small group work on hypothetical student cases.\r\nIdentification of Individual Student Learning Needs/Areas of Interest (40 minutes)\r\n•\r\nMapping academic performance, learning styles, and extracurricular interests.\r\n•\r\nUse of diagnostic assessments and reflective conversations.\r\n•\r\nActivity: Developing a student profile template.\r\nImplementation of Support Strategies (40 minutes)\r\n•\r\nAcademic support: peer tutoring, remedial sessions, advanced learning opportunities.\r\n•\r\nPersonal support: counselling, time management, motivation enhancement.\r\n•\r\nInstitutional support: resource access, research exposure, career workshops.\r\n•\r\nActivity: Designing a support plan for a case scenario.\r\nWrap-up and Way Forward (30 minutes)\r\n•\r\nPresentation of group outputs.\r\n•\r\nKey takeaways and feedback.', 'Introduction and Orientation (20 minutes)\r\n•\r\nOverview of SAGE concept and objectives.\r\n•\r\nImportance of structured academic guidance in higher education.\r\nIdentification of SNACS/SPECS (40 minutes)\r\n•\r\nConceptual framework and practical application.\r\n•\r\nTools for gathering student data\r\n•\r\nActivity: Small group work on hypothetical student cases.\r\nIdentification of Individual Student Learning Needs/Areas of Interest (40 minutes)\r\n•\r\nMapping academic performance, learning styles, and extracurricular interests.\r\n•\r\nUse of diagnostic assessments and reflective conversations.\r\n•\r\nActivity: Developing a student profile template.\r\nImplementation of Support Strategies (40 minutes)\r\n•\r\nAcademic support: peer tutoring, remedial sessions, advanced learning opportunities.\r\n•\r\nPersonal support: counselling, time management, motivation enhancement.\r\n•\r\nInstitutional support: resource access, research exposure, career workshops.\r\n•\r\nActivity: Designing a support plan for a case scenario.\r\nWrap-up and Way Forward (30 minutes)\r\n•\r\nPresentation of group outputs.\r\n•\r\nKey takeaways and feedback.', 'Academician from any discipline interested in student wellness/mentoring and policy makers at the institute level for the students support center', 'Academician from any discipline interested in student wellness/mentoring and policy makers at the institute level for the students support center', '30', 'Student Academic Guidance and Enrichment (SAGE) is a structured, student-centric approach aimed at fostering holistic academic growth, enhancing learning outcomes, and providing individualized mentorship. With diverse student populations entering higher education, it is essential to have a systematic framework that identifies Students Needing Additional Curricular Support/ Students Provided with Enriched Curricular Support (SNACS/SPECS), and facilitate them with targeted strategies', 'VIDYEN/1000103', '16-10-2025', 2, 0),
(4, 'VIDYEN/1000079', 'PRE0004', 'Faculty Development for Effective Hybrid Teaching', 'Bridging Minds, Building Care: The Power of Interprofessional Education and Practice.', 'IPP,IPE collaboration', 'Interprofessional Education (IPE) and Practice (IPP) are essential components of contemporary healthcare education, ensuring collaborative, patient-centered care. Despite growing awareness, many health professional programs continue to train students in isolation, limiting their ability to communicate and cooperate effectively across disciplines. This workshop aims to bridge this gap by providing educators and practitioners with the knowledge, tools, and experiential learning strategies needed to design, implement, and assess IPE activities. The rationale lies in preparing healthcare students and faculty to foster teamwork, mutual respect, and shared decision-making, ultimately improving health outcomes and system efficiency.', 'Healthcare today is increasingly complex, requiring collaborative approaches that transcend traditional professional boundaries. Fragmented care delivery often results from inadequate understanding of other professions’ roles, limited communication, and lack of coordinated teamwork. Interprofessional Education (IPE) provides a transformative framework that prepares future and current healthcare professionals to work collaboratively, ensuring patient-centered, efficient, and holistic care.\r\nDespite its recognized importance, IPE is often underrepresented in health professions curricula and continuing education programs. Many educators and practitioners express uncertainty about how to effectively design, implement, and assess interprofessional learning experiences. This pre-conference workshop aims to bridge this gap by providing participants with evidence-based strategies, experiential learning opportunities, and adaptable models for integrating IPE and Interprofessional Practice (IPP) within academic and clinical settings.\r\nThrough interactive activities, case-based discussions, and role-play simulations, participants will experience firsthand how collaborative learning enhances communication, respect, and shared decision-making among healthcare professionals. The workshop also aligns with global calls from the World Health Organization (WHO) and the National Health Policy of India advocating for interprofessional collaboration to strengthen healthcare systems and improve patient outcomes.\r\nUltimately, this workshop seeks to build capacity among educators, clinicians, and students to foster a culture of teamwork—transforming “siloed” education into a connected, compassionate, and collaborative healthcare practice.\r\n\r\n', 'By the end of this workshop, participants will be able to:\r\n1.	Define key principles and competencies of Interprofessional Education and Collaborative Practice.\r\n2.	Describe effective educational models for integrating IPE into curricula.\r\n3.	Demonstrate interactive teaching methods (e.g., case-based learning, role-play, simulation).\r\n4.	Design a brief IPE activity or module relevant to their own institutional context.\r\n5.	Reflect on challenges and facilitators for implementing IPE in their settings.\r\n', 'Participants will:\r\n•	Gain practical strategies for promoting interprofessional collaboration.\r\n•	Develop an action plan to integrate IPE within their programs.\r\n•	Strengthen communication and leadership skills for facilitating multidisciplinary teamwork.\r\n•	Build a network of like-minded educators committed to advancing collaborative healthcare education.\r\n\r\n\r\n', 'Structure of the Workshop (3 hours total)\r\n1. Welcome and Introduction (25minutes)\r\n•	RILPS GOOGLE FORM -Readiness for Interprofessional Learning Scale (RIPLS), a tool used in healthcare education to evaluate students\' attitudes and readiness for interprofessional education (IPE). \r\n•	Introduction and overview of the workshop purpose.\r\n•	Brief icebreaker activity: “Who’s on your team?” – participants introduce their profession and share one key role they play in patient care.\r\n•	Outline of agenda, learning objectives, and expected outcomes.\r\n 2. Setting the Context: Keynote & Mini-Lecture (25 minutes)\r\n•	Short talk on “Interprofessional Education and Collaborative Practice in Healthcare”.\r\n•	Need for IPE in improving patient outcomes.\r\n•	Global and Indian perspectives (WHO Framework, Health Professions Education Reforms).\r\n•	Common barriers and strategies to overcome them.\r\n3. Interactive Activity 1, 2, 3 \r\n•	Case Based learning (40 minutes).\r\n•	Role Play\r\n•	Problem Based Learning\r\n4.Interactive Activity 2 – Design a brief IPE activity or module relevant to their own institutional context. (15 minutes)\r\nSteps:\r\n1.	Identify the patient’s problem(s).\r\n2.	List learning issues related to diagnosis, management, and interprofessional collaboration.\r\n3.	Plan a coordinated care approach.\r\n•	Facilitators guide and record key insights on a whiteboard or shared digital pad. \r\n5.Barriers and Challenges Discussion on chat box or verbal (20 Minutes)\r\n6.Future Directions and Innovations in Interprofessional Education (IPE) and Practice (IPP) (15Minutes)\r\n7. Reflection and Group Discussion (20 minutes)\r\n•	Guided reflection questions:\r\nWhat did you learn about teamwork and communication?\r\nHow did interprofessional collaboration affect patient care planning?\r\nWhat barriers did you experience during the activities?\r\n•	Participants share insights; facilitator summarizes key takeaways.\r\n 6. Wrap-Up and Take-Home Messages (15 minutes)\r\n•	Summary of key concepts from all sessions.\r\n•	Participants complete short feedback through Google form /reflection form.\r\n', 'Structure of the Workshop (3 hours total)\r\n1. Welcome and Introduction (25minutes)\r\n•	RILPS GOOGLE FORM -Readiness for Interprofessional Learning Scale (RIPLS), a tool used in healthcare education to evaluate students\' attitudes and readiness for interprofessional education (IPE). \r\n•	Introduction and overview of the workshop purpose.\r\n•	Brief icebreaker activity: “Who’s on your team?” – participants introduce their profession and share one key role they play in patient care.\r\n•	Outline of agenda, learning objectives, and expected outcomes.\r\n 2. Setting the Context: Keynote & Mini-Lecture (25 minutes)\r\n•	Short talk on “Interprofessional Education and Collaborative Practice in Healthcare”.\r\n•	Need for IPE in improving patient outcomes.\r\n•	Global and Indian perspectives (WHO Framework, Health Professions Education Reforms).\r\n•	Common barriers and strategies to overcome them.\r\n3. Interactive Activity 1, 2, 3 \r\n•	Case Based learning (40 minutes).\r\n•	Role Play\r\n•	Problem Based Learning\r\n4.Interactive Activity 2 – Design a brief IPE activity or module relevant to their own institutional context. (15 minutes)\r\nSteps:\r\n1.	Identify the patient’s problem(s).\r\n2.	List learning issues related to diagnosis, management, and interprofessional collaboration.\r\n3.	Plan a coordinated care approach.\r\n•	Facilitators guide and record key insights on a whiteboard or shared digital pad. \r\n5.Barriers and Challenges Discussion on chat box or verbal (20 Minutes)\r\n6.Future Directions and Innovations in Interprofessional Education (IPE) and Practice (IPP) (15Minutes)\r\n7. Reflection and Group Discussion (20 minutes)\r\n•	Guided reflection questions:\r\nWhat did you learn about teamwork and communication?\r\nHow did interprofessional collaboration affect patient care planning?\r\nWhat barriers did you experience during the activities?\r\n•	Participants share insights; facilitator summarizes key takeaways.\r\n 6. Wrap-Up and Take-Home Messages (15 minutes)\r\n•	Summary of key concepts from all sessions.\r\n•	Participants complete short feedback through Google form /reflection form.\r\n7. Optional Post-Workshop Networking (Informal – 10 minutes)\r\n•	Open networking time for participants to connect and exchange ideas on future collaborative teaching or research initiatives. \r\n', '•	Faculty from health professions (dentistry, medicine, nursing, physiotherapy, pharmacy, public health, etc.)\r\n•	Clinical educators, curriculum planners, and postgraduate students interested in teaching and implementing IPE and want to practice IPP.\r\n', '•	Interprofessional collaboration enhances patient outcomes and professional satisfaction.\r\n•	IPE and IPP are achievable within existing curricula through structured teamwork activities.\r\n•	Role-play, simulation, and problem-based learning are powerful tools for IPE delivery.\r\n•	Effective communication and shared leadership are the backbone of collaborative practice.\r\n•	Each participant leaves with a draft plan or idea to implement IPE and turn into IPP at their institution.\r\n', '30-35', 'Join us for an engaging, hands-on workshop — “Bridging Minds, Building Care: The Power of Interprofessional Education and Practice.” This interactive session brings together educators and practitioners from various health disciplines to explore strategies that enhance teamwork, communication, and patient-centered care. Through real-world cases, role-plays, and collaborative design activities, participants will experience the essence of interprofessional learning and discover practical approaches to embed it into their teaching and practice. Whether you’re new to IPE/IPP or seeking to refine existing initiatives, this workshop will communicate with innovative tools, actionable insights, and a professional network dedicated to transforming healthcare education', 'VIDYEN/1000079', '23-10-2025', 2, 0),
