INSERT INTO `workshop` (`id`, `registration_id`, `workshop_id`, `sub_theme`, `title_paper`, `keywords`, `abstract_background`, `abstract_rationale`, `abstract_objective`, `abstract_outcome`, `abstract_structure`, `abstract_description`, `participant`, `participant_description`, `max_participants`, `workshop_overview`, `created_by`, `created_on`, `status`, `flag`) VALUES
(1, 'VIDYEN/1000063', 'WRK0001', 'Quality assurance in dentistry and its applications in Blended Learning', 'Enhancing Health Care Using PROMs, PREMs, and Experiences in Dentistry', 'PREM, PROM SATISFACTION ASSESSMENT', 'Delivering truly patient-centered dental care requires more than clinical outcomes alone. Patient-Reported Outcome Measures (PROMs) and Patient-Reported Experience Measures (PREMs) capture what matters most to patients, their quality of life, treatment results, and care experiences. By integrating these measures, dental teams can improve communication, tailor care, and strengthen service quality.', 'Patient-Reported Outcome Measures (PROMs) and Patient-Reported Experience Measures (PREMs) put the patient’s voice at the center of dental care. By capturing both outcomes and experiences, dental teams can improve treatment quality, enhance satisfaction, and make care truly patient-centered. Integrating these tools equips practitioners with actionable insights, supports evidence-based practice, and aligns dentistry with modern health care standards.', 'This interactive workshop will:\r\n•	Introduce PROMs and PREMs and their value in dentistry.\r\n•	Explore practical tools and methods to capture patient voices.\r\n•	Develop skills to analyze and apply data for better care decisions.\r\n•	Provide strategies to overcome barriers to implementation.\r\n•	Support participants in creating actionable plans for their own settings.\r\n', 'Participants will leave with:\r\n•	A clear understanding of PROMs/PREMs in dental practice.\r\n•	Practical experience applying tools to cases and data.\r\n•	Enhanced skills in patient-centered communication.\r\n•	Concrete action plans for integrating PROMs/PREMs in practice, education, or research.\r\n', 'Why: To improve patient-centered care in dentistry by leveraging insights from PROMs, PREMs, and patient experiences.\r\nWho: Dental professionals, clinic managers, researchers, and policymakers seeking actionable strategies to enhance care quality.\r\nHow: Through interactive sessions, real-world case studies, and practical exercises demonstrating data collection, interpretation, and integration into clinical practice.\r\nWhat: Participants will learn to measure outcomes meaningful to patients, translate feedback into care improvements, and foster a culture of continuous quality enhancement. This workshop equips attendees with tools to make dental care more responsive, effective, and patient-focused.', ':00 – 0:10 | Welcome & Introduction (10 min)\r\n\r\nBrief overview of patient-centered care in dentistry.\r\n\r\nObjectives of the workshop: why PROMs, PREMs, and patient experiences matter.\r\n\r\nIcebreaker: quick poll or show of hands on current use of patient feedback in practice.\r\n\r\n0:10 – 0:35 | Understanding PROMs and PREMs (25 min)\r\n\r\nInteractive mini-lecture: definitions, differences, and real-world examples.\r\n\r\nGroup discussion: participants share experiences or challenges with patient feedback.\r\n\r\nQuick quiz or interactive activity: matching outcomes to patient priorities.\r\n\r\n0:35 – 1:00 | Collecting Meaningful Patient Data (25 min)\r\n\r\nCase study walkthrough: effective PROM/PREM implementation in a dental clinic.\r\n\r\nDemonstration: survey tools, interview techniques, digital platforms.\r\n\r\nSmall-group exercise: design a short patient feedback questionnaire for a hypothetical clinic scenario.\r\n\r\n1:00 – 1:15 | Break (15 min)\r\n\r\n1:15 – 1:40 | Interpreting and Applying Patient Feedback (25 min)\r\n\r\nHands-on exercise: analyze sample PROM/PREM data to identify improvement areas.\r\n\r\nDiscussion: translating insights into actionable strategies for clinical practice.\r\n\r\nTips for overcoming common barriers (time, resources, staff engagement).\r\n\r\n1:40 – 1:55 | Fostering a Patient-Centered Culture (15 min)\r\n\r\nInteractive brainstorm: ways to integrate feedback into everyday clinic routines.\r\n\r\nRole-play scenarios: staff-patient interactions that reflect patient-centered principles.\r\n\r\n1:55 – 2:00 | Wrap-Up & Takeaways (5 min)\r\n\r\nKey lessons recap.\r\n\r\nProvide a toolkit/handout with sample surveys, data interpretation guides, and improvement templates.\r\n\r\nQ&A and next steps', '•	Dental practitioners (general dentists, specialists)\r\n•	Dental hygienists and therapists\r\n•	Dental educators and researchers\r\n•	Dental students and trainees\r\n•	Health care administrators and quality improvement managers\r\n', 'Patient-centered dental care is built on listening, measuring, and acting on what truly matters to patients. By effectively collecting and using PROMs, PREMs, and patient experiences, you can transform feedback into meaningful improvements, enhance care quality, and foster a culture where patients feel heard, valued, and empowered', '20', 'Join us for an interactive workshop designed to help dental professionals, clinic managers, researchers, and policymakers elevate patient-centered care. Learn how to harness Patient-Reported Outcome Measures (PROMs), Patient-Reported Experience Measures (PREMs), and real patient feedback to make care more responsive, effective, and meaningful.\r\n\r\nThrough engaging sessions, real-world case studies, and hands-on exercises, you’ll discover practical ways to collect, interpret, and apply patient insights in your practice. Gain the skills to measure outcomes that matter most to patients, translate feedback into actionable improvements, and foster a culture of continuous quality enhancement.\r\n\r\nBy the end of this 2-hour workshop, you’ll leave equipped with tools and strategies to make dental care truly patient-focused, driving better experiences, improved satisfaction, and stronger trust in your clinic or organization.', 'VIDYEN/1000063', '03-10-2025', 2, 0),
(2, 'VIDYEN/1000058', 'WRK0002', 'Faculty Development for Effective Hybrid Teaching', 'The Mindful Map: The Art & Science of Mind Mapping in Health Professions Education', 'Mind Mapping, Medical Education, Visual Learning, Creative Teaching, Active Learning', 'Health professions education often involves complex, layered concepts that challenge learners to connect theory with practice. Mind mapping, a visual thinking tool, promotes active learning by enabling learners to organize, integrate, and retain information more effectively. It has proven benefits in enhancing creativity, critical thinking, and long-term memory.', 'Faculty members are increasingly exploring innovative teaching methods to make learning more student-centered and concept-driven. This workshop introduces mind mapping as an evidence-based and versatile technique that can be applied to curriculum design, classroom teaching, and assessment to improve learner engagement and understanding.', 'By the end of the workshop, participants will be able to:\r\n\r\n1. Explain the principles and cognitive basis of mind mapping.\r\n\r\n2. Create effective mind maps for teaching and learning complex topics.\r\n\r\n3. Integrate mind mapping strategies into lesson planning and student assessments.\r\n\r\n4. Facilitate students’ use of mind maps to promote self-directed learning.', 'Participants will gain both conceptual understanding and practical skills in designing and implementing mind maps to enhance the learning experience in health sciences education.', 'Activity 1: Setting the Stage - Different types of Mindmaps\r\nActivity 2: Demonstration & Hands-on of creating mindmap using online tools\r\nActivity 3: Application & Reflection\r\nWrap-up & Feedback', 'Activity 1: Setting the Stage - Different types of Mindmaps - 40 mins\r\nActivity 2: Demonstration & Hands-on of creating mindmap using online tools - 1 hour\r\nActivity 3: Application & Reflection  - 10 mins\r\nWrap-up & Feedback - 10 mins', 'Faculty members  involved in health professions education who wish to explore innovative, visual approaches to teaching and learning.', 'Participants will leave with:\r\n\r\nA clear understanding of how mind maps enhance learning and retention.\r\n\r\nPractical templates and examples to apply in their teaching.\r\n\r\nFirst-hand experience in creating and assessing mind maps.', '25 participants (to ensure individual attention and active engagement).', 'Unlock the power of visual thinking with The Mindful Map! This interactive workshop introduces mind mapping as a creative, evidence-based teaching tool that transforms how students learn and retain complex medical concepts. Through guided demonstrations, hands-on exercises, and reflective discussions, participants will learn how to design and apply mind maps for classroom teaching, self-directed learning, and assessment. Whether you’re new to the concept or looking to refine your methods, this session will help you turn abstract ideas into meaningful, memorable visuals. Join us to experience how the art and science of mind mapping can make teaching and learning in health professions education more engaging, organized, and impactful.', 'VIDYEN/1000058', '11-10-2025', 2, 0),
